        residue_family_rare_adapter_max_abs_by_pair: dict[str, float] | None = None,
        residue_family_rare_adapter_uncertainty_threshold_by_pair: (
            dict[str, float] | None
        ) = None,
        factor_bin_rare_adapter_keys: tuple[str, ...] = (),
        factor_bin_rare_adapter_max_abs_by_key: dict[str, float] | None = None,
        factor_bin_rare_adapter_center_by_key: dict[str, float] | None = None,
        factor_bin_rare_adapter_width_by_key: dict[str, float] | None = None,
        factor_bin_rare_adapter_uncertainty_threshold_by_key: (
            dict[str, float] | None
        ) = None,
