def _bioemu_physics_bin_audit(
    prediction_frame: pd.DataFrame,
    physics_atlas_frame: pd.DataFrame,
    *,
    coordinate_names: tuple[str, ...],
    family_names: tuple[str, ...],
    audit_name: str,
) -> pd.DataFrame:
    columns = [
        "audit_name",
        "split",
        "coordinate_name",
        "coordinate_bin",
        "atom_family",
        "row_count",
        "ccc",
        "mae",
        "bias",
        "rmse",
        "std_ratio",
        "mean_abs_coordinate",
        "mean_reliability",
        "mean_uncertainty",
        "mean_sidecar_target",
        "mean_sidecar_residual",
        "mean_family_tangent_delta",
        "mean_family_chart_bias_delta",
        "mean_mechanism_signed_bias_conflict_delta",
        "mean_mechanism_signed_cancellation_delta",
        "mean_mechanism_signed_router_delta",
        "mean_mechanism_signed_override_delta",
    ]
    merged = _bioemu_physics_prediction_merge(prediction_frame, physics_atlas_frame)
    if merged.empty:
        return pd.DataFrame(columns=columns)
    merged = merged.loc[
        merged["coordinate_name"].astype(str).isin(coordinate_names)
        & merged["atom_family"].astype(str).isin(family_names)
    ].copy()
    if merged.empty:
        return pd.DataFrame(columns=columns)
    frames = [merged]
    all_frame = merged.copy()
    all_frame["split"] = "ALL"
    frames.append(all_frame)
    merged = pd.concat(frames, ignore_index=True)
    rows: list[dict[str, Any]] = []
    for (split_name, coordinate_name, atom_family), coord_group in merged.groupby(
        ["split", "coordinate_name", "atom_family"],
        dropna=False,
    ):
        coord_group = coord_group.copy()
        coord_group["coordinate_bin"] = _quantile_bin_labels(
            coord_group["coordinate_value"]
        )
        for coordinate_bin, group in coord_group.groupby("coordinate_bin", dropna=False):
            target = group["target_value"].astype(float).to_numpy()
            pred = group["predicted_value"].astype(float).to_numpy()
            residual = pred - target
            target_std = float(np.std(target)) if len(target) else float("nan")
            pred_std = float(np.std(pred)) if len(pred) else float("nan")
            rows.append(
                {
                    "audit_name": audit_name,
                    "split": str(split_name),
                    "coordinate_name": str(coordinate_name),
                    "coordinate_bin": str(coordinate_bin),
                    "atom_family": str(atom_family),
                    "row_count": int(len(group)),
                    "ccc": _safe_ccc_np(pred, target) if len(group) >= 2 else float("nan"),
                    "mae": float(np.mean(np.abs(residual))) if len(residual) else float("nan"),
                    "bias": float(np.mean(residual)) if len(residual) else float("nan"),
                    "rmse": (
                        float(np.sqrt(np.mean(np.square(residual))))
                        if len(residual)
                        else float("nan")
                    ),
                    "std_ratio": (
                        pred_std / target_std
                        if math.isfinite(pred_std) and target_std > 1.0e-9
                        else float("nan")
                    ),
                    "mean_abs_coordinate": _safe_mean(group["coordinate_value"].abs()),
                    "mean_reliability": _safe_mean(
                        group.get("reliability", pd.Series(dtype=float))
                    ),
                    "mean_uncertainty": _safe_mean(
                        group.get("uncertainty", pd.Series(dtype=float))
                    ),
                    "mean_sidecar_target": _safe_mean(
                        group.get("sidecar_target_value", pd.Series(dtype=float))
                    ),
                    "mean_sidecar_residual": _safe_mean(
                        group.get("sidecar_residual", pd.Series(dtype=float))
                    ),
                    "mean_family_tangent_delta": _safe_mean(
                        group.get("family_tangent_delta", pd.Series(dtype=float))
                    ),
                    "mean_family_chart_bias_delta": _safe_mean(
                        group.get("family_chart_bias_delta", pd.Series(dtype=float))
                    ),
                    "mean_mechanism_signed_bias_conflict_delta": _safe_mean(
                        group.get(
                            "mechanism_signed_bias_conflict_delta",
                            pd.Series(dtype=float),
                        )
                    ),
                    "mean_mechanism_signed_cancellation_delta": _safe_mean(
                        group.get(
                            "mechanism_signed_cancellation_delta",
                            pd.Series(dtype=float),
                        )
                    ),
                    "mean_mechanism_signed_router_delta": _safe_mean(
                        group.get("mechanism_signed_router_delta", pd.Series(dtype=float))
                    ),
                    "mean_mechanism_signed_override_delta": _safe_mean(
                        group.get(
                            "mechanism_signed_override_delta",
                            pd.Series(dtype=float),
                        )
                    ),
                }
            )
    if not rows:
        return pd.DataFrame(columns=columns)
    return pd.DataFrame(rows, columns=columns).sort_values(
        ["split", "coordinate_name", "coordinate_bin", "atom_family"],
        kind="stable",
    )


def _bioemu_physics_prediction_merge(
    prediction_frame: pd.DataFrame,
    physics_atlas_frame: pd.DataFrame,
) -> pd.DataFrame:
    required_prediction = {
        "split",
        "entity_uid",
        "target_id",
        "atom_family",
        "target_value",
        "predicted_value",
    }
    required_physics = {
        "split",
        "entity_uid",
        "target_id",
        "atom_family",
        "coordinate_name",
        "coordinate_value",
    }
    if (
        prediction_frame.empty
        or physics_atlas_frame.empty
        or not required_prediction.issubset(prediction_frame.columns)
        or not required_physics.issubset(physics_atlas_frame.columns)
    ):
        return pd.DataFrame()

    predictions = prediction_frame.copy()
    if "is_masked_holdout" in predictions:
        masked = predictions.loc[predictions["is_masked_holdout"].astype(bool)].copy()
        if not masked.empty:
            predictions = masked
    predictions["target_value"] = pd.to_numeric(
        predictions["target_value"],
        errors="coerce",
    )
    predictions["predicted_value"] = pd.to_numeric(
        predictions["predicted_value"],
        errors="coerce",
    )
    predictions = predictions.dropna(subset=["target_value", "predicted_value"])
    if predictions.empty:
        return pd.DataFrame()
    predictions["residual"] = predictions["predicted_value"] - predictions["target_value"]
    family_scale = (
        predictions.groupby("atom_family", dropna=False)["target_value"]
        .std(ddof=0)
        .replace(0.0, np.nan)
        .to_dict()
    )
    predictions["residual_z"] = [
        float(residual) / max(float(family_scale.get(family, np.nan)), 1.0e-6)
        if math.isfinite(float(family_scale.get(family, np.nan)))
        else float("nan")
        for family, residual in zip(
            predictions["atom_family"].astype(str),
            predictions["residual"].astype(float),
            strict=False,
        )
    ]

    physics = physics_atlas_frame.copy()
    if "is_masked_holdout" in physics:
        masked_physics = physics.loc[physics["is_masked_holdout"].astype(bool)].copy()
        if not masked_physics.empty:
            physics = masked_physics
    physics["coordinate_value"] = pd.to_numeric(
        physics["coordinate_value"],
        errors="coerce",
    )
    physics = physics.dropna(subset=["coordinate_value"])
    if physics.empty:
        return pd.DataFrame()

    merge_keys = ["split", "entity_uid", "target_id", "atom_family"]
    prediction_columns = [
        *merge_keys,
        "target_value",
        "predicted_value",
        "residual",
        "residual_z",
    ]
    for optional in (
        "family_tangent_delta",
        "family_chart_bias_delta",
        "mechanism_signed_bias_conflict_delta",
        "mechanism_signed_cancellation_delta",
        "mechanism_signed_router_delta",
        "mechanism_signed_override_delta",
    ):
        if optional in predictions.columns:
            prediction_columns.append(optional)
    merged = physics.merge(
        predictions[prediction_columns],
        on=merge_keys,
        how="inner",
    )
    for column in [
        "coordinate_value",
        "reliability",
        "uncertainty",
        "chart_probability",
        "sidecar_target_value",
        "sidecar_residual",
        "family_tangent_delta",
        "family_chart_bias_delta",
        "mechanism_signed_bias_conflict_delta",
        "mechanism_signed_cancellation_delta",
        "mechanism_signed_router_delta",
        "mechanism_signed_override_delta",
    ]:
        if column in merged.columns:
            merged[column] = pd.to_numeric(merged[column], errors="coerce")
    return merged.dropna(subset=["target_value", "predicted_value", "coordinate_value"])


def _write_bioemu_cprime_chart_calibration_probe(
    *,
    prediction_frame: pd.DataFrame,
    atlas_frame: pd.DataFrame,
    arrays_dir: Path,
    plots_dir: Path,
) -> dict[str, str]:
    """Write train-fit/validation-applied C' chart calibration diagnostics."""

    summary_frame, calibrated_frame = _bioemu_cprime_chart_calibration_frames(
        prediction_frame,
        atlas_frame,
    )
    artifacts: dict[str, str] = {}
    artifacts.update(
        _write_table_pair(
            summary_frame,
            arrays_dir / "bioemu_cprime_chart_calibration_probe.parquet",
        )
    )
    artifacts.update(
        _write_table_pair(
            calibrated_frame,
            arrays_dir / "bioemu_cprime_chart_calibrated_predictions.parquet",
        )
    )
    _render_cprime_chart_calibration_probe_plot(
        summary_frame,
        plots_dir / "bioemu_cprime_chart_calibration_probe.png",
    )
    return artifacts


