def _bioemu_family_calibration_strategy_frames(
    prediction_frame: pd.DataFrame,
    atlas_frame: pd.DataFrame,
    *,
    family_names: tuple[str, ...] = CHEMICAL_SHIFT_FAMILIES,
    min_delta_ccc: float = 0.002,
) -> tuple[pd.DataFrame, pd.DataFrame]:
    """Select baseline, chart-bin, or scale-up affine calibration per family."""

    summary_columns = [
        "atom_family",
        "selected_strategy",
        "selected_coordinate_name",
        "baseline_ccc",
        "chart_ccc",
        "affine_ccc",
        "selected_ccc",
        "delta_ccc",
        "baseline_mae",
        "selected_mae",
        "baseline_bias",
        "selected_bias",
        "baseline_std_ratio",
        "selected_std_ratio",
        "reason",
    ]
    prediction_columns = [
        "split",
        "entity_uid",
        "target_id",
        "atom_family",
        "target_value",
        "predicted_value",
        "calibrated_predicted_value",
        "selected_strategy",
        "selected_coordinate_name",
        "calibration_delta",
        "baseline_residual",
        "calibrated_residual",
    ]
    required = {
        "split",
        "entity_uid",
        "target_id",
        "atom_family",
        "target_value",
        "predicted_value",
    }
    if prediction_frame.empty or not required.issubset(prediction_frame.columns):
        return (
            pd.DataFrame(columns=summary_columns),
            pd.DataFrame(columns=prediction_columns),
        )

    chart_summary, chart_predictions = _bioemu_family_chart_calibration_frames(
        prediction_frame,
        atlas_frame,
        family_names=family_names,
    )
    affine_summary, affine_predictions = _bioemu_family_affine_calibration_frames(
        prediction_frame,
        family_names=family_names,
    )
    predictions = prediction_frame.copy()
    if "is_masked_holdout" in predictions:
        masked = predictions.loc[predictions["is_masked_holdout"].astype(bool)].copy()
        if not masked.empty:
            predictions = masked
    predictions = predictions.loc[predictions["split"].astype(str).eq("val")].copy()
    if predictions.empty:
        predictions = prediction_frame.copy()
        if "is_masked_holdout" in predictions:
            predictions = predictions.loc[predictions["is_masked_holdout"].astype(bool)].copy()
        predictions = predictions.loc[~predictions["split"].astype(str).eq("train")].copy()
    predictions["target_value"] = pd.to_numeric(
        predictions["target_value"],
        errors="coerce",
    )
    predictions["predicted_value"] = pd.to_numeric(
        predictions["predicted_value"],
        errors="coerce",
    )
    predictions = predictions.dropna(subset=["target_value", "predicted_value"])

    rows: list[dict[str, Any]] = []
    strategy_rows: list[dict[str, Any]] = []
    for family in family_names:
        family_baseline = predictions.loc[
            predictions["atom_family"].astype(str).eq(family)
        ].copy()
        if family_baseline.empty:
            continue
        baseline_metrics = _family_calibration_metrics(
            family_baseline,
            "predicted_value",
        )
        candidates = [
            {
                "strategy": "baseline",
                "coordinate_name": "",
                "ccc": baseline_metrics["ccc"],
                "mae": baseline_metrics["mae"],
                "bias": baseline_metrics["bias"],
                "std_ratio": baseline_metrics["std_ratio"],
                "frame": _baseline_strategy_frame(family_baseline),
            }
        ]
        chart_candidates = chart_summary.loc[
            chart_summary.get("atom_family", pd.Series(dtype=str)).astype(str).eq(family)
            & chart_summary.get("calibration_kind", pd.Series(dtype=str))
            .astype(str)
            .ne("baseline")
        ].copy()
        if not chart_candidates.empty:
            chart_best = chart_candidates.sort_values(
                ["calibrated_ccc", "delta_ccc"],
                ascending=False,
                kind="stable",
            ).iloc[0]
            coord = str(chart_best.get("coordinate_name", ""))
            chart_frame = chart_predictions.loc[
                chart_predictions.get("atom_family", pd.Series(dtype=str))
                .astype(str)
                .eq(family)
                & chart_predictions.get("coordinate_name", pd.Series(dtype=str))
                .astype(str)
                .eq(coord)
            ].copy()
            candidates.append(
                {
                    "strategy": "chart_bin",
                    "coordinate_name": coord,
                    "ccc": float(chart_best.get("calibrated_ccc", float("nan"))),
                    "mae": float(chart_best.get("calibrated_mae", float("nan"))),
                    "bias": float(chart_best.get("calibrated_bias", float("nan"))),
                    "std_ratio": baseline_metrics["std_ratio"],
                    "frame": chart_frame,
                }
            )
        affine_candidates = affine_summary.loc[
            affine_summary.get("atom_family", pd.Series(dtype=str)).astype(str).eq(family)
        ].copy()
        if not affine_candidates.empty:
            affine_row = affine_candidates.iloc[0]
            affine_frame = affine_predictions.loc[
                affine_predictions.get("atom_family", pd.Series(dtype=str))
                .astype(str)
                .eq(family)
            ].copy()
            candidates.append(
                {
                    "strategy": "scale_up_affine",
                    "coordinate_name": "",
                    "ccc": float(affine_row.get("calibrated_ccc", float("nan"))),
                    "mae": float(affine_row.get("calibrated_mae", float("nan"))),
                    "bias": float(affine_row.get("calibrated_bias", float("nan"))),
                    "std_ratio": float(
                        affine_row.get("calibrated_std_ratio", float("nan"))
                    ),
                    "frame": affine_frame,
                }
            )

        valid_candidates = [
            candidate
            for candidate in candidates
            if math.isfinite(float(candidate.get("ccc", float("nan"))))
        ]
        selected = max(valid_candidates, key=lambda item: float(item["ccc"]))
        if float(selected["ccc"]) < baseline_metrics["ccc"] + float(min_delta_ccc):
            selected = candidates[0]
            reason = "baseline_kept_small_or_negative_gain"
        else:
            reason = "best_validation_ccc_with_min_delta"
        selected_frame = selected["frame"].copy()
        if not selected_frame.empty:
            selected_frame["selected_strategy"] = str(selected["strategy"])
            selected_frame["selected_coordinate_name"] = str(
                selected.get("coordinate_name", "")
            )
            strategy_rows.extend(
                selected_frame[
                    [
                        column
                        for column in prediction_columns
                        if column in selected_frame.columns
                    ]
                ].to_dict("records")
            )
        chart_ccc = next(
            (
                float(candidate["ccc"])
                for candidate in candidates
                if candidate["strategy"] == "chart_bin"
            ),
            float("nan"),
        )
        affine_ccc = next(
            (
                float(candidate["ccc"])
                for candidate in candidates
                if candidate["strategy"] == "scale_up_affine"
            ),
            float("nan"),
        )
        rows.append(
            {
                "atom_family": family,
                "selected_strategy": selected["strategy"],
                "selected_coordinate_name": selected.get("coordinate_name", ""),
                "baseline_ccc": baseline_metrics["ccc"],
                "chart_ccc": chart_ccc,
                "affine_ccc": affine_ccc,
                "selected_ccc": float(selected["ccc"]),
                "delta_ccc": float(selected["ccc"]) - baseline_metrics["ccc"],
                "baseline_mae": baseline_metrics["mae"],
                "selected_mae": float(selected["mae"]),
                "baseline_bias": baseline_metrics["bias"],
                "selected_bias": float(selected["bias"]),
                "baseline_std_ratio": baseline_metrics["std_ratio"],
                "selected_std_ratio": float(selected["std_ratio"]),
                "reason": reason,
            }
        )
    return (
        pd.DataFrame(rows, columns=summary_columns),
        pd.DataFrame(strategy_rows, columns=prediction_columns),
    )


def _baseline_strategy_frame(frame: pd.DataFrame) -> pd.DataFrame:
    """Return baseline prediction rows with the calibrated schema."""

    output = frame.copy()
    output["calibrated_predicted_value"] = output["predicted_value"].astype(float)
    output["calibration_delta"] = 0.0
    output["baseline_residual"] = (
        output["predicted_value"].astype(float)
        - output["target_value"].astype(float)
    )
    output["calibrated_residual"] = output["baseline_residual"].astype(float)
    return output


def _bioemu_family_affine_calibration_frames(
    prediction_frame: pd.DataFrame,
    *,
    family_names: tuple[str, ...] = CHEMICAL_SHIFT_FAMILIES,
) -> tuple[pd.DataFrame, pd.DataFrame]:
    """Fit per-family affine maps on train and apply them to validation rows."""

    summary_columns = [
        "atom_family",
        "fit_split",
        "eval_split",
        "fit_rows",
        "eval_rows",
        "slope",
        "intercept",
        "baseline_ccc",
        "calibrated_ccc",
        "delta_ccc",
        "baseline_mae",
        "calibrated_mae",
        "delta_mae",
        "baseline_bias",
        "calibrated_bias",
        "delta_abs_bias",
        "baseline_std_ratio",
        "calibrated_std_ratio",
        "target_std",
        "pred_std",
        "calibrated_pred_std",
        "calibration_kind",
    ]
    calibrated_columns = [
        "split",
        "entity_uid",
        "target_id",
        "atom_family",
        "target_value",
        "predicted_value",
        "calibrated_predicted_value",
        "calibration_delta",
        "baseline_residual",
        "calibrated_residual",
    ]
    required = {
        "split",
        "entity_uid",
        "target_id",
        "atom_family",
        "target_value",
        "predicted_value",
    }
    if prediction_frame.empty or not required.issubset(prediction_frame.columns):
        return (
            pd.DataFrame(columns=summary_columns),
            pd.DataFrame(columns=calibrated_columns),
        )
    frame = prediction_frame.copy()
    if "is_masked_holdout" in frame:
        masked = frame.loc[frame["is_masked_holdout"].astype(bool)].copy()
        if not masked.empty:
            frame = masked
    frame["target_value"] = pd.to_numeric(frame["target_value"], errors="coerce")
    frame["predicted_value"] = pd.to_numeric(frame["predicted_value"], errors="coerce")
    frame = frame.dropna(subset=["atom_family", "target_value", "predicted_value"])
    if frame.empty:
        return (
            pd.DataFrame(columns=summary_columns),
            pd.DataFrame(columns=calibrated_columns),
        )

    summary_rows: list[dict[str, Any]] = []
    calibrated_rows: list[dict[str, Any]] = []
    for family in family_names:
        family_frame = frame.loc[frame["atom_family"].astype(str).eq(family)].copy()
        fit = family_frame.loc[family_frame["split"].astype(str).eq("train")].copy()
        eval_split = "val" if (family_frame["split"].astype(str) == "val").any() else ""
        eval_frame = (
            family_frame.loc[family_frame["split"].astype(str).eq(eval_split)].copy()
            if eval_split
            else family_frame.loc[~family_frame["split"].astype(str).eq("train")].copy()
        )
        if eval_split == "" and not eval_frame.empty:
            eval_split = "non_train"
        if len(fit) < 2 or len(eval_frame) < 2:
            continue

        slope, intercept = _fit_family_affine_map(
            fit["predicted_value"].astype(float).to_numpy(),
            fit["target_value"].astype(float).to_numpy(),
        )
        eval_frame["calibrated_predicted_value"] = (
            slope * eval_frame["predicted_value"].astype(float) + intercept
        )
        base_metrics = _family_calibration_metrics(eval_frame, "predicted_value")
        calibrated_metrics = _family_calibration_metrics(
            eval_frame,
            "calibrated_predicted_value",
        )
        summary_rows.append(
            {
                "atom_family": family,
                "fit_split": "train",
                "eval_split": eval_split,
                "fit_rows": int(len(fit)),
                "eval_rows": int(len(eval_frame)),
                "slope": float(slope),
                "intercept": float(intercept),
                "baseline_ccc": base_metrics["ccc"],
                "calibrated_ccc": calibrated_metrics["ccc"],
                "delta_ccc": calibrated_metrics["ccc"] - base_metrics["ccc"],
                "baseline_mae": base_metrics["mae"],
                "calibrated_mae": calibrated_metrics["mae"],
                "delta_mae": calibrated_metrics["mae"] - base_metrics["mae"],
                "baseline_bias": base_metrics["bias"],
                "calibrated_bias": calibrated_metrics["bias"],
                "delta_abs_bias": abs(calibrated_metrics["bias"])
                - abs(base_metrics["bias"]),
                "baseline_std_ratio": base_metrics["std_ratio"],
                "calibrated_std_ratio": calibrated_metrics["std_ratio"],
                "target_std": base_metrics["target_std"],
                "pred_std": base_metrics["pred_std"],
                "calibrated_pred_std": calibrated_metrics["pred_std"],
                "calibration_kind": "train_family_scale_up_affine",
            }
        )
        eval_frame["calibration_delta"] = (
            eval_frame["calibrated_predicted_value"].astype(float)
            - eval_frame["predicted_value"].astype(float)
        )
        eval_frame["baseline_residual"] = (
            eval_frame["predicted_value"].astype(float)
            - eval_frame["target_value"].astype(float)
        )
        eval_frame["calibrated_residual"] = (
            eval_frame["calibrated_predicted_value"].astype(float)
            - eval_frame["target_value"].astype(float)
        )
        calibrated_rows.extend(
            eval_frame[
                [
                    "split",
                    "entity_uid",
                    "target_id",
                    "atom_family",
                    "target_value",
                    "predicted_value",
                    "calibrated_predicted_value",
                    "calibration_delta",
                    "baseline_residual",
                    "calibrated_residual",
                ]
            ].to_dict("records")
        )

    summary_frame = pd.DataFrame(summary_rows, columns=summary_columns)
    calibrated_frame = pd.DataFrame(calibrated_rows, columns=calibrated_columns)
    return summary_frame, calibrated_frame


def _fit_family_affine_map(predicted: np.ndarray, target: np.ndarray) -> tuple[float, float]:
    """Fit a scale-up affine map without allowing extra posterior collapse."""

    predicted = np.asarray(predicted, dtype=np.float64)
    target = np.asarray(target, dtype=np.float64)
    finite = np.isfinite(predicted) & np.isfinite(target)
    predicted = predicted[finite]
    target = target[finite]
    if predicted.size < 2:
        return 1.0, 0.0
    pred_mean = float(np.mean(predicted))
    target_mean = float(np.mean(target))
    pred_var = float(np.mean(np.square(predicted - pred_mean)))
    covariance = float(np.mean((predicted - pred_mean) * (target - target_mean)))
    if pred_var <= 1.0e-12:
        return 1.0, target_mean - pred_mean
    slope = covariance / pred_var
    slope = float(np.clip(slope, 1.0, 4.0))
    intercept = target_mean - slope * pred_mean
    return slope, float(intercept)


def _family_calibration_metrics(frame: pd.DataFrame, predicted_column: str) -> dict[str, float]:
    """Return validation metrics for one family calibration probe."""

    target = frame["target_value"].astype(float).to_numpy()
    predicted = frame[predicted_column].astype(float).to_numpy()
    finite = np.isfinite(target) & np.isfinite(predicted)
    target = target[finite]
    predicted = predicted[finite]
    if target.size == 0:
        return {
            "ccc": float("nan"),
            "mae": float("nan"),
            "bias": float("nan"),
            "target_std": float("nan"),
            "pred_std": float("nan"),
            "std_ratio": float("nan"),
        }
    residual = predicted - target
    target_std = float(np.std(target))
    pred_std = float(np.std(predicted))
    return {
        "ccc": _safe_ccc_np(predicted, target),
        "mae": float(np.mean(np.abs(residual))),
        "bias": float(np.mean(residual)),
        "target_std": target_std,
        "pred_std": pred_std,
        "std_ratio": pred_std / target_std if target_std > 1.0e-12 else float("nan"),
    }


def _bioemu_family_chart_calibration_frames(
    prediction_frame: pd.DataFrame,
    atlas_frame: pd.DataFrame,
    *,
    family_names: tuple[str, ...] = CHEMICAL_SHIFT_FAMILIES,
) -> tuple[pd.DataFrame, pd.DataFrame]:
    """Run the leakage-safe chart calibration probe independently per family."""

    summary_frames: list[pd.DataFrame] = []
    calibrated_frames: list[pd.DataFrame] = []
    for family in family_names:
        family_prediction = prediction_frame.loc[
            prediction_frame.get("atom_family", pd.Series(dtype=str)).astype(str).eq(family)
        ].copy()
        family_atlas = atlas_frame.loc[
            atlas_frame.get("atom_family", pd.Series(dtype=str)).astype(str).eq(family)
        ].copy()
        if family_prediction.empty or family_atlas.empty:
            continue
        # Reuse the C' implementation by normalizing the family label locally.
        family_prediction["atom_family"] = "C'"
        family_atlas["atom_family"] = "C'"
        summary, calibrated = _bioemu_cprime_chart_calibration_frames(
            family_prediction,
            family_atlas,
        )
        if not summary.empty:
            summary = summary.copy()
            summary.insert(0, "atom_family", family)
            summary_frames.append(summary)
        if not calibrated.empty:
            calibrated = calibrated.copy()
            calibrated["atom_family"] = family
            calibrated_frames.append(calibrated)

    if summary_frames:
        summary_frame = pd.concat(summary_frames, ignore_index=True)
        summary_frame = summary_frame.sort_values(
            ["atom_family", "calibration_kind", "calibrated_ccc", "coordinate_name"],
            ascending=[True, True, False, True],
            kind="stable",
        )
    else:
        summary_frame = pd.DataFrame(
            columns=[
                "atom_family",
                "coordinate_name",
                "fit_split",
                "eval_split",
                "fit_rows",
                "eval_rows",
                "bin_count",
                "baseline_ccc",
                "calibrated_ccc",
                "delta_ccc",
                "baseline_mae",
                "calibrated_mae",
                "delta_mae",
                "baseline_bias",
                "calibrated_bias",
                "delta_abs_bias",
                "mean_correction",
                "correction_std",
                "max_abs_correction",
                "mean_abs_applied_correction",
                "calibration_kind",
            ]
        )
    calibrated_frame = (
        pd.concat(calibrated_frames, ignore_index=True)
        if calibrated_frames
        else pd.DataFrame(
            columns=[
                "split",
                "entity_uid",
                "target_id",
                "atom_family",
                "coordinate_name",
                "coordinate_value",
                "chart_bin",
                "target_value",
                "predicted_value",
                "calibrated_predicted_value",
                "calibration_correction",
                "baseline_residual",
                "calibrated_residual",
            ]
        )
    )
    return summary_frame, calibrated_frame


def _bioemu_cprime_chart_calibration_frames(
    prediction_frame: pd.DataFrame,
    atlas_frame: pd.DataFrame,
) -> tuple[pd.DataFrame, pd.DataFrame]:
    """Fit atlas-bin C' residual corrections on train and apply them to val."""

    summary_columns = [
        "coordinate_name",
        "fit_split",
        "eval_split",
        "fit_rows",
        "eval_rows",
        "bin_count",
        "baseline_ccc",
        "calibrated_ccc",
        "delta_ccc",
        "baseline_mae",
        "calibrated_mae",
        "delta_mae",
        "baseline_bias",
        "calibrated_bias",
        "delta_abs_bias",
        "mean_correction",
        "correction_std",
        "max_abs_correction",
        "mean_abs_applied_correction",
        "calibration_kind",
    ]
    calibrated_columns = [
        "split",
        "entity_uid",
        "target_id",
        "atom_family",
        "coordinate_name",
        "coordinate_value",
        "chart_bin",
        "target_value",
        "predicted_value",
        "calibrated_predicted_value",
        "calibration_correction",
        "baseline_residual",
        "calibrated_residual",
    ]
    required_prediction = {
        "split",
        "entity_uid",
        "target_id",
        "atom_family",
        "target_value",
        "predicted_value",
    }
    required_atlas = {
        "split",
        "entity_uid",
        "target_id",
        "atom_family",
        "coordinate_name",
        "coordinate_value",
    }
    if (
        prediction_frame.empty
        or atlas_frame.empty
        or not required_prediction.issubset(prediction_frame.columns)
        or not required_atlas.issubset(atlas_frame.columns)
    ):
        return (
            pd.DataFrame(columns=summary_columns),
            pd.DataFrame(columns=calibrated_columns),
        )

    predictions = prediction_frame.copy()
    predictions = predictions.loc[predictions["atom_family"].astype(str).eq("C'")]
    if "is_masked_holdout" in predictions:
        masked = predictions.loc[predictions["is_masked_holdout"].astype(bool)].copy()
        if not masked.empty:
            predictions = masked
    predictions["target_value"] = pd.to_numeric(
        predictions["target_value"],
        errors="coerce",
    )
    predictions["predicted_value"] = pd.to_numeric(
        predictions["predicted_value"],
        errors="coerce",
    )
    predictions = predictions.dropna(subset=["target_value", "predicted_value"])
    if predictions.empty:
        return (
            pd.DataFrame(columns=summary_columns),
            pd.DataFrame(columns=calibrated_columns),
        )

    atlas = atlas_frame.copy()
    atlas = atlas.loc[atlas["atom_family"].astype(str).eq("C'")]
    if "is_masked_holdout" in atlas:
        atlas_masked = atlas.loc[atlas["is_masked_holdout"].astype(bool)].copy()
        if not atlas_masked.empty:
            atlas = atlas_masked
    atlas["coordinate_value"] = pd.to_numeric(
        atlas["coordinate_value"],
        errors="coerce",
    )
    atlas = atlas.dropna(subset=["coordinate_value"])
    merge_keys = ["split", "entity_uid", "target_id", "atom_family"]
    merged = atlas.merge(
        predictions[
            [
                *merge_keys,
                "target_value",
                "predicted_value",
            ]
        ],
        on=merge_keys,
        how="inner",
    )
    if merged.empty:
        return (
            pd.DataFrame(columns=summary_columns),
            pd.DataFrame(columns=calibrated_columns),
        )

    fit_pool = merged.loc[merged["split"].astype(str).eq("train")].copy()
    eval_split = "val" if (merged["split"].astype(str) == "val").any() else ""
    eval_pool = (
        merged.loc[merged["split"].astype(str).eq(eval_split)].copy()
        if eval_split
        else merged.loc[~merged["split"].astype(str).eq("train")].copy()
    )
    if eval_split == "" and not eval_pool.empty:
        eval_split = "non_train"
    if fit_pool.empty or eval_pool.empty:
        return (
            pd.DataFrame(columns=summary_columns),
            pd.DataFrame(columns=calibrated_columns),
        )

    baseline_metrics = _cprime_calibration_metrics(
        eval_pool.drop_duplicates(subset=merge_keys),
        "predicted_value",
    )
    summary_rows: list[dict[str, Any]] = [
        {
            "coordinate_name": "uncalibrated",
            "fit_split": "train",
            "eval_split": eval_split,
            "fit_rows": int(fit_pool.drop_duplicates(subset=merge_keys).shape[0]),
            "eval_rows": int(eval_pool.drop_duplicates(subset=merge_keys).shape[0]),
            "bin_count": 0,
            "baseline_ccc": baseline_metrics["ccc"],
            "calibrated_ccc": baseline_metrics["ccc"],
            "delta_ccc": 0.0,
            "baseline_mae": baseline_metrics["mae"],
            "calibrated_mae": baseline_metrics["mae"],
            "delta_mae": 0.0,
            "baseline_bias": baseline_metrics["bias"],
            "calibrated_bias": baseline_metrics["bias"],
            "delta_abs_bias": 0.0,
            "mean_correction": 0.0,
            "correction_std": 0.0,
            "max_abs_correction": 0.0,
            "mean_abs_applied_correction": 0.0,
            "calibration_kind": "baseline",
        }
    ]
    calibrated_rows: list[dict[str, Any]] = []
    for coordinate_name in sorted(fit_pool["coordinate_name"].astype(str).unique()):
        fit_coord = fit_pool.loc[
            fit_pool["coordinate_name"].astype(str).eq(coordinate_name)
        ].copy()
        eval_coord = eval_pool.loc[
            eval_pool["coordinate_name"].astype(str).eq(coordinate_name)
        ].copy()
        if fit_coord.empty or eval_coord.empty:
            continue
        edges = _train_quantile_edges(fit_coord["coordinate_value"], bin_count=4)
        fit_coord["chart_bin"] = _assign_quantile_bins_from_edges(
            fit_coord["coordinate_value"],
            edges,
        )
        eval_coord["chart_bin"] = _assign_quantile_bins_from_edges(
            eval_coord["coordinate_value"],
            edges,
        )
        fit_coord["calibration_correction"] = (
            fit_coord["target_value"].astype(float)
            - fit_coord["predicted_value"].astype(float)
        )
        global_correction = float(fit_coord["calibration_correction"].mean())
        correction_by_bin = (
            fit_coord.groupby("chart_bin", dropna=False)["calibration_correction"]
            .mean()
            .to_dict()
        )
        bin_corrections = np.asarray(
            [float(value) for value in correction_by_bin.values()],
            dtype=np.float64,
        )
        eval_coord["calibration_correction"] = [
            float(correction_by_bin.get(str(chart_bin), global_correction))
            for chart_bin in eval_coord["chart_bin"].astype(str)
        ]
        eval_coord["calibrated_predicted_value"] = (
            eval_coord["predicted_value"].astype(float)
            + eval_coord["calibration_correction"].astype(float)
        )
        base_metrics = _cprime_calibration_metrics(eval_coord, "predicted_value")
        calibrated_metrics = _cprime_calibration_metrics(
            eval_coord,
            "calibrated_predicted_value",
        )
        applied_corrections = eval_coord["calibration_correction"].astype(float)
        summary_rows.append(
            {
                "coordinate_name": coordinate_name,
                "fit_split": "train",
                "eval_split": eval_split,
                "fit_rows": int(len(fit_coord)),
                "eval_rows": int(len(eval_coord)),
                "bin_count": int(fit_coord["chart_bin"].nunique(dropna=True)),
                "baseline_ccc": base_metrics["ccc"],
                "calibrated_ccc": calibrated_metrics["ccc"],
                "delta_ccc": calibrated_metrics["ccc"] - base_metrics["ccc"],
                "baseline_mae": base_metrics["mae"],
                "calibrated_mae": calibrated_metrics["mae"],
                "delta_mae": calibrated_metrics["mae"] - base_metrics["mae"],
                "baseline_bias": base_metrics["bias"],
                "calibrated_bias": calibrated_metrics["bias"],
                "delta_abs_bias": abs(calibrated_metrics["bias"])
                - abs(base_metrics["bias"]),
                "mean_correction": float(global_correction),
                "correction_std": float(np.std(bin_corrections))
                if bin_corrections.size
                else 0.0,
                "max_abs_correction": float(np.max(np.abs(bin_corrections)))
                if bin_corrections.size
                else abs(global_correction),
                "mean_abs_applied_correction": float(applied_corrections.abs().mean()),
                "calibration_kind": "train_chart_bin_mean",
            }
        )
        eval_coord["baseline_residual"] = (
            eval_coord["predicted_value"].astype(float)
            - eval_coord["target_value"].astype(float)
        )
        eval_coord["calibrated_residual"] = (
            eval_coord["calibrated_predicted_value"].astype(float)
            - eval_coord["target_value"].astype(float)
        )
        calibrated_rows.extend(
            eval_coord[
                [
                    *merge_keys,
                    "coordinate_name",
                    "coordinate_value",
                    "chart_bin",
                    "target_value",
                    "predicted_value",
                    "calibrated_predicted_value",
                    "calibration_correction",
                    "baseline_residual",
                    "calibrated_residual",
                ]
            ].to_dict("records")
        )

    summary_frame = pd.DataFrame(summary_rows, columns=summary_columns)
    if not summary_frame.empty:
        summary_frame = summary_frame.sort_values(
            ["calibration_kind", "calibrated_ccc", "coordinate_name"],
            ascending=[True, False, True],
            kind="stable",
        )
    calibrated_frame = pd.DataFrame(calibrated_rows, columns=calibrated_columns)
    return summary_frame, calibrated_frame


def _cprime_calibration_metrics(frame: pd.DataFrame, predicted_column: str) -> dict[str, float]:
    """Return C' calibration metrics using predicted - target residual sign."""

    if frame.empty or predicted_column not in frame:
        return {"ccc": float("nan"), "mae": float("nan"), "bias": float("nan")}
    target = frame["target_value"].astype(float).to_numpy()
    predicted = frame[predicted_column].astype(float).to_numpy()
    finite = np.isfinite(target) & np.isfinite(predicted)
    target = target[finite]
    predicted = predicted[finite]
    if target.size == 0:
        return {"ccc": float("nan"), "mae": float("nan"), "bias": float("nan")}
    residual = predicted - target
    return {
        "ccc": _safe_ccc_np(predicted, target),
        "mae": float(np.mean(np.abs(residual))),
        "bias": float(np.mean(residual)),
    }


def _train_quantile_edges(values: pd.Series, bin_count: int = 4) -> np.ndarray | None:
    """Return train-derived quantile edges for leakage-safe chart binning."""

    numeric = pd.to_numeric(values, errors="coerce").dropna().astype(float)
    if numeric.nunique() <= 1:
        return None
    quantiles = np.linspace(0.0, 1.0, max(int(bin_count), 1) + 1)
    edges = np.unique(np.quantile(numeric.to_numpy(), quantiles))
    if edges.size < 2:
        return None
    edges[0] = -np.inf
    edges[-1] = np.inf
    return edges


def _assign_quantile_bins_from_edges(
    values: pd.Series,
    edges: np.ndarray | None,
) -> pd.Series:
    """Assign values to train-derived quantile bins."""

    numeric = pd.to_numeric(values, errors="coerce")
    if edges is None or len(edges) < 2:
        return pd.Series(["Q1"] * len(numeric), index=values.index, dtype="object")
    labels = [f"Q{index + 1}" for index in range(len(edges) - 1)]
    bins = pd.cut(
        numeric,
        bins=edges,
        labels=labels,
        include_lowest=True,
    )
    assigned = pd.Series(bins.astype("object"), index=values.index)
    return assigned.where(assigned.notna(), "Q?").astype(str)


def _render_cprime_chart_calibration_probe_plot(
    summary_frame: pd.DataFrame,
    path: Path,
) -> None:
    """Render validation C' CCC before/after chart-bin calibration."""

    try:
        import matplotlib.pyplot as plt
    except Exception:
        return
    path.parent.mkdir(parents=True, exist_ok=True)
    fig, axis = plt.subplots(figsize=(8, 4.5))
    required = {"coordinate_name", "baseline_ccc", "calibrated_ccc", "delta_ccc"}
    if summary_frame.empty or not required.issubset(summary_frame.columns):
        axis.text(0.5, 0.5, "No C' chart calibration rows", ha="center", va="center")
        axis.set_axis_off()
    else:
        frame = summary_frame.loc[
            summary_frame["coordinate_name"].astype(str).ne("uncalibrated")
        ].copy()
        frame = frame.dropna(subset=["calibrated_ccc"])
        if frame.empty:
            axis.text(0.5, 0.5, "No calibrated C' chart rows", ha="center", va="center")
            axis.set_axis_off()
        else:
            frame = frame.sort_values("calibrated_ccc", ascending=True).tail(12)
            baseline = summary_frame.loc[
                summary_frame["coordinate_name"].astype(str).eq("uncalibrated"),
                "baseline_ccc",
            ]
            baseline_value = (
                float(baseline.iloc[0]) if len(baseline) else float("nan")
            )
            colors = [
                "#059669" if float(delta) >= 0.0 else "#dc2626"
                for delta in frame["delta_ccc"].astype(float)
            ]
            axis.barh(frame["coordinate_name"].astype(str), frame["calibrated_ccc"], color=colors)
            if math.isfinite(baseline_value):
                axis.axvline(
                    baseline_value,
                    color="#111827",
                    linestyle="--",
                    linewidth=1.2,
                    label=f"baseline {baseline_value:.3f}",
                )
                axis.legend(loc="lower right")
            axis.set_xlim(-1.0, 1.0)
            axis.set_xlabel("Validation C' CCC")
            axis.set_ylabel("Atlas coordinate")
            for y_index, (_, row) in enumerate(frame.iterrows()):
                axis.text(
                    min(float(row["calibrated_ccc"]) + 0.015, 0.95),
                    y_index,
                    f"Δ={float(row['delta_ccc']):+.3f}",
                    va="center",
                    fontsize=8,
                )
    axis.set_title("C' chart-bin calibration probe (train fit -> val apply)")
    fig.tight_layout()
    fig.savefig(path, dpi=180)
    plt.close(fig)


def _render_family_chart_calibration_probe_plot(
    summary_frame: pd.DataFrame,
    path: Path,
) -> None:
    """Render best chart-bin calibration gain per atom family."""

    try:
        import matplotlib.pyplot as plt
    except Exception:
        return
    path.parent.mkdir(parents=True, exist_ok=True)
    fig, axes = plt.subplots(1, 2, figsize=(10, 4.5))
    required = {
        "atom_family",
        "coordinate_name",
        "baseline_ccc",
        "calibrated_ccc",
        "delta_ccc",
        "calibration_kind",
    }
    if summary_frame.empty or not required.issubset(summary_frame.columns):
        axes[0].text(0.5, 0.5, "No family calibration rows", ha="center", va="center")
        axes[0].set_axis_off()
        axes[1].set_axis_off()
    else:
        chart_rows = summary_frame.loc[
            summary_frame["calibration_kind"].astype(str).ne("baseline")
        ].copy()
        if chart_rows.empty:
            axes[0].text(0.5, 0.5, "No chart calibration rows", ha="center", va="center")
            axes[0].set_axis_off()
            axes[1].set_axis_off()
        else:
            best_rows = (
                chart_rows.sort_values(
                    ["atom_family", "calibrated_ccc", "delta_ccc"],
                    ascending=[True, False, False],
                    kind="stable",
                )
                .groupby("atom_family", dropna=False)
                .head(1)
                .copy()
            )
            family_order = [
                family
                for family in CHEMICAL_SHIFT_FAMILIES
                if family in set(best_rows["atom_family"].astype(str))
            ]
            extras = sorted(set(best_rows["atom_family"].astype(str)).difference(family_order))
            family_order.extend(extras)
            best_rows["atom_family"] = pd.Categorical(
                best_rows["atom_family"].astype(str),
                categories=family_order,
                ordered=True,
            )
            best_rows = best_rows.sort_values("atom_family")
            x = np.arange(len(best_rows))
            width = 0.36
            axes[0].bar(
                x - width / 2,
                best_rows["baseline_ccc"].astype(float),
                width=width,
                color="#94a3b8",
                label="baseline",
            )
            axes[0].bar(
                x + width / 2,
                best_rows["calibrated_ccc"].astype(float),
                width=width,
                color="#059669",
                label="chart calibrated",
            )
            axes[0].axhline(0.0, color="#cbd5e1", linewidth=0.8)
            axes[0].set_ylim(-1.0, 1.0)
            axes[0].set_xticks(x)
            tick_labels = [
                f"{family}\n({coordinate})"
                for family, coordinate in zip(
                    best_rows["atom_family"].astype(str),
                    best_rows["coordinate_name"].astype(str),
                    strict=False,
                )
            ]
            axes[0].set_xticklabels(tick_labels, rotation=0, fontsize=8)
            axes[0].set_ylabel("Validation CCC")
            axes[0].set_title("Best chart calibration by family")
            axes[0].legend(loc="lower right")
            colors = [
                "#059669" if float(value) >= 0.0 else "#dc2626"
                for value in best_rows["delta_ccc"].astype(float)
            ]
            axes[1].bar(best_rows["atom_family"].astype(str), best_rows["delta_ccc"], color=colors)
            axes[1].axhline(0.0, color="#111827", linewidth=0.9)
            axes[1].set_ylabel("Delta validation CCC")
            axes[1].set_title("Calibration gain")
            axes[1].tick_params(axis="x", rotation=20)
    fig.suptitle("Family chart-bin calibration probe (train fit -> val apply)")
    fig.tight_layout()
    fig.savefig(path, dpi=180)
    plt.close(fig)


