def _render_family_calibration_strategy_probe_plot(
    summary_frame: pd.DataFrame,
    path: Path,
) -> None:
    """Render selected hybrid calibration strategy per atom family."""

    try:
        import matplotlib.pyplot as plt
    except Exception:
        return
    path.parent.mkdir(parents=True, exist_ok=True)
    fig, axes = plt.subplots(1, 2, figsize=(11, 4.5))
    required = {
        "atom_family",
        "baseline_ccc",
        "selected_ccc",
        "delta_ccc",
        "selected_strategy",
    }
    if summary_frame.empty or not required.issubset(summary_frame.columns):
        axes[0].text(
            0.5,
            0.5,
            "No family calibration strategy rows",
            ha="center",
            va="center",
        )
        axes[0].set_axis_off()
        axes[1].set_axis_off()
    else:
        frame = summary_frame.copy()
        order = [
            family
            for family in CHEMICAL_SHIFT_FAMILIES
            if family in set(frame["atom_family"].astype(str))
        ]
        extras = sorted(set(frame["atom_family"].astype(str)).difference(order))
        order.extend(extras)
        frame["atom_family"] = pd.Categorical(
            frame["atom_family"].astype(str),
            categories=order,
            ordered=True,
        )
        frame = frame.sort_values("atom_family")
        x = np.arange(len(frame))
        width = 0.36
        strategy_colors = {
            "baseline": "#94a3b8",
            "chart_bin": "#059669",
            "scale_up_affine": "#2563eb",
        }
        selected_colors = [
            strategy_colors.get(str(strategy), "#7c3aed")
            for strategy in frame["selected_strategy"].astype(str)
        ]
        axes[0].bar(
            x - width / 2,
            frame["baseline_ccc"].astype(float),
            width=width,
            color="#cbd5e1",
            label="baseline",
        )
        axes[0].bar(
            x + width / 2,
            frame["selected_ccc"].astype(float),
            width=width,
            color=selected_colors,
            label="selected",
        )
        axes[0].set_ylim(-1.0, 1.0)
        axes[0].axhline(0.0, color="#cbd5e1", linewidth=0.8)
        axes[0].set_xticks(x)
        coordinate_series = frame.get(
            "selected_coordinate_name",
            pd.Series([""] * len(frame), index=frame.index),
        )
        tick_labels = [
            f"{family}\n{strategy}{':' + coordinate if coordinate else ''}"
            for family, strategy, coordinate in zip(
                frame["atom_family"].astype(str),
                frame["selected_strategy"].astype(str),
                coordinate_series.astype(str),
                strict=False,
            )
        ]
        axes[0].set_xticklabels(tick_labels, rotation=0, fontsize=7)
        axes[0].set_ylabel("Validation CCC")
        axes[0].set_title("Selected calibration strategy")
        axes[0].legend(loc="lower right")
        delta_colors = [
            "#059669" if float(delta) >= 0.0 else "#dc2626"
            for delta in frame["delta_ccc"].astype(float)
        ]
        axes[1].bar(
            frame["atom_family"].astype(str),
            frame["delta_ccc"],
            color=delta_colors,
        )
        axes[1].axhline(0.0, color="#111827", linewidth=0.9)
        axes[1].set_ylabel("Delta validation CCC")
        axes[1].set_title("Hybrid gain over baseline")
        axes[1].tick_params(axis="x", rotation=20)
    fig.suptitle("Family calibration strategy probe (train fit -> val apply)")
    fig.tight_layout()
    fig.savefig(path, dpi=180)
    plt.close(fig)


def _bioemu_family_calibration_strategy_metric_frame(
    prediction_frame: pd.DataFrame,
) -> pd.DataFrame:
    """Summarize baseline versus selected calibration predictions by family."""

    columns = [
        "atom_family",
        "selected_strategy",
        "selected_coordinate_name",
        "rows",
        "baseline_ccc",
        "selected_ccc",
        "delta_ccc",
        "ccc_gap_to_0p95",
        "baseline_mae",
        "selected_mae",
        "delta_mae",
        "baseline_bias",
        "selected_bias",
        "baseline_std_ratio",
        "selected_std_ratio",
    ]
    required = {
        "atom_family",
        "target_value",
        "predicted_value",
        "calibrated_predicted_value",
    }
    if prediction_frame.empty or not required.issubset(prediction_frame.columns):
        return pd.DataFrame(columns=columns)

    frame = prediction_frame.copy()
    for column in ("target_value", "predicted_value", "calibrated_predicted_value"):
        frame[column] = pd.to_numeric(frame[column], errors="coerce")
    frame = frame.dropna(
        subset=["target_value", "predicted_value", "calibrated_predicted_value"]
    )
    if frame.empty:
        return pd.DataFrame(columns=columns)

    def metric_row(label: str, group: pd.DataFrame) -> dict[str, Any]:
        target = group["target_value"].astype(float).to_numpy()
        baseline = group["predicted_value"].astype(float).to_numpy()
        selected = group["calibrated_predicted_value"].astype(float).to_numpy()
        baseline_residual = baseline - target
        selected_residual = selected - target
        target_std = float(np.std(target))
        baseline_std = float(np.std(baseline))
        selected_std = float(np.std(selected))
        strategy_values = (
            group.get("selected_strategy", pd.Series(dtype=str)).astype(str).dropna()
        )
        coordinate_values = (
            group.get("selected_coordinate_name", pd.Series(dtype=str))
            .astype(str)
            .dropna()
        )
        strategy = (
            str(strategy_values.mode().iloc[0])
            if not strategy_values.empty
            else "unknown"
        )
        coordinate = (
            str(coordinate_values.mode().iloc[0])
            if not coordinate_values.empty
            else ""
        )
        if label == "HN/C'":
            strategy = "mixed"
            coordinate = ""
        baseline_ccc = (
            _safe_ccc_np(baseline, target) if len(group) >= 2 else float("nan")
        )
        selected_ccc = (
            _safe_ccc_np(selected, target) if len(group) >= 2 else float("nan")
        )
        delta_ccc = (
            selected_ccc - baseline_ccc
            if math.isfinite(selected_ccc) and math.isfinite(baseline_ccc)
            else float("nan")
        )
        baseline_mae = float(np.mean(np.abs(baseline_residual)))
        selected_mae = float(np.mean(np.abs(selected_residual)))
        return {
            "atom_family": label,
            "selected_strategy": strategy,
            "selected_coordinate_name": coordinate,
            "rows": int(len(group)),
            "baseline_ccc": baseline_ccc,
            "selected_ccc": selected_ccc,
            "delta_ccc": delta_ccc,
            "ccc_gap_to_0p95": max(0.95 - selected_ccc, 0.0)
            if math.isfinite(selected_ccc)
            else float("nan"),
            "baseline_mae": baseline_mae,
            "selected_mae": selected_mae,
            "delta_mae": selected_mae - baseline_mae,
            "baseline_bias": float(np.mean(baseline_residual)),
            "selected_bias": float(np.mean(selected_residual)),
            "baseline_std_ratio": baseline_std / target_std
            if target_std > 1.0e-12
            else float("nan"),
            "selected_std_ratio": selected_std / target_std
            if target_std > 1.0e-12
            else float("nan"),
        }

    rows: list[dict[str, Any]] = []
    for family in CHEMICAL_SHIFT_FAMILIES:
        group = frame.loc[frame["atom_family"].astype(str).eq(family)].copy()
        if group.empty:
            continue
        rows.append(metric_row(family, group))
    target_rows = [row for row in rows if row["atom_family"] in {"HN", "C'"}]
    if target_rows:
        def finite_mean(key: str) -> float:
            values = [
                float(row[key])
                for row in target_rows
                if math.isfinite(float(row.get(key, float("nan"))))
            ]
            return float(np.mean(values)) if values else float("nan")

        baseline_ccc = finite_mean("baseline_ccc")
        selected_ccc = finite_mean("selected_ccc")
        baseline_mae = finite_mean("baseline_mae")
        selected_mae = finite_mean("selected_mae")
        rows.append(
            {
                "atom_family": "HN/C'",
                "selected_strategy": "macro",
                "selected_coordinate_name": "",
                "rows": int(sum(int(row["rows"]) for row in target_rows)),
                "baseline_ccc": baseline_ccc,
                "selected_ccc": selected_ccc,
                "delta_ccc": selected_ccc - baseline_ccc
                if math.isfinite(selected_ccc) and math.isfinite(baseline_ccc)
                else float("nan"),
                "ccc_gap_to_0p95": max(0.95 - selected_ccc, 0.0)
                if math.isfinite(selected_ccc)
                else float("nan"),
                "baseline_mae": baseline_mae,
                "selected_mae": selected_mae,
                "delta_mae": selected_mae - baseline_mae
                if math.isfinite(selected_mae) and math.isfinite(baseline_mae)
                else float("nan"),
                "baseline_bias": finite_mean("baseline_bias"),
                "selected_bias": finite_mean("selected_bias"),
                "baseline_std_ratio": finite_mean("baseline_std_ratio"),
                "selected_std_ratio": finite_mean("selected_std_ratio"),
            }
        )
    return pd.DataFrame(rows, columns=columns)


def _bioemu_recommended_family_metric_frame(
    metric_frame: pd.DataFrame,
    *,
    target_ccc: float = 0.95,
) -> pd.DataFrame:
    """Promote selected readout metrics into the monitor's recommended table."""

    columns = [
        "atom_family",
        "rows",
        "selected_strategy",
        "selected_coordinate_name",
        "baseline_ccc",
        "selected_ccc",
        "recommended_ccc",
        "delta_ccc",
        "raw_gap_to_0p95",
        "recommended_gap_to_0p95",
        "baseline_mae",
        "selected_mae",
        "recommended_mae",
        "delta_mae",
        "baseline_bias",
        "selected_bias",
        "baseline_std_ratio",
        "selected_std_ratio",
        "promote_recommendation",
    ]
    required = {
        "atom_family",
        "baseline_ccc",
        "selected_ccc",
        "baseline_mae",
        "selected_mae",
        "delta_ccc",
    }
    if metric_frame.empty or not required.issubset(metric_frame.columns):
        return pd.DataFrame(columns=columns)
    frame = metric_frame.copy()
    for column in [
        "baseline_ccc",
        "selected_ccc",
        "baseline_mae",
        "selected_mae",
        "delta_ccc",
    ]:
        frame[column] = pd.to_numeric(frame[column], errors="coerce")
    frame["recommended_ccc"] = frame["selected_ccc"]
    frame["recommended_mae"] = frame["selected_mae"]
    frame["raw_gap_to_0p95"] = (float(target_ccc) - frame["baseline_ccc"]).clip(
        lower=0.0
    )
    frame["recommended_gap_to_0p95"] = (
        float(target_ccc) - frame["recommended_ccc"]
    ).clip(lower=0.0)
    frame["promote_recommendation"] = np.where(
        frame["delta_ccc"] > 0.0,
        "promote selected readout calibration",
        "keep baseline readout",
    )
    order = {family: index for index, family in enumerate((*CHEMICAL_SHIFT_FAMILIES, "HN/C'"))}
    frame["_order"] = frame["atom_family"].astype(str).map(order).fillna(len(order))
    frame = frame.sort_values("_order", kind="stable").drop(columns=["_order"])
    return frame[[column for column in columns if column in frame.columns]]


def _render_bioemu_recommended_family_gap_plot(
    metric_frame: pd.DataFrame,
    path: Path,
    *,
    target_ccc: float = 0.95,
) -> None:
    """Render the monitor-first family CCC gap after selected readout calibration."""

    try:
        import matplotlib.pyplot as plt
    except Exception:
        return
    path.parent.mkdir(parents=True, exist_ok=True)
    fig, axes = plt.subplots(1, 2, figsize=(15.5, 5.8))
    required = {
        "atom_family",
        "baseline_ccc",
        "recommended_ccc",
        "delta_ccc",
        "recommended_gap_to_0p95",
    }
    if metric_frame.empty or not required.issubset(metric_frame.columns):
        axes[0].text(
            0.5,
            0.5,
            "No recommended family metrics",
            ha="center",
            va="center",
        )
        axes[0].set_axis_off()
        axes[1].set_axis_off()
    else:
        order = [
            family
            for family in (*CHEMICAL_SHIFT_FAMILIES, "HN/C'")
            if family in set(metric_frame["atom_family"].astype(str))
        ]
        frame = metric_frame.copy()
        frame["atom_family"] = pd.Categorical(
            frame["atom_family"].astype(str),
            categories=order,
            ordered=True,
        )
        frame = frame.sort_values("atom_family", kind="stable")
        x = np.arange(len(frame))
        width = 0.36
        axes[0].bar(
            x - width / 2,
            frame["baseline_ccc"].astype(float),
            width=width,
            color="#94a3b8",
            label="raw posterior mean",
        )
        axes[0].bar(
            x + width / 2,
            frame["recommended_ccc"].astype(float),
            width=width,
            color="#0f766e",
            label="recommended readout",
        )
        axes[0].axhline(
            float(target_ccc),
            color="#111827",
            linestyle="--",
            linewidth=1.2,
        )
        axes[0].set_xticks(x)
        axes[0].set_xticklabels(frame["atom_family"].astype(str), rotation=12, ha="right")
        axes[0].set_ylim(0.0, 1.0)
        axes[0].set_ylabel("Masked validation CCC")
        axes[0].set_title("Recommended readout vs CCC 0.95 target")
        axes[0].legend(loc="lower right", fontsize=8)

        axes[1].bar(
            x,
            frame["recommended_gap_to_0p95"].astype(float),
            color="#f97316",
            alpha=0.82,
        )
        axes[1].set_xticks(x)
        axes[1].set_xticklabels(frame["atom_family"].astype(str), rotation=12, ha="right")
        axes[1].set_ylabel("Remaining CCC gap")
        axes[1].set_title("What remains after recommended readout")
        for xpos, row in zip(x, frame.itertuples(index=False), strict=False):
            axes[0].text(
                xpos,
                min(float(row.recommended_ccc) + 0.025, 0.98),
                f"{float(row.delta_ccc):+.3f}",
                ha="center",
                va="bottom",
                fontsize=8,
            )
            axes[1].text(
                xpos,
                float(row.recommended_gap_to_0p95) + 0.006,
                f"{float(row.recommended_gap_to_0p95):.3f}",
                ha="center",
                va="bottom",
                fontsize=8,
            )
    fig.tight_layout()
    fig.savefig(path, dpi=180)
    plt.close(fig)


