def _safe_ccc_np(predicted: np.ndarray, target: np.ndarray) -> float:
    predicted = np.asarray(predicted, dtype=np.float64)
    target = np.asarray(target, dtype=np.float64)
    finite = np.isfinite(predicted) & np.isfinite(target)
    predicted = predicted[finite]
    target = target[finite]
    if predicted.size < 2:
        return float("nan")
    pred_mean = float(np.mean(predicted))
    target_mean = float(np.mean(target))
    pred_var = float(np.mean(np.square(predicted - pred_mean)))
    target_var = float(np.mean(np.square(target - target_mean)))
    covariance = float(np.mean((predicted - pred_mean) * (target - target_mean)))
    denominator = pred_var + target_var + (pred_mean - target_mean) ** 2
    return float("nan") if denominator <= 1e-12 else 2.0 * covariance / denominator


def _read_bioemu_score_config(config_path: Path) -> dict[str, Any]:
    try:
        import yaml
    except Exception as exc:  # pragma: no cover - runtime dependency probe.
        raise ImportError("Official BioEmu provider requires PyYAML.") from exc
    payload = yaml.safe_load(config_path.read_text())
    if not isinstance(payload, dict) or not isinstance(payload.get("score_model"), dict):
        raise ValueError(f"Invalid official BioEmu config.yaml: {config_path}")
    return {
        key: value
        for key, value in payload["score_model"].items()
        if not str(key).startswith("_")
    }


def _import_official_bioemu(repo_root: Path | None) -> tuple[Any, Any]:
    if repo_root is not None:
        for candidate in (repo_root / "src", repo_root):
            text = str(candidate)
            if candidate.exists() and text not in sys.path:
                sys.path.insert(0, text)
    try:
        from bioemu.chemgraph import ChemGraph
        from bioemu.model_utils import load_model
    except Exception as exc:  # pragma: no cover - runtime dependency probe.
        raise ImportError(
            "Official BioEmu provider requires the microsoft/bioemu package and "
            "its runtime dependencies inside the SIF."
        ) from exc
    return load_model, ChemGraph


def _official_bioemu_chemgraph(
    *,
    chemgraph_cls: Any,
    sequence_tokens: torch.Tensor,
    entity_uid: str,
    sample_index: int,
    generator: torch.Generator,
    device: torch.device,
) -> Any:
    residue_count = max(int(sequence_tokens.numel()), 1)
    row = torch.arange(residue_count, device=device).repeat_interleave(residue_count)
    col = torch.arange(residue_count, device=device).repeat(residue_count)
    return chemgraph_cls(
        pos=0.1
        * torch.randn(residue_count, 3, generator=generator, device=device),
        node_orientations=torch.eye(3, device=device).repeat(residue_count, 1, 1),
        edge_index=torch.stack([row, col], dim=0),
        single_embeds=_official_single_embeds(sequence_tokens, device=device),
        pair_embeds=_official_pair_embeds(sequence_tokens, row=row, col=col, device=device),
        sequence=_sequence_string(sequence_tokens),
        system_id=f"{entity_uid}:sample:{sample_index}",
        node_labels=_official_node_labels(sequence_tokens, device=device),
        batch=torch.zeros(residue_count, dtype=torch.long, device=device),
        pos_is_known=torch.ones(residue_count, dtype=torch.bool, device=device),
    )


def _official_bioemu_chemgraph_batch(
    *,
    chemgraph_cls: Any,
    sequence_tokens: torch.Tensor,
    entity_uid: str,
    sample_start: int,
    sample_count: int,
    generator: torch.Generator,
    device: torch.device,
) -> Any:
    """Create one block-diagonal ChemGraph batch for several BioEmu probes."""

    sample_count = max(int(sample_count), 1)
    residue_count = max(int(sequence_tokens.numel()), 1)
    base_row = torch.arange(residue_count, device=device).repeat_interleave(residue_count)
    base_col = torch.arange(residue_count, device=device).repeat(residue_count)
    offsets = (
        torch.arange(sample_count, device=device, dtype=torch.long)
        .repeat_interleave(residue_count * residue_count)
        * residue_count
    )
    row = base_row.repeat(sample_count) + offsets
    col = base_col.repeat(sample_count) + offsets
    base_single = _official_single_embeds(sequence_tokens, device=device)
    base_pair = _official_pair_embeds(
        sequence_tokens,
        row=base_row,
        col=base_col,
        device=device,
    )
    base_labels = _official_node_labels(sequence_tokens, device=device)
    node_count = sample_count * residue_count
    return chemgraph_cls(
        pos=0.1 * torch.randn(node_count, 3, generator=generator, device=device),
        node_orientations=torch.eye(3, device=device).repeat(node_count, 1, 1),
        edge_index=torch.stack([row, col], dim=0),
        single_embeds=base_single.repeat(sample_count, 1),
        pair_embeds=base_pair.repeat(sample_count, 1),
        sequence=_sequence_string(sequence_tokens),
        system_id=f"{entity_uid}:samples:{sample_start}-{sample_start + sample_count - 1}",
        node_labels=base_labels.repeat(sample_count),
        batch=torch.arange(sample_count, dtype=torch.long, device=device).repeat_interleave(
            residue_count
        ),
        pos_is_known=torch.ones(node_count, dtype=torch.bool, device=device),
    )


def _reshape_official_batched_nodes(
    values: torch.Tensor,
    *,
    sample_count: int,
    residue_count: int,
    detach: bool = True,
) -> torch.Tensor:
    if detach:
        values = values.detach()
    if values.ndim == 3 and values.shape[0] == sample_count:
        return values[:, :residue_count, :]
    if values.ndim == 3 and values.shape[0] == 1:
        values = values.squeeze(0)
    if values.ndim != 2:
        raise ValueError(f"Expected BioEmu x1d node tensor, got shape {tuple(values.shape)}")
    expected_nodes = int(sample_count) * int(residue_count)
    if values.shape[0] < expected_nodes:
        raise ValueError(
            "Official BioEmu x1d hook returned too few nodes for the batched graph: "
            f"{values.shape[0]} < {expected_nodes}"
        )
    return values[:expected_nodes].reshape(sample_count, residue_count, values.shape[-1])


def _reshape_official_batched_positions(
    values: Any,
    *,
    sample_count: int,
    residue_count: int,
) -> torch.Tensor | None:
    """Return official BioEmu residue/node positions as ``[sample, residue, 3]``."""

    if not torch.is_tensor(values):
        return None
    positions = values.detach()
    sample_count = int(sample_count)
    residue_count = int(residue_count)
    if positions.ndim == 3 and int(positions.shape[0]) == sample_count:
        if int(positions.shape[1]) < residue_count or int(positions.shape[-1]) != 3:
            return None
        return positions[:, :residue_count, :].to(dtype=torch.float32)
    if positions.ndim != 2 or int(positions.shape[-1]) != 3:
        return None
    expected_nodes = sample_count * residue_count
    if int(positions.shape[0]) < expected_nodes:
        return None
    return positions[:expected_nodes].reshape(sample_count, residue_count, 3).to(
        dtype=torch.float32
    )


def _reshape_official_batched_pairs(
    values: torch.Tensor,
    *,
    sample_count: int,
    residue_count: int,
    detach: bool = True,
) -> torch.Tensor:
    """Return BioEmu StructureModule x2d as ``[sample, residue, residue, dim]``."""

    if detach:
        values = values.detach()
    sample_count = int(sample_count)
    residue_count = int(residue_count)
    if values.ndim == 4:
        if int(values.shape[0]) == sample_count:
            return values[:, :residue_count, :residue_count, :]
        if int(values.shape[0]) == 1 and sample_count == 1:
            return values[:, :residue_count, :residue_count, :]
    if values.ndim == 3:
        if int(values.shape[0]) == sample_count * residue_count:
            if int(values.shape[1]) < residue_count:
                raise ValueError(
                    "Official BioEmu x2d hook returned too few neighbor residues: "
                    f"{values.shape[1]} < {residue_count}"
                )
            return values[:, :residue_count, :].reshape(
                sample_count,
                residue_count,
                residue_count,
                values.shape[-1],
            )
        if sample_count == 1 and int(values.shape[0]) >= residue_count:
            return values[:residue_count, :residue_count, :].unsqueeze(0)
    raise ValueError(f"Expected BioEmu x2d pair tensor, got shape {tuple(values.shape)}")


def _normalize_x2d_global_extra_bands(
    bands: tuple[dict[str, Any], ...] | list[dict[str, Any]] | None,
) -> tuple[dict[str, Any], ...]:
    normalized: list[dict[str, Any]] = []
    for raw in bands or ():
        if not isinstance(raw, dict):
            raise TypeError(
                "bioemu_x2d_pair_global_extra_bands entries must be objects"
            )
        topk = int(raw.get("topk", raw.get("global_topk", 0)))
        weight = float(raw.get("weight", raw.get("global_weight", 1.0)))
        min_sep = int(
            raw.get(
                "min_sequence_separation",
                raw.get("global_min_sequence_separation", raw.get("min_sep", 0)),
            )
        )
        max_sep = int(
            raw.get(
                "max_sequence_separation",
                raw.get("global_max_sequence_separation", raw.get("max_sep", 0)),
            )
        )
        if topk <= 0 or weight <= 0.0:
            continue
        name = str(raw.get("name", raw.get("band_name", ""))).strip()
        if not name:
            name = f"global_extra_{len(normalized) + 1}"
        normalized.append(
            {
                "name": name,
                "topk": float(max(topk, 0)),
                "weight": max(weight, 0.0),
                "min_sequence_separation": float(max(min_sep, 0)),
                "max_sequence_separation": float(max(max_sep, 0)),
                "score_mode": str(raw.get("score_mode", "x2d_norm")),
            }
        )
    return tuple(normalized)


def _x2d_global_band_specs(
    *,
    global_topk: int,
    global_weight: float,
    global_min_sequence_separation: int,
    global_max_sequence_separation: int,
    global_band_name: str = "global",
    global_extra_bands: tuple[dict[str, Any], ...] | list[dict[str, Any]] = (),
) -> tuple[dict[str, Any], ...]:
    bands: list[dict[str, Any]] = []
    if int(global_topk) > 0 and float(global_weight) > 0.0:
        bands.append(
            {
                "name": str(global_band_name or "global"),
                "topk": float(max(int(global_topk), 0)),
                "weight": max(float(global_weight), 0.0),
                "min_sequence_separation": float(
                    max(int(global_min_sequence_separation), 0)
                ),
                "max_sequence_separation": float(
                    max(int(global_max_sequence_separation), 0)
                ),
                "score_mode": "x2d_norm",
            }
        )
    bands.extend(_normalize_x2d_global_extra_bands(global_extra_bands))
    return tuple(bands)


def _x2d_global_band_names(
    *,
    global_topk: int,
    global_weight: float,
    global_band_name: str = "global",
    global_extra_bands: tuple[dict[str, Any], ...] | list[dict[str, Any]] = (),
) -> tuple[str, ...]:
    bands = _x2d_global_band_specs(
        global_topk=global_topk,
        global_weight=global_weight,
        global_band_name=global_band_name,
        global_min_sequence_separation=0,
        global_max_sequence_separation=0,
        global_extra_bands=global_extra_bands,
    )
    return tuple(str(band.get("name", f"global_{index}")) for index, band in enumerate(bands))


def _x2d_global_neighbor_mask(
    *,
    seq_offset: torch.Tensor,
    local_offsets: torch.Tensor,
    min_sequence_separation: int,
    max_sequence_separation: int,
) -> torch.Tensor:
    global_mask = seq_offset.ne(0)
    if local_offsets.numel() > 0:
        global_mask = global_mask & ~torch.any(
            seq_offset.unsqueeze(-1) == local_offsets.view(1, 1, -1),
            dim=-1,
        )
    min_sep = max(0, int(min_sequence_separation))
    if min_sep > 0:
        long_range_mask = torch.abs(seq_offset) >= min_sep
        if torch.count_nonzero(global_mask & long_range_mask) > 0:
            global_mask = global_mask & long_range_mask
    max_sep = max(0, int(max_sequence_separation))
    if max_sep > 0:
        medium_range_mask = torch.abs(seq_offset) <= max_sep
        if torch.count_nonzero(global_mask & medium_range_mask) > 0:
            global_mask = global_mask & medium_range_mask
    if torch.count_nonzero(global_mask) == 0:
        global_mask = seq_offset.ne(0)
    return global_mask


def _residue_class_score_from_tokens(
    sequence_tokens: torch.Tensor | None,
    *,
    residue_count: int,
    mode: str,
    device: torch.device,
    dtype: torch.dtype,
) -> torch.Tensor:
    if sequence_tokens is None:
        return torch.zeros(residue_count, dtype=dtype, device=device)
    tokens = sequence_tokens.to(device=device).long()
    if int(tokens.numel()) < int(residue_count):
        tokens = torch.nn.functional.pad(tokens, (0, int(residue_count) - int(tokens.numel())))
    tokens = tokens[: int(residue_count)]
    mode = str(mode or "x2d_norm").lower()
    classes: set[int] = set()
    if any(key in mode for key in ("ring", "aromatic")):
        # H, F, W, Y in the internal alphabet XARNDCQEGHILKMFPSTWYV.
        classes.update({9, 14, 18, 19})
    if any(key in mode for key in ("charged", "electrostatic", "sulfur")):
        # R, D, E, H, K plus sulfur-containing C/M.
        classes.update({2, 4, 5, 7, 9, 12, 13})
    if any(key in mode for key in ("hbond", "exchange")):
        # Polar/charged side chains and Gly/Pro context for exchange-prone rows.
        classes.update({2, 3, 4, 6, 7, 8, 9, 12, 15, 16, 17, 19})
    if any(key in mode for key in ("peptide", "plane", "carbonyl")):
        # Gly/Pro/beta-branched residues perturb peptide-plane local geometry.
        classes.update({8, 10, 15, 17, 20})
    if not classes:
        return torch.zeros(residue_count, dtype=dtype, device=device)
    class_tensor = torch.as_tensor(sorted(classes), dtype=torch.long, device=device)
    return torch.isin(tokens, class_tensor).to(dtype=dtype)


def _x2d_pair_score_for_mode(
    *,
    pair_score: torch.Tensor,
    seq_offset: torch.Tensor,
    local_offsets: torch.Tensor,
    sequence_tokens: torch.Tensor | None,
    score_mode: str,
) -> torch.Tensor:
    """Return edge-class-aware x2d top-k score without storing full L^2 output."""

    mode = str(score_mode or "x2d_norm").lower()
    if mode in {"", "x2d", "x2d_norm", "norm"}:
        return pair_score
    sample_count, residue_count, _ = pair_score.shape
    score = pair_score.float()
    abs_offset = torch.abs(seq_offset).float().view(1, residue_count, residue_count)
    if any(key in mode for key in ("peptide", "plane", "carbonyl")):
        plane_pref = torch.exp(-0.5 * torch.square(abs_offset - 2.0))
        score = score + 0.35 * plane_pref
    if any(key in mode for key in ("medium", "sequence")):
        local_pref = 1.0 / (1.0 + torch.abs(abs_offset - 3.0))
        score = score + 0.15 * local_pref
    if any(key in mode for key in ("global", "contact", "ring", "aromatic")):
        long_pref = (abs_offset >= 5.0).to(dtype=score.dtype)
        score = score + 0.10 * long_pref
    residue_score = _residue_class_score_from_tokens(
        sequence_tokens,
        residue_count=residue_count,
        mode=mode,
        device=pair_score.device,
        dtype=score.dtype,
    )
    if bool(torch.any(residue_score > 0.0)):
        pair_bonus = 0.5 * (
            residue_score.view(1, residue_count)
            + residue_score.view(residue_count, 1)
        )
        score = score + 0.45 * pair_bonus.view(1, residue_count, residue_count)
    if local_offsets.numel() > 0 and "nonlocal" in mode:
        local_mask = torch.any(
            seq_offset.unsqueeze(-1) == local_offsets.view(1, 1, -1),
            dim=-1,
        )
        score = score.masked_fill(local_mask.view(1, residue_count, residue_count), -1.0e9)
    return score.to(dtype=pair_score.dtype).expand(sample_count, -1, -1)


def _topk_pair_edge_summary(
    *,
    sym_pair: torch.Tensor,
    pair_score: torch.Tensor,
    seq_offset: torch.Tensor,
    local_offsets: torch.Tensor,
    topk: int,
    min_sequence_separation: int,
    max_sequence_separation: int,
    sequence_tokens: torch.Tensor | None = None,
    score_mode: str = "x2d_norm",
) -> torch.Tensor:
    sample_count, residue_count, _, pair_dim = sym_pair.shape
    global_mask = _x2d_global_neighbor_mask(
        seq_offset=seq_offset,
        local_offsets=local_offsets,
        min_sequence_separation=min_sequence_separation,
        max_sequence_separation=max_sequence_separation,
    )
    class_score = _x2d_pair_score_for_mode(
        pair_score=pair_score,
        seq_offset=seq_offset,
        local_offsets=local_offsets,
        sequence_tokens=sequence_tokens,
        score_mode=score_mode,
    )
    topk = min(max(int(topk), 1), max(int(residue_count) - 1, 1))
    masked_score = class_score.masked_fill(
        ~global_mask.view(1, residue_count, residue_count),
        -1.0e9,
    )
    top_values, top_indices = torch.topk(masked_score, k=topk, dim=-1)
    top_valid = torch.gather(
        global_mask.view(1, residue_count, residue_count).expand(
            int(sample_count), -1, -1
        ),
        dim=-1,
        index=top_indices,
    )
    gather_index = top_indices.unsqueeze(-1).expand(-1, -1, -1, int(pair_dim))
    top_pair = torch.gather(sym_pair, dim=2, index=gather_index)
    top_logits = top_values.masked_fill(~top_valid, -1.0e4)
    top_weights = torch.softmax(top_logits.float(), dim=-1).to(dtype=sym_pair.dtype)
    top_weights = top_weights * top_valid.to(dtype=sym_pair.dtype)
    top_weights = top_weights / top_weights.sum(dim=-1, keepdim=True).clamp_min(
        1.0e-8
    )
    return torch.sum(top_pair * top_weights.unsqueeze(-1), dim=2)


def _topk_residue_neighbor_summary(
    *,
    residue_latent: torch.Tensor,
    pair_score: torch.Tensor,
    seq_offset: torch.Tensor,
    local_offsets: torch.Tensor,
    topk: int,
    min_sequence_separation: int,
    max_sequence_separation: int,
    sequence_tokens: torch.Tensor | None = None,
    score_mode: str = "x2d_norm",
) -> torch.Tensor:
    sample_count, residue_count, residue_dim = residue_latent.shape
    global_mask = _x2d_global_neighbor_mask(
        seq_offset=seq_offset,
        local_offsets=local_offsets,
        min_sequence_separation=min_sequence_separation,
        max_sequence_separation=max_sequence_separation,
    )
    class_score = _x2d_pair_score_for_mode(
        pair_score=pair_score,
        seq_offset=seq_offset,
        local_offsets=local_offsets,
        sequence_tokens=sequence_tokens,
        score_mode=score_mode,
    )
    topk = min(max(int(topk), 1), max(int(residue_count) - 1, 1))
    masked_score = class_score.masked_fill(
        ~global_mask.view(1, residue_count, residue_count),
        -1.0e9,
    )
    top_values, top_indices = torch.topk(masked_score, k=topk, dim=-1)
    top_valid = torch.gather(
        global_mask.view(1, residue_count, residue_count).expand(
            int(sample_count), -1, -1
        ),
        dim=-1,
        index=top_indices,
    )
    gather_index = top_indices.unsqueeze(-1).expand(-1, -1, -1, int(residue_dim))
    neighbor_context = torch.gather(
        residue_latent.unsqueeze(1).expand(-1, int(residue_count), -1, -1),
        dim=2,
        index=gather_index,
    )
    top_logits = top_values.masked_fill(~top_valid, -1.0e4)
    top_weights = torch.softmax(top_logits.float(), dim=-1).to(dtype=residue_latent.dtype)
    top_weights = top_weights * top_valid.to(dtype=residue_latent.dtype)
    top_weights = top_weights / top_weights.sum(dim=-1, keepdim=True).clamp_min(
        1.0e-8
    )
    return torch.sum(neighbor_context * top_weights.unsqueeze(-1), dim=2)


def _fallback_pair_residue_latent_from_residue(
    residue_latent: torch.Tensor,
    *,
    offsets: tuple[int, ...] = (-2, -1, 0, 1, 2),
    global_topk: int = 0,
    global_weight: float = 1.0,
    global_min_sequence_separation: int = 0,
    global_max_sequence_separation: int = 0,
    global_extra_bands: tuple[dict[str, Any], ...] = (),
    sequence_tokens: torch.Tensor | None = None,
) -> torch.Tensor:
    """Build a compact pair-context fallback when x2d capture is unavailable.

    The fallback is deliberately conservative: it never stores a full pair
    tensor, and it only pools sequence-local neighbors plus optional top-k
    representation-neighbor rows from the final low-t residue state.
    """

    if residue_latent.ndim != 3:
        raise ValueError(
            "Expected residue_latent with shape [sample, residue, dim], got "
            f"{tuple(residue_latent.shape)}"
        )
    sample_count, residue_count, _ = residue_latent.shape
    if int(residue_count) <= 0:
        return residue_latent
    offset_tensor = torch.as_tensor(offsets, dtype=torch.long, device=residue_latent.device)
    if offset_tensor.numel() == 0:
        offset_tensor = torch.as_tensor([0], dtype=torch.long, device=residue_latent.device)
    center = torch.arange(residue_count, dtype=torch.long, device=residue_latent.device)
    raw_neighbor = center.view(-1, 1) + offset_tensor.view(1, -1)
    valid = (raw_neighbor >= 0) & (raw_neighbor < residue_count)
    neighbor = raw_neighbor.clamp(min=0, max=residue_count - 1)
    local_context = residue_latent[:, neighbor, :]
    local_weights = valid.to(dtype=residue_latent.dtype).view(1, residue_count, -1, 1)
    local_summary = torch.sum(local_context * local_weights, dim=2) / local_weights.sum(
        dim=2
    ).clamp_min(1.0)

    global_bands = _x2d_global_band_specs(
        global_topk=global_topk,
        global_weight=global_weight,
        global_min_sequence_separation=global_min_sequence_separation,
        global_max_sequence_separation=global_max_sequence_separation,
        global_extra_bands=global_extra_bands,
    )
    if not global_bands or int(residue_count) <= 1:
        return local_summary

    normalized = torch.nn.functional.normalize(residue_latent.float(), dim=-1)
    pair_score = torch.matmul(normalized, normalized.transpose(1, 2)).to(
        dtype=residue_latent.dtype
    )
    row_index = torch.arange(residue_count, dtype=torch.long, device=residue_latent.device)
    seq_offset = row_index.view(1, -1) - row_index.view(-1, 1)
    local_offsets = torch.as_tensor(tuple(set(int(o) for o in offsets)), device=residue_latent.device)
    global_summary = local_summary.new_zeros(local_summary.shape)
    total_weight = 0.0
    for band in global_bands:
        band_weight = max(float(band["weight"]), 0.0)
        if band_weight <= 0.0:
            continue
        band_summary = _topk_residue_neighbor_summary(
            residue_latent=residue_latent,
            pair_score=pair_score,
            seq_offset=seq_offset,
            local_offsets=local_offsets,
            topk=int(band["topk"]),
            min_sequence_separation=int(band["min_sequence_separation"]),
            max_sequence_separation=int(band["max_sequence_separation"]),
            sequence_tokens=sequence_tokens,
            score_mode=str(band.get("score_mode", "x2d_norm")),
        )
        global_summary = global_summary + band_weight * band_summary
        total_weight += band_weight
    if total_weight <= 0.0:
        return local_summary
    global_summary = global_summary / max(total_weight, 1.0e-8)
    return (local_summary + total_weight * global_summary) / (1.0 + total_weight)


def _summarize_official_x2d(
    values: torch.Tensor,
    *,
    sample_count: int,
    residue_count: int,
    sequence_tokens: torch.Tensor | None = None,
    offsets: tuple[int, ...] = (-2, -1, 0, 1, 2),
    global_topk: int = 0,
    global_weight: float = 1.0,
    global_min_sequence_separation: int = 0,
    global_max_sequence_separation: int = 0,
    global_extra_bands: tuple[dict[str, Any], ...] = (),
    global_band_name: str = "global",
    split_global_bands: bool = False,
    detach: bool = True,
) -> torch.Tensor:
    """Compactly summarize x2d on local and optional global pair edges.

    This keeps x2d as pair-state evidence without retaining the full L^2 tensor
    outside the frozen BioEmu forward pass.
    """

    pair = _reshape_official_batched_pairs(
        values,
        sample_count=sample_count,
        residue_count=residue_count,
        detach=detach,
    )
    residue_count = int(pair.shape[1])
    if residue_count <= 0:
        return pair.new_zeros(int(sample_count), 0, int(pair.shape[-1]))
    offset_tensor = torch.as_tensor(offsets, dtype=torch.long, device=pair.device)
    if offset_tensor.numel() == 0:
        offset_tensor = torch.as_tensor([0], dtype=torch.long, device=pair.device)
    center = torch.arange(residue_count, dtype=torch.long, device=pair.device)
    raw_neighbor = center.view(-1, 1) + offset_tensor.view(1, -1)
    valid = (raw_neighbor >= 0) & (raw_neighbor < residue_count)
    neighbor = raw_neighbor.clamp(min=0, max=residue_count - 1)
    center_matrix = center.view(-1, 1).expand_as(neighbor)
    forward_pair = pair[:, center_matrix, neighbor, :]
    reverse_pair = pair[:, neighbor, center_matrix, :]
    local_pair = 0.5 * (forward_pair + reverse_pair)
    weights = valid.to(dtype=pair.dtype).view(1, residue_count, -1, 1)
    denom = weights.sum(dim=2).clamp_min(1.0)
    local_summary = torch.sum(local_pair * weights, dim=2) / denom
    global_bands = _x2d_global_band_specs(
        global_topk=global_topk,
        global_weight=global_weight,
        global_min_sequence_separation=global_min_sequence_separation,
        global_max_sequence_separation=global_max_sequence_separation,
        global_band_name=global_band_name,
        global_extra_bands=global_extra_bands,
    )
    if not global_bands or residue_count <= 1:
        return local_summary

    sym_pair = 0.5 * (pair + pair.transpose(1, 2))
    pair_score = torch.linalg.vector_norm(sym_pair.float(), dim=-1).to(dtype=pair.dtype)
    row_index = torch.arange(residue_count, dtype=torch.long, device=pair.device)
    col_index = row_index
    seq_offset = col_index.view(1, -1) - row_index.view(-1, 1)
    local_offsets = torch.as_tensor(tuple(set(int(o) for o in offsets)), device=pair.device)
    global_summary = local_summary.new_zeros(local_summary.shape)
    split_summaries: list[torch.Tensor] = []
    for band in global_bands:
        band_weight = max(float(band["weight"]), 0.0)
        if band_weight <= 0.0:
            continue
        band_summary = _topk_pair_edge_summary(
            sym_pair=sym_pair,
            pair_score=pair_score,
            seq_offset=seq_offset,
            local_offsets=local_offsets,
            topk=int(band["topk"]),
            min_sequence_separation=int(band["min_sequence_separation"]),
            max_sequence_separation=int(band["max_sequence_separation"]),
            sequence_tokens=sequence_tokens,
            score_mode=str(band.get("score_mode", "x2d_norm")),
        )
        if split_global_bands:
            split_summaries.append(band_weight * band_summary)
        global_summary = global_summary + band_weight * band_summary
    if split_global_bands and split_summaries:
        return torch.cat([local_summary, *split_summaries], dim=-1)
    return torch.cat([local_summary, global_summary], dim=-1)


def _official_batched_score_norm(
    *,
    output: Any,
    sample_count: int,
    residue_count: int,
    detach: bool = True,
) -> torch.Tensor:
    pos = output.pos.detach() if detach else output.pos
    orientations = (
        output.node_orientations.detach()
        if detach
        else output.node_orientations
    )
    if pos.ndim != 2 or orientations.ndim != 2:
        scalar = torch.mean(torch.square(pos)) + torch.mean(torch.square(orientations))
        return scalar.reshape(1).repeat(sample_count)
    expected_nodes = int(sample_count) * int(residue_count)
    pos = pos[:expected_nodes].reshape(sample_count, residue_count, -1)
    orientations = orientations[:expected_nodes].reshape(sample_count, residue_count, -1)
    return torch.mean(torch.square(pos) + torch.square(orientations), dim=(1, 2))


def _official_single_embeds(sequence_tokens: torch.Tensor, *, device: torch.device) -> torch.Tensor:
    tokens = sequence_tokens.to(device=device).float()
    residue_count = max(int(tokens.numel()), 1)
    base = _sequence_basis(sequence_tokens.to(device=device), 384)
    position = torch.linspace(0.0, 1.0, residue_count, device=device).unsqueeze(-1)
    freqs = torch.arange(1, 385, dtype=torch.float32, device=device).unsqueeze(0)
    positional = torch.sin(position * freqs * 0.37) + torch.cos(position * freqs * 0.11)
    embeds = 0.5 * base + 0.5 * positional
    token_indices = torch.clamp(tokens.long(), min=0, max=29)
    one_hot = torch.nn.functional.one_hot(token_indices, num_classes=30).float()
    embeds[:, :30] = embeds[:, :30] + one_hot
    return embeds.to(torch.float32)


def _official_pair_embeds(
    sequence_tokens: torch.Tensor,
    *,
    row: torch.Tensor,
    col: torch.Tensor,
    device: torch.device,
) -> torch.Tensor:
    tokens = sequence_tokens.to(device=device).float()
    rel = (row - col).float().unsqueeze(-1)
    token_pair = (tokens[row] - tokens[col]).unsqueeze(-1)
    freqs = torch.arange(1, 129, dtype=torch.float32, device=device).unsqueeze(0)
    return (
        torch.sin(rel * freqs * 0.031)
        + torch.cos(rel.abs() * freqs * 0.017)
        + 0.05 * torch.sin(token_pair * freqs * 0.071)
    ).to(torch.float32)


def _official_node_labels(sequence_tokens: torch.Tensor, *, device: torch.device) -> torch.Tensor:
    return torch.clamp(sequence_tokens.to(device=device).long(), min=0, max=29)


def _official_bioemu_timesteps(
    *,
    sample_count: int,
    generator: torch.Generator,
    device: torch.device,
    antithetic: bool,
) -> torch.Tensor:
    if antithetic and sample_count > 1:
        return torch.linspace(0.05, 0.95, sample_count, device=device)
    return torch.rand(sample_count, generator=generator, device=device).clamp(0.05, 0.95)


def _sequence_string(sequence_tokens: torch.Tensor) -> str:
    alphabet = "XARNDCQEGHILKMFPSTWYV"
    letters = []
    for token in sequence_tokens.detach().cpu().long().tolist():
        index = int(token)
        letters.append(alphabet[index] if 0 <= index < len(alphabet) else "X")
    return "".join(letters) or "X"


def _trim_special_tokens(embeddings: torch.Tensor, *, residue_count: int) -> torch.Tensor:
    """Trim BOS/EOS-like tokens from sequence-model embeddings when present."""

    residue_count = max(int(residue_count), 1)
    if embeddings.shape[0] == residue_count:
        return embeddings
    if embeddings.shape[0] == residue_count + 2:
        return embeddings[1:-1]
    if embeddings.shape[0] == residue_count + 1:
        return embeddings[:residue_count]
    if embeddings.shape[0] > residue_count:
        start = max((int(embeddings.shape[0]) - residue_count) // 2, 0)
        return embeddings[start : start + residue_count]
    pad_count = residue_count - int(embeddings.shape[0])
    pad = embeddings[-1:].expand(pad_count, -1)
    return torch.cat([embeddings, pad], dim=0)


def _import_external_bioemu(repo_root: Path) -> tuple[type[nn.Module], Any]:
    """Import the external BioEmu class without making AtypEmu depend on it."""

    candidates = [repo_root, repo_root / "src"]
    for candidate in candidates:
        text = str(candidate)
        if candidate.exists() and text not in sys.path:
            sys.path.insert(0, text)
    import_errors: list[str] = []
    model_cls = None
    for module_name in (
        "bioemu.models.voltage_conditioned_bioemu",
        "src.bioemu.models.voltage_conditioned_bioemu",
    ):
        try:
            module = __import__(module_name, fromlist=["VoltageConditionedBioEmu"])
            model_cls = getattr(module, "VoltageConditionedBioEmu")
            break
        except Exception as exc:  # pragma: no cover - external runtime only.
            import_errors.append(f"{module_name}: {type(exc).__name__}: {exc}")
    if model_cls is None:
        raise ImportError(
            "Could not import VoltageConditionedBioEmu from external BioEmu repo "
            f"{repo_root}. Tried: {'; '.join(import_errors)}"
        )
    fallback_embeddings = None
    for module_name in ("bioemu.data.sequence_features", "src.bioemu.data.sequence_features"):
        try:
            module = __import__(module_name, fromlist=["build_fallback_esm2_embeddings"])
            fallback_embeddings = getattr(module, "build_fallback_esm2_embeddings")
            break
        except Exception:
            continue
    return model_cls, fallback_embeddings


def _extract_external_state_dict(payload: Any) -> dict[str, torch.Tensor]:
    """Extract a loadable state-dict from common BioEmu checkpoint layouts."""

    if isinstance(payload, dict):
        for key in (
            "model_state_dict",
            "state_dict",
            "model",
            "ema_state_dict",
            "module",
        ):
            value = payload.get(key)
            if isinstance(value, dict):
                return _strip_state_dict_prefixes(value)
        if payload and all(torch.is_tensor(value) for value in payload.values()):
            return _strip_state_dict_prefixes(payload)
    raise ValueError(
        "Unsupported external BioEmu checkpoint payload; expected a state_dict-like "
        "mapping or a dict containing model_state_dict/state_dict/model."
    )


def _strip_state_dict_prefixes(state_dict: dict[str, Any]) -> dict[str, torch.Tensor]:
    stripped: dict[str, torch.Tensor] = {}
    for key, value in state_dict.items():
        if not torch.is_tensor(value):
            continue
        name = str(key)
        for prefix in ("module.", "model.", "backbone."):
            if name.startswith(prefix):
                name = name[len(prefix):]
        stripped[name] = value
    return stripped


def _bioemu_external_tokens(
    sequence_tokens: torch.Tensor,
    sample_count: int,
    device: torch.device,
) -> torch.Tensor:
    """Convert AtypEmu 1-based AA tokens to the external BioEmu token convention."""

    tokens = sequence_tokens.detach().long().to(device=device)
    unknown_mask = tokens <= 0
    tokens = torch.clamp(tokens - 1, min=0, max=20)
    tokens = torch.where(unknown_mask, torch.full_like(tokens, 20), tokens)
    return tokens.unsqueeze(0).expand(max(int(sample_count), 1), -1).contiguous()


def _external_output_tensor(
    output: Any,
    key: str,
    *,
    device: torch.device,
    required: bool = True,
) -> torch.Tensor | None:
    value = None
    if isinstance(output, dict):
        value = output.get(key)
    else:
        value = getattr(output, key, None)
    if value is None:
        if required:
            raise ValueError(f"External BioEmu output did not include {key!r}.")
        return None
    return torch.as_tensor(value, dtype=torch.float32, device=device)


def _torch_ccc(predictions: torch.Tensor, targets: torch.Tensor) -> torch.Tensor:
    if predictions.numel() < 2:
        return predictions.new_tensor(0.0)
    pred_mean = torch.mean(predictions)
    target_mean = torch.mean(targets)
    pred_var = torch.mean(torch.square(predictions - pred_mean))
    target_var = torch.mean(torch.square(targets - target_mean))
    covariance = torch.mean((predictions - pred_mean) * (targets - target_mean))
    denominator = pred_var + target_var + torch.square(pred_mean - target_mean)
    return (2.0 * covariance) / denominator.clamp_min(1e-8)


def _torch_ccc_loss(predictions: torch.Tensor, targets: torch.Tensor) -> torch.Tensor:
    return 1.0 - _torch_ccc(predictions, targets)


def _bioemu_family_ccc_loss(
    *,
    predictions: torch.Tensor,
    targets: torch.Tensor,
    families: torch.Tensor,
    row_mask: torch.Tensor,
    family_names: tuple[str, ...],
) -> torch.Tensor:
    """Preserve selected auxiliary atom-family directions without dominating HN/C'."""

    losses: list[torch.Tensor] = []
    for family_name in family_names:
        if family_name not in CHEMICAL_SHIFT_FAMILIES:
            continue
        family_index = CHEMICAL_SHIFT_FAMILIES.index(family_name)
        mask = row_mask.bool() & (families == family_index)
        if torch.count_nonzero(mask) < 2:
            continue
        losses.append(_torch_ccc_loss(predictions[mask], targets[mask]))
    if not losses:
        return predictions.new_tensor(0.0)
    return torch.mean(torch.stack(losses))


def _bioemu_family_ccc_target_loss(
    *,
    predictions: torch.Tensor,
    targets: torch.Tensor,
    families: torch.Tensor,
    row_mask: torch.Tensor,
    family_names: tuple[str, ...],
    target_ccc: float,
    min_rows: int,
) -> torch.Tensor:
    """Penalize only atom families whose masked CCC is below the requested floor."""

    losses: list[torch.Tensor] = []
    target = predictions.new_tensor(float(target_ccc))
    min_count = max(int(min_rows), 2)
    for family_name in family_names:
        if family_name not in CHEMICAL_SHIFT_FAMILIES:
            continue
        family_index = CHEMICAL_SHIFT_FAMILIES.index(family_name)
        mask = row_mask.bool() & (families == family_index)
        if torch.count_nonzero(mask) < min_count:
            continue
        ccc = _torch_ccc(predictions[mask], targets[mask])
        losses.append(torch.square(torch.relu(target - ccc)))
    if not losses:
        return predictions.new_tensor(0.0)
    return torch.mean(torch.stack(losses))


def _bioemu_all_family_residual_outlier_loss(
    *,
    predictions: torch.Tensor,
    targets: torch.Tensor,
    families: torch.Tensor,
    row_mask: torch.Tensor,
    family_names: tuple[str, ...],
    family_weights: dict[str, float],
    target_residue_tokens: torch.Tensor | None = None,
    residue_family_keys: tuple[str, ...] = (),
    tail_fraction: float,
    min_rows: int,
    max_rows_per_family: int,
    abs_error_threshold: float = 0.0,
    abs_error_threshold_by_family: dict[str, float] | None = None,
) -> tuple[torch.Tensor, int]:
    """Focus a small robust loss on current residual tails for every atom family.

    Unlike trainable rare adapters, this term does not add inference-time
    degrees of freedom.  It simply asks the existing posterior/atlas heads to
    spend some gradient on the worst masked rows within each family, normalized
    by chemical-shift ppm scale so CB/N/CA tails are not hidden behind HN/C'.
    """

    _, default_scales = family_center_scale_tensors(
        families.long().clamp(min=0, max=len(CHEMICAL_SHIFT_FAMILIES) - 1),
        dtype=targets.dtype,
        device=targets.device,
    )
    normalized_residual = (predictions - targets) / default_scales.clamp_min(1.0e-4)
    abs_score = torch.abs(normalized_residual.detach())
    abs_error = torch.abs((predictions - targets).detach())
    row_mask = row_mask.bool()
    fraction = min(max(float(tail_fraction), 0.01), 0.49)
    global_abs_threshold = max(float(abs_error_threshold), 0.0)
    family_abs_thresholds = {
        str(key): max(float(value), 0.0)
        for key, value in (abs_error_threshold_by_family or {}).items()
    }
    min_count = max(int(min_rows), 2)
    max_tail_rows = max(int(max_rows_per_family), 1)
    residue_family_pairs = _residue_family_pair_indices(residue_family_keys)
    residue_family_mask: torch.Tensor | None = None
    if residue_family_pairs and target_residue_tokens is not None:
        tokens = target_residue_tokens.to(device=targets.device).long()
        if tokens.numel() == predictions.numel():
            residue_family_mask = torch.zeros_like(row_mask, dtype=torch.bool)
            family_long = families.long()
            for residue_token, family_index in residue_family_pairs:
                residue_family_mask = residue_family_mask | (
                    (tokens == int(residue_token))
                    & (family_long == int(family_index))
                )
    weighted_losses: list[torch.Tensor] = []
    weights: list[float] = []
    selected_rows = 0
    for family_name in family_names:
        if family_name not in CHEMICAL_SHIFT_FAMILIES:
            continue
        family_index = CHEMICAL_SHIFT_FAMILIES.index(family_name)
        mask = row_mask & (families == family_index)
        if residue_family_mask is not None:
            mask = mask & residue_family_mask
        count = int(torch.count_nonzero(mask).detach().cpu())
        if count < min_count:
            continue
        family_abs_threshold = family_abs_thresholds.get(
            family_name, global_abs_threshold
        )
        if family_abs_threshold > 0.0:
            tail_mask = mask & (
                abs_error >= abs_error.new_tensor(float(family_abs_threshold))
            )
            threshold_rows = int(torch.count_nonzero(tail_mask).detach().cpu())
            if threshold_rows > max_tail_rows:
                threshold_scores = abs_score[tail_mask]
                capped_threshold = torch.topk(
                    threshold_scores,
                    k=max_tail_rows,
                ).values.min()
                tail_mask = tail_mask & (abs_score >= capped_threshold)
        else:
            family_scores = abs_score[mask]
            tail_count = max(1, min(max_tail_rows, count, math.ceil(count * fraction)))
            threshold = torch.topk(family_scores, k=tail_count).values.min()
            tail_mask = mask & (abs_score >= threshold)
        tail_rows = int(torch.count_nonzero(tail_mask).detach().cpu())
        if tail_rows == 0:
            continue
        tail_residual = normalized_residual[tail_mask]
        tail_loss = torch.nn.functional.smooth_l1_loss(
            tail_residual,
            torch.zeros_like(tail_residual),
            beta=0.75,
        )
        weight = max(float(family_weights.get(family_name, 1.0)), 0.0)
        if weight <= 0.0:
            continue
        weighted_losses.append(tail_loss * weight)
        weights.append(weight)
        selected_rows += tail_rows
    if not weighted_losses:
        return predictions.new_tensor(0.0), 0
    return (
        torch.sum(torch.stack(weighted_losses)) / max(float(sum(weights)), 1.0e-8),
        selected_rows,
    )


def _bioemu_signed_support_replay_loss(
    *,
    predictions: torch.Tensor,
    targets: torch.Tensor,
    families: torch.Tensor,
    row_mask: torch.Tensor,
    family_weights: dict[str, float],
    target_residue_tokens: torch.Tensor | None,
    signed_state_keys: tuple[str, ...],
    tail_fraction: float,
    min_rows: int,
    max_rows_per_state: int,
    huber_beta: float,
) -> tuple[torch.Tensor, int, int]:
    """Train-side replay for residue/family states with stable signed support.

    This differs from validation-outlier replay: it never imports validation
    rows into training and it only sees current train residual signs.  If a
    configured state flips sign during training, it naturally drops out of that
    signed replay bucket.
    """

    signed_specs = _residue_family_signed_state_indices(signed_state_keys)
    if not signed_specs or target_residue_tokens is None:
        return predictions.new_tensor(0.0), 0, 0
    tokens = target_residue_tokens.to(device=targets.device).long()
    if tokens.numel() != predictions.numel():
        return predictions.new_tensor(0.0), 0, 0
    _, default_scales = family_center_scale_tensors(
        families.long().clamp(min=0, max=len(CHEMICAL_SHIFT_FAMILIES) - 1),
        dtype=targets.dtype,
        device=targets.device,
    )
    raw_residual = predictions - targets
    normalized_residual = raw_residual / default_scales.clamp_min(1.0e-4)
    abs_score = torch.abs(normalized_residual.detach())
    residual_sign = torch.sign(raw_residual.detach())
    base_mask = row_mask.bool() & torch.isfinite(predictions) & torch.isfinite(targets)
    fraction = min(max(float(tail_fraction), 0.01), 1.0)
    min_count = max(int(min_rows), 1)
    max_tail_rows = max(int(max_rows_per_state), 1)
    beta = max(float(huber_beta), 1.0e-4)

    weighted_losses: list[torch.Tensor] = []
    weights: list[float] = []
    selected_rows = 0
    selected_states = 0
    family_long = families.long()
    for residue_token, family_index, sign in signed_specs:
        state_mask = (
            base_mask
            & (tokens == int(residue_token))
            & (family_long == int(family_index))
            & (residual_sign == int(sign))
        )
        count = int(torch.count_nonzero(state_mask).detach().cpu())
        if count < min_count:
            continue
        state_scores = abs_score[state_mask]
        tail_count = max(1, min(max_tail_rows, count, math.ceil(count * fraction)))
        threshold = torch.topk(state_scores, k=tail_count).values.min()
        tail_mask = state_mask & (abs_score >= threshold)
        tail_rows = int(torch.count_nonzero(tail_mask).detach().cpu())
        if tail_rows == 0:
            continue
        tail_residual = normalized_residual[tail_mask]
        tail_loss = torch.nn.functional.smooth_l1_loss(
            tail_residual,
            torch.zeros_like(tail_residual),
            beta=beta,
        )
        family_name = CHEMICAL_SHIFT_FAMILIES[int(family_index)]
        weight = max(float(family_weights.get(family_name, 1.0)), 0.0)
        if weight <= 0.0:
            continue
        weighted_losses.append(tail_loss * weight)
        weights.append(weight)
        selected_rows += tail_rows
        selected_states += 1
    if not weighted_losses:
        return predictions.new_tensor(0.0), 0, 0
    return (
        torch.sum(torch.stack(weighted_losses)) / max(float(sum(weights)), 1.0e-8),
        selected_rows,
        selected_states,
    )


def _bioemu_residue_atom_posterior_mean_loss(
    *,
    predictions: torch.Tensor,
    targets: torch.Tensor,
    families: torch.Tensor,
    row_mask: torch.Tensor,
    family_weights: dict[str, float],
    scale_by_family: dict[str, float],
    mean_weight_by_family: dict[str, float],
    family_names: tuple[str, ...],
    loss_mode: str,
    huber_delta_by_family: dict[str, float],
    row_weights: torch.Tensor | None = None,
) -> torch.Tensor:
    """Align each residue-atom posterior mean to its experimental shift.

    The loss is balanced by atom family and normalized by a fixed ppm scale so
    C'/N ppm ranges do not drown out HN rows, and uncertainty inflation cannot
    hide a displaced posterior mean. Robust modes keep rare-regime rows from
    dominating the shared atlas before the local chart geometry has separated.
    """

    centers, default_scales = family_center_scale_tensors(
        families.long().clamp(min=0, max=len(CHEMICAL_SHIFT_FAMILIES) - 1),
        dtype=targets.dtype,
        device=targets.device,
    )
    del centers
    weighted_losses: list[torch.Tensor] = []
    weights: list[float] = []
    for family_name in family_names:
        if family_name not in CHEMICAL_SHIFT_FAMILIES:
            continue
        family_index = CHEMICAL_SHIFT_FAMILIES.index(family_name)
        mask = row_mask.bool() & (families == family_index)
        if torch.count_nonzero(mask) == 0:
            continue
        configured_scale = float(scale_by_family.get(family_name, 0.0))
        scale = (
            predictions.new_tensor(configured_scale)
            if configured_scale > 0.0
            else default_scales[mask]
        )
        normalized_residual = (predictions[mask] - targets[mask]) / scale.clamp_min(
            1.0e-4
        )
        family_row_weights = (
            row_weights[mask].to(dtype=normalized_residual.dtype)
            if row_weights is not None and row_weights.shape == predictions.shape
            else None
        )
        family_loss = _bioemu_residue_atom_alignment_penalty(
            normalized_residual,
            family_name=family_name,
            loss_mode=loss_mode,
            huber_delta_by_family=huber_delta_by_family,
            row_weights=family_row_weights,
        )
        if family_name in mean_weight_by_family:
            weight = float(mean_weight_by_family[family_name])
        else:
            weight = float(family_weights.get(family_name, 1.0))
        weight = max(weight, 0.0)
        if weight <= 0.0:
            continue
        weighted_losses.append(family_loss * weight)
        weights.append(weight)
    if not weighted_losses:
        return predictions.new_tensor(0.0)
    return torch.sum(torch.stack(weighted_losses)) / max(float(sum(weights)), 1.0e-8)


def _bioemu_residue_atom_alignment_penalty(
    normalized_residual: torch.Tensor,
    *,
    family_name: str,
    loss_mode: str,
    huber_delta_by_family: dict[str, float],
    row_weights: torch.Tensor | None = None,
) -> torch.Tensor:
    def weighted_mean(values: torch.Tensor) -> torch.Tensor:
        if row_weights is None or row_weights.shape != values.shape:
            return torch.mean(values)
        weights = row_weights.to(dtype=values.dtype, device=values.device).clamp(
            min=0.0,
            max=1.0,
        )
        return torch.mean(values * weights)

    mode = str(loss_mode or "mse").strip().lower()
    if mode in {"smooth_l1", "huber", "robust_huber"}:
        delta = float(huber_delta_by_family.get(family_name, 1.0))
        beta = normalized_residual.new_tensor(max(delta, 1.0e-4))
        abs_residual = torch.abs(normalized_residual)
        quadratic = 0.5 * torch.square(normalized_residual)
        linear = beta * (abs_residual - 0.5 * beta)
        return weighted_mean(torch.where(abs_residual <= beta, quadratic, linear))
    if mode in {"clipped_mse", "winsorized_mse"}:
        delta = float(huber_delta_by_family.get(family_name, 2.0))
        clipped = torch.clamp(normalized_residual, min=-max(delta, 1.0e-4), max=max(delta, 1.0e-4))
        return weighted_mean(torch.square(clipped))
    return weighted_mean(torch.square(normalized_residual))


def _bioemu_family_orthogonal_loss(
    *,
    outputs: dict[str, torch.Tensor],
    targets: torch.Tensor,
    families: torch.Tensor,
    row_mask: torch.Tensor,
    target_family_names: tuple[str, ...],
    support_family_names: tuple[str, ...],
    detach_support: bool,
) -> torch.Tensor:
    """Keep target residual directions from collapsing onto support directions."""

    coordinates = outputs.get("atlas_coordinates")
    if coordinates is None or coordinates.ndim != 2:
        return targets.new_tensor(0.0)
    row_mask = row_mask.bool()
    target_mask = row_mask & _family_name_mask(families, target_family_names)
    support_mask = row_mask & _family_name_mask(families, support_family_names)
    if torch.count_nonzero(target_mask) < 2 or torch.count_nonzero(support_mask) < 2:
        return targets.new_tensor(0.0)
    centers, scales = family_center_scale_tensors(
        families,
        dtype=targets.dtype,
        device=targets.device,
    )
    residual_z = (outputs["mu"] - targets) / scales.clamp_min(1.0e-4)
    query_coordinates = coordinates[row_mask]
    coordinate_mean = torch.mean(query_coordinates, dim=0, keepdim=True)
    coordinate_std = torch.std(query_coordinates, dim=0, unbiased=False, keepdim=True)
    normalized_coordinates = (coordinates - coordinate_mean) / coordinate_std.clamp_min(1.0e-4)
    target_direction = torch.mean(
        normalized_coordinates[target_mask] * residual_z[target_mask].unsqueeze(-1),
        dim=0,
    )
    support_direction = torch.mean(
        normalized_coordinates[support_mask] * residual_z[support_mask].unsqueeze(-1),
        dim=0,
    )
    if detach_support:
        support_direction = support_direction.detach()
    numerator = torch.square(torch.sum(target_direction * support_direction))
    denominator = (
        torch.sum(torch.square(target_direction))
        * torch.sum(torch.square(support_direction))
    ).clamp_min(1.0e-8)
    return numerator / denominator


def _bioemu_family_direction_conflict_loss(
    *,
    outputs: dict[str, torch.Tensor],
    targets: torch.Tensor,
    families: torch.Tensor,
    row_mask: torch.Tensor,
) -> torch.Tensor:
    coordinates = outputs.get("physics_atlas_coordinates")
    if coordinates is None:
        coordinates = outputs.get("atlas_coordinates")
    if coordinates is None or coordinates.ndim != 2:
        return targets.new_tensor(0.0)
    hn_mask = row_mask.bool() & _family_name_mask(families, ("HN",))
    cprime_mask = row_mask.bool() & _family_name_mask(families, ("C'",))
    if torch.count_nonzero(hn_mask) < 2 or torch.count_nonzero(cprime_mask) < 2:
        return targets.new_tensor(0.0)
    _, scales = family_center_scale_tensors(
        families,
        dtype=targets.dtype,
        device=targets.device,
    )
    residual_z = (outputs["mu"] - targets) / scales.clamp_min(1.0e-4)
    coordinate_mean = torch.mean(coordinates[row_mask.bool()], dim=0, keepdim=True)
    coordinate_std = torch.std(coordinates[row_mask.bool()], dim=0, unbiased=False, keepdim=True)
    normalized = (coordinates - coordinate_mean) / coordinate_std.clamp_min(1.0e-4)
    hn_direction = torch.mean(normalized[hn_mask] * residual_z[hn_mask].unsqueeze(-1), dim=0)
    cprime_direction = torch.mean(
        normalized[cprime_mask] * residual_z[cprime_mask].unsqueeze(-1),
        dim=0,
    )
    cosine = torch.sum(hn_direction * cprime_direction) / (
        torch.linalg.vector_norm(hn_direction)
        * torch.linalg.vector_norm(cprime_direction)
    ).clamp_min(1.0e-8)
    return torch.square(cosine)


def _bioemu_family_tangent_orthogonality_loss(
    *,
    outputs: dict[str, torch.Tensor],
    families: torch.Tensor,
    row_mask: torch.Tensor,
) -> torch.Tensor:
    tangent_delta = outputs.get("family_tangent_delta")
    if tangent_delta is None:
        return row_mask.new_zeros((), dtype=torch.float32)
    hn_mask = row_mask.bool() & _family_name_mask(families, ("HN",))
    cprime_mask = row_mask.bool() & _family_name_mask(families, ("C'",))
    if torch.count_nonzero(hn_mask) == 0 or torch.count_nonzero(cprime_mask) == 0:
        return tangent_delta.new_tensor(0.0)
    hn_delta = torch.mean(tangent_delta[hn_mask])
    cprime_delta = torch.mean(tangent_delta[cprime_mask])
    return torch.square(hn_delta * cprime_delta)


def _bioemu_physics_sidecar_supervision_loss(
    *,
    outputs: dict[str, torch.Tensor],
    row_mask: torch.Tensor,
) -> torch.Tensor:
    coordinates = outputs.get("physics_atlas_coordinates")
    targets = outputs.get("physics_sidecar_targets")
    target_mask = outputs.get("physics_sidecar_mask")
    if coordinates is None or targets is None or target_mask is None:
        return row_mask.new_zeros((), dtype=torch.float32)
    mask = target_mask.bool() & row_mask.bool().unsqueeze(-1)
    if torch.count_nonzero(mask) == 0:
        return coordinates.new_tensor(0.0)
    return torch.mean(torch.square(coordinates[mask] - targets[mask]))


def _bioemu_ring_signed_consistency_loss(
    *,
    outputs: dict[str, torch.Tensor],
    families: torch.Tensor,
    row_mask: torch.Tensor,
    coordinate_names: tuple[str, ...],
) -> torch.Tensor:
    if "ring_orientation" not in coordinate_names:
        return row_mask.new_zeros((), dtype=torch.float32)
    target_mask = outputs.get("physics_sidecar_mask")
    targets = outputs.get("physics_sidecar_targets")
    tangent = outputs.get("family_tangent_delta")
    if target_mask is None or targets is None or tangent is None:
        return row_mask.new_zeros((), dtype=torch.float32)
    coord_index = coordinate_names.index("ring_orientation")
    mask = (
        row_mask.bool()
        & _family_name_mask(families, ("HN",))
        & target_mask[:, coord_index].bool()
    )
    if torch.count_nonzero(mask) == 0:
        return tangent.new_tensor(0.0)
    sign = torch.sign(targets[mask, coord_index]).clamp(min=-1.0, max=1.0)
    nonzero = torch.abs(sign) > 0.0
    if torch.count_nonzero(nonzero) == 0:
        return tangent.new_tensor(0.0)
    signed_delta = tangent[mask][nonzero] * sign[nonzero]
    return torch.mean(torch.square(torch.relu(-signed_delta)))


def _bioemu_carbonyl_backbone_consistency_loss(
    *,
    outputs: dict[str, torch.Tensor],
    families: torch.Tensor,
    row_mask: torch.Tensor,
    coordinate_names: tuple[str, ...],
) -> torch.Tensor:
    carbonyl_name = (
        "carbonyl_cprime"
        if "carbonyl_cprime" in coordinate_names
        else "carbonyl_backbone"
    )
    if carbonyl_name not in coordinate_names:
        return row_mask.new_zeros((), dtype=torch.float32)
    coordinates = outputs.get("physics_atlas_coordinates")
    targets = outputs.get("physics_sidecar_targets")
    target_mask = outputs.get("physics_sidecar_mask")
    if coordinates is None or targets is None or target_mask is None:
        return row_mask.new_zeros((), dtype=torch.float32)
    coord_index = coordinate_names.index(carbonyl_name)
    mask = (
        row_mask.bool()
        & _family_name_mask(families, ("C'",))
        & target_mask[:, coord_index].bool()
    )
    if torch.count_nonzero(mask) == 0:
        return coordinates.new_tensor(0.0)
    return torch.mean(
        torch.square(coordinates[mask, coord_index] - targets[mask, coord_index])
    )


def _family_name_mask(families: torch.Tensor, family_names: tuple[str, ...]) -> torch.Tensor:
    mask = torch.zeros_like(families, dtype=torch.bool)
    for family_name in family_names:
        family = str(family_name)
        if family not in CHEMICAL_SHIFT_FAMILIES:
            continue
        mask = mask | (families == CHEMICAL_SHIFT_FAMILIES.index(family))
    return mask


def _bioemu_family_scale_loss(
    *,
    predictions: torch.Tensor,
    targets: torch.Tensor,
    families: torch.Tensor,
    row_mask: torch.Tensor,
    family_names: tuple[str, ...] = CHEMICAL_SHIFT_FAMILIES,
) -> torch.Tensor:
    """Discourage family-wise posterior mean variance collapse."""

    losses: list[torch.Tensor] = []
    for family_name in family_names:
        if family_name not in CHEMICAL_SHIFT_FAMILIES:
            continue
        family_index = CHEMICAL_SHIFT_FAMILIES.index(family_name)
        mask = row_mask.bool() & (families == family_index)
        if torch.count_nonzero(mask) < 4:
            continue
        pred_std = torch.std(predictions[mask], unbiased=False).clamp_min(1e-5)
        target_std = torch.std(targets[mask], unbiased=False).clamp_min(1e-5)
        losses.append(torch.square(torch.log(pred_std / target_std)))
    if not losses:
        return predictions.new_tensor(0.0)
    return torch.mean(torch.stack(losses))


def _bioemu_family_bias_loss(
    *,
    predictions: torch.Tensor,
    targets: torch.Tensor,
    families: torch.Tensor,
    row_mask: torch.Tensor,
    family_names: tuple[str, ...] = CHEMICAL_SHIFT_FAMILIES,
) -> torch.Tensor:
    """Penalize normalized family mean bias without mixing ppm scales."""

    losses: list[torch.Tensor] = []
    for family_name in family_names:
        if family_name not in CHEMICAL_SHIFT_FAMILIES:
            continue
        family_index = CHEMICAL_SHIFT_FAMILIES.index(family_name)
        mask = row_mask.bool() & (families == family_index)
        if torch.count_nonzero(mask) < 4:
            continue
        pred_mean = torch.mean(predictions[mask])
        target_mean = torch.mean(targets[mask])
        target_std = torch.std(targets[mask], unbiased=False).clamp_min(1e-5)
        losses.append(torch.square((pred_mean - target_mean) / target_std))
    if not losses:
        return predictions.new_tensor(0.0)
    return torch.mean(torch.stack(losses))


def _target_residue_indices(
    *,
    target_features: torch.Tensor,
    residue_count: int,
) -> torch.Tensor:
    if residue_count <= 0:
        return torch.zeros(target_features.shape[0], dtype=torch.long, device=target_features.device)
    if target_features.shape[1] > FEATURE_ALIGNED_RESIDUE_INDEX:
        residue_index = target_features[:, FEATURE_ALIGNED_RESIDUE_INDEX]
    else:
        residue_index = target_features[:, 0]
    return torch.clamp(torch.round(residue_index).long() - 1, min=0, max=residue_count - 1)


def _target_residue_name_tokens(
    example: PreparedCandidateFreeExample,
    *,
    device: torch.device,
) -> torch.Tensor:
    tokens: list[int] = []
    for target_id in example.target_ids:
        parsed = parse_chemical_shift_target_id(target_id)
        residue_name = str(parsed.get("residue_name") or "").strip().upper()
        tokens.append(int(AA3_TO_SEQUENCE_TOKEN.get(residue_name, 0)))
    return torch.as_tensor(tokens, dtype=torch.long, device=device)


def _sequence_basis(sequence_tokens: torch.Tensor, latent_dim: int) -> torch.Tensor:
    tokens = sequence_tokens.float().unsqueeze(-1)
    freqs = torch.arange(1, latent_dim + 1, dtype=torch.float32, device=sequence_tokens.device)
    return torch.sin(tokens * freqs * 0.173) + torch.cos(tokens * freqs * 0.071)


def _normal_latents(
    *,
    sample_count: int,
    latent_dim: int,
    generator: torch.Generator,
    device: torch.device,
    antithetic: bool,
) -> torch.Tensor:
    if not antithetic or sample_count == 1:
        return torch.randn(sample_count, latent_dim, generator=generator, device=device)
    half = int(math.ceil(sample_count / 2))
    base = torch.randn(half, latent_dim, generator=generator, device=device)
    latent = torch.cat([base, -base], dim=0)
    return latent[:sample_count]


def _stable_entry_seed(entity_uid: str, seed: int) -> int:
    acc = int(seed) & 0x7FFFFFFF
    for char in str(entity_uid):
        acc = (acc * 131 + ord(char)) & 0x7FFFFFFF
    return acc


def _repeat_or_trim(tensor: torch.Tensor, size: int, *, dim: int) -> torch.Tensor:
    if tensor.shape[dim] == size:
        return tensor
    if tensor.shape[dim] > size:
        slices = [slice(None)] * tensor.ndim
        slices[dim] = slice(0, size)
        return tensor[tuple(slices)]
    repeats = int(math.ceil(size / max(int(tensor.shape[dim]), 1)))
    repeated = torch.cat([tensor] * repeats, dim=dim)
    slices = [slice(None)] * repeated.ndim
    slices[dim] = slice(0, size)
    return repeated[tuple(slices)]


def _resize_residue_axis(tensor: torch.Tensor, residue_count: int) -> torch.Tensor:
    return _repeat_or_trim(tensor, max(int(residue_count), 1), dim=1)


def _resize_last_dim(tensor: torch.Tensor, latent_dim: int) -> torch.Tensor:
    if tensor.shape[-1] == latent_dim:
        return tensor
    if tensor.shape[-1] > latent_dim:
        return tensor[..., :latent_dim]
    pad = tensor.new_zeros(*tensor.shape[:-1], latent_dim - tensor.shape[-1])
    return torch.cat([tensor, pad], dim=-1)


def _resize_pair_local_global_blocks(
    tensor: torch.Tensor,
    latent_dim: int,
    *,
    global_block_count: int = 1,
) -> torch.Tensor:
    """Resize concatenated local/global pair summaries without mixing blocks."""

    latent_dim = max(int(latent_dim), 1)
    global_block_count = max(int(global_block_count), 1)
    raw_block_count = 1 + global_block_count
    if int(tensor.shape[-1]) % raw_block_count != 0:
        raw_block_count = 2
        global_block_count = 1
    raw_block_dim = max(int(tensor.shape[-1]) // raw_block_count, 1)
    local_dim = max(latent_dim // 2, 1)
    global_dim = max(latent_dim - local_dim, 1)
    local = _resize_last_dim(tensor[..., :raw_block_dim], local_dim)
    global_dims = _split_feature_dim(global_dim, global_block_count)
    pieces = [local]
    raw_start = raw_block_dim
    for block_index, block_dim in enumerate(global_dims):
        raw_end = raw_start + raw_block_dim
        raw_block = tensor[..., raw_start:raw_end]
        pieces.append(_resize_last_dim(raw_block, block_dim))
        raw_start = raw_end
    return torch.cat(pieces, dim=-1)


def _split_feature_dim(total_dim: int, block_count: int) -> tuple[int, ...]:
    total_dim = max(int(total_dim), 1)
    block_count = max(int(block_count), 1)
    base = total_dim // block_count
    remainder = total_dim % block_count
    return tuple(base + (1 if index < remainder else 0) for index in range(block_count))


def _x2d_pair_global_block_slices(
    *,
    latent_dim: int,
    local_dim: int,
    global_block_names: tuple[str, ...],
) -> tuple[tuple[str, int, int], ...]:
    local_dim = max(min(int(local_dim), int(latent_dim)), 0)
    names = tuple(str(name) for name in global_block_names) or ("global",)
    if local_dim >= int(latent_dim):
        return ()
    global_dims = _split_feature_dim(int(latent_dim) - local_dim, len(names))
    slices: list[tuple[str, int, int]] = []
    start = local_dim
    for name, width in zip(names, global_dims):
        end = start + int(width)
        slices.append((name, start, end))
        start = end
    return tuple(slices)


def _epoch_ramped_weight(
    base_weight: float,
    *,
    epoch: int | None,
    start_epoch: int,
    ramp_epochs: int,
) -> float:
    if base_weight <= 0.0:
        return 0.0
    if epoch is None:
        return float(base_weight)
    safe_start = max(int(start_epoch), 1)
    if int(epoch) < safe_start:
        return 0.0
    safe_ramp = max(int(ramp_epochs), 1)
    progress = (float(epoch) - float(safe_start) + 1.0) / float(safe_ramp)
    return float(base_weight) * min(max(progress, 0.0), 1.0)


def _load_bioemu_physics_sidecar(
    *,
    config: StudentTrainingConfig,
    data_root: Path,
) -> dict[tuple[str, int, str], dict[str, float]] | None:
    path_value = config.bioemu_physics_sidecar_path
    if not path_value:
        return None
    path = Path(path_value)
    if not path.is_absolute():
        path = data_root / path
    if not path.exists():
        if float(config.bioemu_physics_sidecar_supervision_weight) > 0.0:
            raise FileNotFoundError(
                f"bioemu_physics_sidecar_path was enabled but not found: {path}"
            )
        return None
    if path.suffix == ".parquet":
        frame = pd.read_parquet(path)
    else:
        frame = pd.read_csv(path, sep=None, engine="python")
    required = {"entity_uid", "residue_index", "atom_family"}
    missing = required.difference(frame.columns)
    if missing:
        raise ValueError(
            "BioEmu physics sidecar requires columns "
            f"{sorted(required)}; missing {sorted(missing)}"
        )
    rows: dict[tuple[str, int, str], dict[str, float]] = {}
    for (entity_uid, residue_index, atom_family), group in frame.groupby(
        ["entity_uid", "residue_index", "atom_family"],
        dropna=False,
    ):
        rows[(str(entity_uid), int(residue_index), str(atom_family))] = (
            _physics_sidecar_feature_summary(group)
        )
    return rows


def _physics_sidecar_feature_summary(group: pd.DataFrame) -> dict[str, float]:
    def mean_col(name: str, default: float = float("nan")) -> float:
        if name not in group:
            return default
        values = pd.to_numeric(group[name], errors="coerce")
        if values.dropna().empty:
            return default
        return float(values.mean())

    ring_distance = mean_col("ring_distance_min")
    ring_source_count = mean_col("ring_source_count", 0.0)
    hbond_distance = mean_col("hbond_distance")
    hbond_angle = mean_col("hbond_angle")
    phi = math.radians(mean_col("phi", 0.0))
    psi = math.radians(mean_col("psi", 0.0))
    component_id = mean_col("component_id", 0.0)
    ucbshift_hbond_energy = mean_col("ucbshift_hbond_energy", float("nan"))
    ucbshift_ring_current = mean_col("ucbshift_ring_current_atom", float("nan"))
    ucbshift_electric_field = mean_col("ucbshift_electric_field_atom", float("nan"))
    ucbshift_rel_asa = mean_col("ucbshift_rel_asa", float("nan"))
    ucbshift_s2_order = mean_col("ucbshift_s2_order", float("nan"))
    ucbshift_confidence = mean_col("ucbshift_feature_confidence", 0.0)
    hbond_distance_sq = mean_col("ucbshift_hbond_distance_sq", float("nan"))
    hbond_distance_inv = mean_col("ucbshift_hbond_distance_inv", float("nan"))
    hbond_distance_inv2 = mean_col("ucbshift_hbond_distance_inv2", float("nan"))
    hbond_distance_inv3 = mean_col("ucbshift_hbond_distance_inv3", float("nan"))
    phi_cos = mean_col("ucbshift_phi_cos", math.cos(phi))
    psi_cos = mean_col("ucbshift_psi_cos", math.cos(psi))
    phi_cos2 = mean_col("ucbshift_phi_cos2", phi_cos * phi_cos)
    psi_cos2 = mean_col("ucbshift_psi_cos2", psi_cos * psi_cos)
    soft_helix = mean_col("ucbshift_soft_helix", 0.0)
    soft_beta = mean_col("ucbshift_soft_beta", 0.0)
    sequence_context = mean_col("ucbshift_sequence_context_score", 0.0)
    tripeptide_gly_pro = mean_col("ucbshift_tripeptide_gly_pro", 0.0)
    next_proline = mean_col("ucbshift_next_proline", 0.0)
    next_proline_delta = mean_col("ucbshift_next_proline_delta", 0.0)
    transfer_memory_confidence = mean_col("ucbshift_transfer_memory_confidence", 0.0)
    transfer_support_mismatch = mean_col("ucbshift_transfer_support_mismatch", float("nan"))
    transfer_abstain_risk = mean_col("ucbshift_transfer_abstain_risk", float("nan"))
    if not math.isfinite(hbond_distance_inv) and math.isfinite(hbond_distance):
        safe_distance = max(float(hbond_distance), 0.05)
        hbond_distance_sq = safe_distance * safe_distance
        hbond_distance_inv = 1.0 / safe_distance
        hbond_distance_inv2 = hbond_distance_inv * hbond_distance_inv
        hbond_distance_inv3 = hbond_distance_inv2 * hbond_distance_inv
    hbond_nonlinear = (
        math.tanh(
            0.40 * hbond_distance_inv
            + 0.18 * hbond_distance_inv2
            + 0.04 * hbond_distance_inv3
            - 0.015 * hbond_distance_sq
        )
        if all(
            math.isfinite(value)
            for value in (
                hbond_distance_sq,
                hbond_distance_inv,
                hbond_distance_inv2,
                hbond_distance_inv3,
            )
        )
        else 0.0
    )
    carbonyl_hbond_proxy = (
        math.tanh(-ucbshift_hbond_energy)
        if math.isfinite(ucbshift_hbond_energy)
        else mean_col("carbonyl_hbond_proxy", 0.0)
    )
    cis_proline_proxy = mean_col("cis_proline_proxy", 0.0)
    sidechain_rotamer = mean_col("sidechain_rotamer_proxy", cis_proline_proxy)
    ring_occupancy = (
        min(1.0, abs(ucbshift_ring_current))
        if math.isfinite(ucbshift_ring_current)
        else 0.0 if not math.isfinite(ring_distance) else 1.0 / (
            1.0 + max(ring_distance, 0.0)
        )
    )
    hbond_score = 0.0 if not math.isfinite(hbond_distance) else 1.0 / (
        1.0 + max(hbond_distance, 0.0)
    )
    angle_score = 0.0 if not math.isfinite(hbond_angle) else math.cos(
        math.radians(hbond_angle)
    )
    backbone_phase = 0.5 * (phi_cos + psi_cos)
    soft_secondary_structure = math.tanh(soft_helix - soft_beta)
    backbone_dihedral_poly = math.tanh(
        0.42 * phi_cos
        + 0.42 * psi_cos
        + 0.11 * phi_cos2
        + 0.11 * psi_cos2
        + 0.18 * soft_secondary_structure
    )
    sequence_tripeptide_context = math.tanh(
        sequence_context + 0.35 * tripeptide_gly_pro + 0.20 * next_proline
    )
    random_coil_secondary_anchor = math.tanh(next_proline_delta / 4.0)
    exchange_hbond = (0.70 * hbond_score + 0.30 * hbond_nonlinear) * angle_score
    solvent_proxy = ucbshift_rel_asa if math.isfinite(ucbshift_rel_asa) else mean_col("solvent_proxy", 0.0)
    local_order_parameter = (
        ucbshift_s2_order
        if math.isfinite(ucbshift_s2_order)
        else 1.0 - mean_col("solvent_proxy", 0.0)
    )
    solvent_exchange_risk = mean_col(
        "ucbshift_solvent_exchange_risk",
        max(0.0, min(1.0, 0.65 * solvent_proxy + 0.35 * (1.0 - local_order_parameter))),
    )
    peptide_plane_coupling = mean_col(
        "ucbshift_peptide_plane_coupling",
        math.tanh(
            0.50 * backbone_dihedral_poly
            + 0.22 * carbonyl_hbond_proxy
            + 0.18 * sequence_tripeptide_context
        ),
    )
    ring_hbond_competition = mean_col(
        "ucbshift_ring_hbond_competition",
        math.tanh(
            0.70
            * (
                ucbshift_ring_current
                if math.isfinite(ucbshift_ring_current)
                else mean_col("ring_orientation_sign", 0.0) * ring_occupancy
            )
            - 0.38 * carbonyl_hbond_proxy
            + 0.18 * solvent_exchange_risk
        ),
    )
    carbonyl_cprime = math.tanh(
        0.82 * backbone_phase
        + 0.18 * backbone_dihedral_poly
        + 0.50 * carbonyl_hbond_proxy
        + 0.20 * hbond_nonlinear
    )
    cprime_carbonyl_manifold = mean_col(
        "ucbshift_cprime_carbonyl_manifold",
        math.tanh(
            0.45 * carbonyl_cprime
            + 0.30 * peptide_plane_coupling
            + 0.15 * local_order_parameter
            - 0.10 * solvent_exchange_risk
        ),
    )
    amide_n_backbone = math.tanh(
        0.50 * exchange_hbond
        + 0.22 * backbone_phase
        + 0.18 * backbone_dihedral_poly
        + 0.10 * cis_proline_proxy
        + 0.10 * hbond_nonlinear
        + 0.08 * sequence_tripeptide_context
    )
    hn_local_manifold = mean_col(
        "ucbshift_hn_local_manifold",
        math.tanh(
            0.42 * amide_n_backbone
            + 0.26 * ring_hbond_competition
            + 0.18 * sequence_tripeptide_context
            - 0.22 * solvent_exchange_risk
        ),
    )
    if not math.isfinite(transfer_memory_confidence):
        transfer_memory_confidence = 0.0
    if not math.isfinite(transfer_support_mismatch):
        transfer_support_mismatch = max(
            0.0,
            min(
                1.0,
                (1.0 - transfer_memory_confidence)
                * (
                    0.35 * abs(ring_hbond_competition)
                    + 0.35 * abs(peptide_plane_coupling)
                    + 0.30 * solvent_exchange_risk
                ),
            ),
        )
    if not math.isfinite(transfer_abstain_risk):
        transfer_abstain_risk = max(
            0.0,
            min(
                1.0,
                0.45 * transfer_support_mismatch
                + 0.35 * (1.0 - transfer_memory_confidence)
                + 0.20 * solvent_exchange_risk,
            ),
        )
    return {
        "ring_orientation": math.copysign(1.0, ucbshift_ring_current)
        if math.isfinite(ucbshift_ring_current) and abs(ucbshift_ring_current) > 1e-8
        else mean_col("ring_orientation_sign", 0.0),
        "ring_occupancy": ring_occupancy,
        "exchange_hbond": exchange_hbond,
        "carbonyl_backbone": backbone_phase,
        "peptide_plane_coupling": peptide_plane_coupling,
        "hn_local_manifold": hn_local_manifold,
        "cprime_carbonyl_manifold": cprime_carbonyl_manifold,
        "ring_hbond_competition": ring_hbond_competition,
        "solvent_exchange_risk": solvent_exchange_risk,
        "transfer_memory_confidence": transfer_memory_confidence,
        "transfer_support_mismatch": transfer_support_mismatch,
        "transfer_abstain_risk": transfer_abstain_risk,
        "backbone_dihedral_poly": backbone_dihedral_poly,
        "carbonyl_cprime": carbonyl_cprime,
        "amide_n_backbone": amide_n_backbone,
        "alpha_backbone": backbone_phase,
        "soft_secondary_structure": soft_secondary_structure,
        "sequence_tripeptide_context": sequence_tripeptide_context,
        "random_coil_secondary_anchor": random_coil_secondary_anchor,
        "electrostatic_sulfur": ucbshift_electric_field
        if math.isfinite(ucbshift_electric_field)
        else mean_col("electrostatic_proxy", 0.0),
        "sidechain_rotamer": sidechain_rotamer,
        "beta_rotamer": sidechain_rotamer,
        "ensemble_component": math.tanh(component_id / 8.0)
        if math.isfinite(component_id)
        else 0.0,
        "uncertainty_abstain": max(
            0.0,
            min(
                1.0,
                max(ring_source_count / 3.0, 1.0 - ucbshift_confidence)
                if math.isfinite(ring_source_count)
                else 1.0 - ucbshift_confidence,
                transfer_abstain_risk,
            ),
        ),
        "hbond_nonlinear": hbond_nonlinear,
        "carbonyl_hbond_proxy": carbonyl_hbond_proxy,
        "solvent_proxy": solvent_proxy,
        "local_order_parameter": local_order_parameter,
    }


def _physics_sidecar_tensors_for_example(
    sidecar: dict[tuple[str, int, str], dict[str, float]] | None,
    *,
    example: PreparedCandidateFreeExample,
    coordinate_names: tuple[str, ...],
    device: torch.device,
) -> tuple[torch.Tensor | None, torch.Tensor | None]:
    if not sidecar:
        return None, None
    targets = torch.zeros(
        len(example.target_ids),
        len(coordinate_names),
        dtype=torch.float32,
        device=device,
    )
    mask = torch.zeros_like(targets, dtype=torch.bool)
    for row_index, target_id in enumerate(example.target_ids):
        parsed = parse_chemical_shift_target_id(target_id)
        target_features = example.target_features[row_index]
        parsed_residue_index = parsed["residue_index"] or 0
        candidate_residue_indices: list[int] = []
        if len(target_features) > FEATURE_ALIGNED_RESIDUE_INDEX:
            aligned_value = float(target_features[FEATURE_ALIGNED_RESIDUE_INDEX])
            if math.isfinite(aligned_value):
                candidate_residue_indices.append(int(round(aligned_value)))
        if parsed_residue_index:
            candidate_residue_indices.append(int(parsed_residue_index))
        features = None
        for residue_index in dict.fromkeys(candidate_residue_indices):
            features = sidecar.get(
                (str(example.entity_uid), residue_index, str(parsed["atom_family"]))
            )
            if features:
                break
        if not features:
            continue
        for coord_index, coord_name in enumerate(coordinate_names):
            value = features.get(str(coord_name))
            if value is None or not math.isfinite(float(value)):
                continue
            targets[row_index, coord_index] = float(value)
            mask[row_index, coord_index] = True
    return targets, mask


def _load_bioemu_neighborhood_sidecar(
    *,
    config: StudentTrainingConfig,
    data_root: Path,
) -> dict[tuple[str, int, int], np.ndarray] | None:
    """Load compact conformer-neighborhood edge summaries.

    The table is intentionally top-k and sparse.  It stores only edge rows that
    are safe to summarize into per-conformer/per-residue features, never the
    full L^2 x2d tensor.
    """

    path_value = config.bioemu_neighborhood_sidecar_path
    if not path_value:
        return None
    path = Path(str(path_value))
    if not path.is_absolute():
        path = data_root / path
    if not path.exists():
        print(
            "[bioemu-latent-nmr] neighborhood sidecar not found; "
            f"falling back to compact sequence neighbors: {path}",
            flush=True,
        )
        return None
    if path.suffix.lower() == ".parquet":
        frame = pd.read_parquet(path)
    elif path.suffix.lower() in {".tsv", ".tab"}:
        frame = pd.read_csv(path, sep="\t")
    else:
        frame = pd.read_csv(path)
    required = {
        "entity_uid",
        "sample_index",
        "residue_index",
        "neighbor_residue_index",
        "edge_class",
    }
    missing = required.difference(frame.columns)
    if missing:
        raise ValueError(
            "BioEmu neighborhood sidecar requires columns "
            f"{sorted(required)}; missing {sorted(missing)}"
        )
    selected_classes = {
        str(edge_class)
        for edge_class in config.bioemu_neighborhood_edge_classes
        if str(edge_class)
    }
    if selected_classes:
        frame = frame.loc[frame["edge_class"].astype(str).isin(selected_classes)].copy()
    if frame.empty:
        return {}
    if _bioemu_neighborhood_sidecar_is_compact_summary(frame):
        rows = _bioemu_neighborhood_sidecar_compact_rows(frame)
        print(
            "[bioemu-latent-nmr] loaded compact neighborhood sidecar "
            f"residue_sample_rows={len(rows)} path={path}",
            flush=True,
        )
        return rows
    rows: dict[tuple[str, int, int], np.ndarray] = {}
    for (entity_uid, sample_index, residue_index), group in frame.groupby(
        ["entity_uid", "sample_index", "residue_index"],
        sort=False,
        dropna=False,
    ):
        selected = _select_bioemu_neighborhood_sidecar_edges(
            group,
            topk_by_class=dict(config.bioemu_neighborhood_topk_by_class),
        )
        if selected.empty:
            continue
        rows[(str(entity_uid), int(sample_index), int(residue_index))] = (
            _bioemu_neighborhood_sidecar_feature_summary(selected)
        )
    print(
        "[bioemu-latent-nmr] loaded neighborhood sidecar "
        f"residue_sample_rows={len(rows)} path={path}",
        flush=True,
    )
    return rows


def _load_bioemu_support_mode_occupancy_labels(
    *,
    config: StudentTrainingConfig,
    data_root: Path,
) -> dict[str, list[str]] | None:
    """Load per-sample support-mode labels used by the occupancy guard."""

    path_value = config.bioemu_support_mode_occupancy_guard_label_path
    if not path_value:
        return None
    path = Path(str(path_value))
    if not path.is_absolute():
        path = data_root / path
    if not path.exists():
        print(
            "[bioemu-latent-nmr] support-mode label sidecar not found; "
            f"occupancy guard will stay label-gated/no-op: {path}",
            flush=True,
        )
        return None
    if path.suffix.lower() == ".parquet":
        frame = pd.read_parquet(path)
    elif path.suffix.lower() in {".tsv", ".tab"}:
        frame = pd.read_csv(path, sep="\t")
    else:
        frame = pd.read_csv(path)
    required = {"entity_uid", "sample_index"}
    missing = required.difference(frame.columns)
    if missing:
        raise ValueError(
            "BioEmu support-mode occupancy label sidecar requires columns "
            f"{sorted(required)}; missing {sorted(missing)}"
        )
    label_column = next(
        (
            column
            for column in (
                "spread_mode",
                "sample_mode_label",
                "sample_mode",
                "support_mode",
            )
            if column in frame.columns
        ),
        None,
    )
    if label_column is None:
        raise ValueError(
            "BioEmu support-mode occupancy label sidecar requires one label "
            "column among spread_mode, sample_mode_label, sample_mode, support_mode."
        )
    frame = frame.copy()
    frame["sample_index"] = pd.to_numeric(frame["sample_index"], errors="coerce")
    frame = frame.dropna(subset=["entity_uid", "sample_index", label_column])
    if frame.empty:
        return {}
    rows: dict[str, list[str]] = {}
    for entity_uid, group in frame.groupby("entity_uid", sort=False, dropna=False):
        ordered = group.sort_values("sample_index", kind="stable")
        labels = [str(label) for label in ordered[label_column].tolist()]
        if not labels:
            continue
        entity_text = str(entity_uid)
        rows[entity_text] = labels
        rows[_normalize_support_mode_token(entity_text)] = labels
    print(
        "[bioemu-latent-nmr] loaded support-mode occupancy labels "
        f"entities={len({key for key in rows if ':' in key or key.startswith('bmr')})} "
        f"path={path}",
        flush=True,
    )
    return rows


def _bioemu_neighborhood_sidecar_is_compact_summary(frame: pd.DataFrame) -> bool:
    """Return true for one-row-per-edge-class sidecars produced by the fast builder."""

    if "compact_class_summary" in frame.columns:
        values = frame["compact_class_summary"]
        if values.dtype == bool:
            return bool(values.fillna(False).all())
        normalized = values.astype(str).str.lower()
        return bool(normalized.isin({"1", "true", "yes"}).all())
    if "edge_rank" not in frame.columns:
        return False
    ranks = pd.to_numeric(frame["edge_rank"], errors="coerce")
    finite = ranks[np.isfinite(ranks)]
    if finite.empty:
        return False
    return bool(float(finite.abs().max()) <= 1.0e-8)


def _bioemu_neighborhood_sidecar_compact_rows(
    frame: pd.DataFrame,
) -> dict[tuple[str, int, int], np.ndarray]:
    """Vectorized loader for compact class-summary neighborhood sidecars.

    The compact sidecar has already selected top-k edges per class during
    sidecar generation, so loading should not redo Python-level edge selection
    for every sample/residue.  We only average class summaries into the exact
    eight-feature representation expected by the model.
    """

    data = frame.copy()
    for column, default in {
        "distance": 0.0,
        "sequence_offset": 0.0,
        "orientation_cos": 0.0,
        "hbond_score": 0.0,
        "ring_score": 0.0,
        "electrostatic_score": 0.0,
        "peptide_plane_score": 0.0,
        "edge_rank": 0.0,
    }.items():
        if column not in data.columns:
            data[column] = default
        data[column] = pd.to_numeric(data[column], errors="coerce").replace(
            [np.inf, -np.inf],
            np.nan,
        )
    grouped = data.groupby(
        ["entity_uid", "sample_index", "residue_index"],
        sort=False,
        dropna=False,
    )[
        list(BIOEMU_NEIGHBORHOOD_SIDECAR_FEATURE_COLUMNS)
    ].mean()
    if grouped.empty:
        return {}
    distance = grouped["distance"].fillna(0.0).clip(lower=0.0)
    edge_rank = grouped["edge_rank"].fillna(0.0).clip(lower=0.0)
    features = np.column_stack(
        [
            1.0 / (1.0 + distance.to_numpy(dtype=np.float64)),
            np.clip(
                grouped["sequence_offset"].fillna(0.0).to_numpy(dtype=np.float64) / 8.0,
                -1.0,
                1.0,
            ),
            np.clip(
                grouped["orientation_cos"].fillna(0.0).to_numpy(dtype=np.float64),
                -1.0,
                1.0,
            ),
            np.clip(
                grouped["hbond_score"].fillna(0.0).to_numpy(dtype=np.float64),
                -1.0,
                1.0,
            ),
            np.clip(
                grouped["ring_score"].fillna(0.0).to_numpy(dtype=np.float64),
                -1.0,
                1.0,
            ),
            np.tanh(
                grouped["electrostatic_score"].fillna(0.0).to_numpy(dtype=np.float64)
            ),
            np.clip(
                grouped["peptide_plane_score"].fillna(0.0).to_numpy(dtype=np.float64),
                -1.0,
                1.0,
            ),
            1.0 / (1.0 + edge_rank.to_numpy(dtype=np.float64)),
        ],
    ).astype(np.float32)
    features = np.nan_to_num(features, nan=0.0, posinf=0.0, neginf=0.0)
    rows: dict[tuple[str, int, int], np.ndarray] = {}
    for index, values in zip(grouped.index, features, strict=False):
        entity_uid, sample_index, residue_index = index
        rows[(str(entity_uid), int(sample_index), int(residue_index))] = values
    return rows


def _select_bioemu_neighborhood_sidecar_edges(
    group: pd.DataFrame,
    *,
    topk_by_class: dict[str, int],
) -> pd.DataFrame:
    """Return per-edge-class top-k rows with stable geometry-aware ordering."""

    if group.empty:
        return group.copy()
    data = group.copy()
    geometry_score = _bioemu_neighborhood_sidecar_edge_score(data)
    data["_geometry_edge_sort"] = -geometry_score
    if "edge_rank" not in data.columns:
        data["edge_rank"] = data["_geometry_edge_sort"]
    data["edge_rank"] = pd.to_numeric(data["edge_rank"], errors="coerce")
    data["edge_rank"] = data["edge_rank"].where(
        np.isfinite(data["edge_rank"]),
        data["_geometry_edge_sort"],
    )
    pieces: list[pd.DataFrame] = []
    default_topk = int(topk_by_class.get("*", topk_by_class.get("default", 0)) or 0)
    for edge_class, class_group in data.groupby("edge_class", sort=False, dropna=False):
        edge_class_key = str(edge_class)
        topk = int(topk_by_class.get(edge_class_key, default_topk) or 0)
        if topk <= 0:
            topk = len(class_group)
        ordered = class_group.sort_values(
            ["edge_rank", "_geometry_edge_sort", "neighbor_residue_index"],
            kind="stable",
        )
        pieces.append(ordered.head(topk))
    if not pieces:
        return data.iloc[0:0].copy()
    return pd.concat(pieces, ignore_index=True).drop(
        columns=["_geometry_edge_sort"],
        errors="ignore",
    )


def _bioemu_neighborhood_sidecar_edge_score(group: pd.DataFrame) -> pd.Series:
    """Class-specific edge priority used when sidecars omit explicit ranks.

    Real geometry sidecars should usually write ``edge_rank`` after computing
    distance/orientation/H-bond/ring/electrostatic priorities.  This fallback is
    deliberately conservative: it uses only compact scalar geometry columns and
    never needs full L^2 x2d storage.
    """

    index = group.index

    def col(name: str, default: float = 0.0) -> pd.Series:
        if name not in group.columns:
            return pd.Series(default, index=index, dtype=np.float64)
        values = pd.to_numeric(group[name], errors="coerce")
        return values.replace([np.inf, -np.inf], np.nan).fillna(default).astype(np.float64)

    distance = col("distance", 8.0).clip(lower=0.0)
    inverse_distance = 1.0 / (1.0 + distance)
    inverse_distance2 = inverse_distance * inverse_distance
    inverse_distance3 = inverse_distance2 * inverse_distance
    sequence_offset = col("sequence_offset", 99.0)
    offset_closeness = 1.0 / (1.0 + sequence_offset.abs())
    orientation = col("orientation_cos", 0.0).abs().clip(upper=1.0)
    hbond = col("hbond_score", 0.0).clip(lower=-1.0, upper=1.0)
    ring = col("ring_score", 0.0).clip(lower=-1.0, upper=1.0)
    electrostatic = col("electrostatic_score", 0.0).abs()
    peptide = col("peptide_plane_score", 0.0).clip(lower=-1.0, upper=1.0)
    explicit_score = col("edge_score", np.nan)
    edge_class = group["edge_class"].astype(str).str.lower()

    score = inverse_distance + 0.05 * orientation
    sequence_mask = edge_class.str.contains("sequence", regex=False)
    peptide_mask = edge_class.str.contains("peptide", regex=False) | edge_class.str.contains(
        "carbonyl",
        regex=False,
    )
    hbond_mask = edge_class.str.contains("hbond", regex=False) | edge_class.str.contains(
        "exchange",
        regex=False,
    )
    ring_mask = edge_class.str.contains("ring", regex=False) | edge_class.str.contains(
        "aromatic",
        regex=False,
    )
    electrostatic_mask = edge_class.str.contains(
        "electrostatic",
        regex=False,
    ) | edge_class.str.contains("charge", regex=False) | edge_class.str.contains(
        "sulfur",
        regex=False,
    )
    contact_mask = edge_class.str.contains("contact", regex=False) | edge_class.str.contains(
        "spatial",
        regex=False,
    )

    score = score.where(~sequence_mask, 0.75 * offset_closeness + 0.25 * inverse_distance)
    score = score.where(
        ~peptide_mask,
        peptide.abs() + 0.25 * offset_closeness + 0.15 * inverse_distance,
    )
    score = score.where(
        ~hbond_mask,
        hbond.clip(lower=0.0)
        + 0.18 * orientation
        + 0.08 * inverse_distance
        + 0.05 * inverse_distance2
        + 0.025 * inverse_distance3,
    )
    score = score.where(
        ~ring_mask,
        ring.clip(lower=0.0) + 0.20 * orientation + 0.10 * inverse_distance,
    )
    score = score.where(
        ~electrostatic_mask,
        np.tanh(electrostatic) + 0.10 * inverse_distance,
    )
    score = score.where(~contact_mask, inverse_distance + 0.10 * orientation)
    return explicit_score.where(np.isfinite(explicit_score), score).astype(np.float64)


def _bioemu_neighborhood_sidecar_feature_summary(group: pd.DataFrame) -> np.ndarray:
    def mean_col(name: str, default: float = 0.0) -> float:
        if name not in group.columns:
            return default
        values = pd.to_numeric(group[name], errors="coerce")
        finite = values[np.isfinite(values)]
        if finite.empty:
            return default
        return float(finite.mean())

    distance = mean_col("distance", 0.0)
    sequence_offset = mean_col("sequence_offset", 0.0)
    edge_rank = mean_col("edge_rank", 0.0)
    values = np.asarray(
        [
            1.0 / (1.0 + max(distance, 0.0)),
            float(np.clip(sequence_offset / 8.0, -1.0, 1.0)),
            float(np.clip(mean_col("orientation_cos", 0.0), -1.0, 1.0)),
            float(np.clip(mean_col("hbond_score", 0.0), -1.0, 1.0)),
            float(np.clip(mean_col("ring_score", 0.0), -1.0, 1.0)),
            math.tanh(mean_col("electrostatic_score", 0.0)),
            float(np.clip(mean_col("peptide_plane_score", 0.0), -1.0, 1.0)),
            1.0 / (1.0 + max(edge_rank, 0.0)),
        ],
        dtype=np.float32,
    )
    return np.nan_to_num(values, nan=0.0, posinf=0.0, neginf=0.0)


def _bioemu_neighborhood_sidecar_prefers_dense_sample_slots(
    sidecar: dict[tuple[str, int, int], np.ndarray],
    *,
    entity_uid: str,
    sample_count: int,
    sample_index_map: tuple[int, ...] | list[int] | np.ndarray | None,
) -> bool:
    """Keep legacy fixture-built sidecars on dense slots when they expose them.

    CS sidecars are indexed by original BioEmu candidate ids, while older
    neighborhood sidecars built directly from dense fixture tensors are indexed
    by posterior slot 0..K-1.  Sparse generated-support neighborhood sidecars
    still require the candidate-index map.  Prefer dense slots only when the
    sidecar contains the complete dense support for this entity.
    """

    if sample_index_map is None or sample_count <= 0:
        return False
    try:
        map_prefix = [int(sample_index_map[index]) for index in range(int(sample_count))]
    except Exception:
        return False
    if map_prefix == list(range(int(sample_count))):
        return False
    needed = set(range(int(sample_count)))
    seen: set[int] = set()
    for key in sidecar:
        key_entity, key_sample_index, _ = key
        if str(key_entity) != str(entity_uid):
            continue
        sample_index = int(key_sample_index)
        if sample_index in needed:
            seen.add(sample_index)
            if len(seen) == int(sample_count):
                return True
    return False


def _bioemu_neighborhood_sidecar_tensor_for_example(
    sidecar: dict[tuple[str, int, int], np.ndarray] | None,
    *,
    example: PreparedCandidateFreeExample,
    sample_count: int,
    device: torch.device,
    sample_index_map: tuple[int, ...] | list[int] | np.ndarray | None = None,
) -> torch.Tensor | None:
    if not sidecar or sample_count <= 0 or not example.target_ids:
        return None
    feature_count = len(BIOEMU_NEIGHBORHOOD_SIDECAR_FEATURE_COLUMNS)
    values = np.zeros((int(sample_count), len(example.target_ids), feature_count), dtype=np.float32)
    entity_uid = str(example.entity_uid)
    use_dense_sample_slots = _bioemu_neighborhood_sidecar_prefers_dense_sample_slots(
        sidecar,
        entity_uid=entity_uid,
        sample_count=int(sample_count),
        sample_index_map=sample_index_map,
    )
    for row_index, target_id in enumerate(example.target_ids):
        residue_indices = _candidate_residue_indices_for_target(example, row_index, target_id)
        if not residue_indices:
            continue
        for sample_index in range(int(sample_count)):
            sidecar_sample_index = (
                int(sample_index)
                if use_dense_sample_slots
                else _bridge_audit_sidecar_sample_index(
                    sample_index,
                    sample_index_map,
                )
            )
            for residue_index in residue_indices:
                summary = sidecar.get((entity_uid, sidecar_sample_index, residue_index))
                if summary is not None:
                    values[sample_index, row_index, :] = summary
                    break
    if not np.any(np.abs(values) > 1.0e-8):
        return None
    return torch.as_tensor(values, dtype=torch.float32, device=device)


def _candidate_residue_indices_for_target(
    example: PreparedCandidateFreeExample,
    row_index: int,
    target_id: str,
) -> list[int]:
    parsed = parse_chemical_shift_target_id(target_id)
    target_features = example.target_features[row_index]
    parsed_residue_index = parsed["residue_index"] or 0
    candidate_residue_indices: list[int] = []
    if len(target_features) > FEATURE_ALIGNED_RESIDUE_INDEX:
        aligned_value = float(target_features[FEATURE_ALIGNED_RESIDUE_INDEX])
        if math.isfinite(aligned_value):
            candidate_residue_indices.append(int(round(aligned_value)))
    if parsed_residue_index:
        candidate_residue_indices.append(int(parsed_residue_index))
    return list(dict.fromkeys(candidate_residue_indices))


def _load_bioemu_ucbshift_cnnls_teacher_weights(
    *,
    config: StudentTrainingConfig,
    data_root: Path,
) -> dict[str, np.ndarray]:
    path_value = config.bioemu_ucbshift_cnnls_teacher_weights_path
    if not path_value:
        return {}
    path = Path(str(path_value))
    if not path.is_absolute():
        path = data_root / path
    if not path.exists():
        if (
            float(config.bioemu_ucbshift_cnnls_teacher_kl_weight) > 0.0
            or _cs_reweighting_teacher_prior_kl_weight(config) > 0.0
        ):
            raise FileNotFoundError(
                "BioEmu CS-reweighting teacher-weight loss is enabled but "
                f"teacher weights were not found: {path}"
            )
        return {}
    if path.suffix.lower() == ".parquet":
        frame = pd.read_parquet(path)
    elif path.suffix.lower() in {".tsv", ".tab"}:
        frame = pd.read_csv(path, sep="\t")
    else:
        frame = pd.read_csv(path)
    required = {"entity_uid", "sample_index", "teacher_weight"}
    missing = required - set(frame.columns)
    if missing:
        raise ValueError(
            "BioEmu UCBShift/CNNLS teacher weight table requires columns "
            f"{sorted(required)}; missing {sorted(missing)}."
        )
    result: dict[str, np.ndarray] = {}
    for entity_uid, group in frame.groupby("entity_uid", sort=False):
        ordered = group.sort_values("sample_index", kind="stable")
        weights = pd.to_numeric(
            ordered["teacher_weight"],
            errors="coerce",
        ).to_numpy(np.float64)
        weights = np.nan_to_num(weights, nan=0.0, posinf=0.0, neginf=0.0)
        total = float(weights.sum())
        if total <= 0.0:
            continue
        result[str(entity_uid)] = weights / total
    return result


def _load_bioemu_ucbshift_cnnls_teacher_predictions(
    *,
    config: StudentTrainingConfig,
    data_root: Path,
) -> dict[str, dict[str, dict[str, float]]]:
    path_value = (
        config.bioemu_ucbshift_cnnls_teacher_predictions_path
        or config.bioemu_cs_reweighting_teacher_predictions_path
    )
    if not path_value:
        return {}
    path = Path(str(path_value))
    if not path.is_absolute():
        path = data_root / path
    if not path.exists():
        if _cs_reweighting_teacher_mean_loss_weight(config) > 0.0:
            raise FileNotFoundError(
                "CS-reweighting teacher mean loss is enabled but "
                f"teacher predictions were not found: {path}"
            )
        return {}
    if path.suffix.lower() == ".parquet":
        frame = pd.read_parquet(path)
    elif path.suffix.lower() in {".tsv", ".tab"}:
        frame = pd.read_csv(path, sep="\t")
    else:
        frame = pd.read_csv(path)
    required = {"entity_uid", "target_id", "teacher_mean"}
    missing = required - set(frame.columns)
    if missing:
        raise ValueError(
            "BioEmu UCBShift/CNNLS teacher prediction table requires columns "
            f"{sorted(required)}; missing {sorted(missing)}."
        )
    result: dict[str, dict[str, dict[str, float]]] = {}
    for entity_uid, group in frame.groupby("entity_uid", sort=False):
        entity_predictions: dict[str, dict[str, float]] = {}
        for row in group.itertuples(index=False):
            row_values = row._asdict()
            value = float(row_values["teacher_mean"])
            if not math.isfinite(value):
                continue
            entity_predictions[str(row_values["target_id"])] = {
                "mean": value,
                "reliability": _teacher_prediction_reliability(
                    row_values,
                    config=config,
                ),
            }
        if entity_predictions:
            result[str(entity_uid)] = entity_predictions
    return result


def _load_bioemu_ucbshift_cnnls_teacher_guard(
    *,
    config: StudentTrainingConfig,
    data_root: Path,
) -> dict[str, set[str]]:
    guarded: dict[str, set[str]] = {}
    path_value = (
        config.bioemu_ucbshift_cnnls_teacher_guard_path
        or config.bioemu_cs_reweighting_teacher_guard_path
    )
    if path_value:
        path = _resolve_guard_table_path(path_value, data_root=data_root)
        frame = _read_guard_table(path)
        required = {"top_atom_family", "outlier_entities"}
        missing = required - set(frame.columns)
        if missing:
            raise ValueError(
                "BioEmu UCBShift/CNNLS teacher guard table requires columns "
                f"{sorted(required)}; missing {sorted(missing)}."
            )

        guard_families = {
            str(name)
            for name in config.bioemu_ucbshift_cnnls_teacher_guard_families
            if str(name)
        }
        min_fraction = max(
            float(config.bioemu_ucbshift_cnnls_teacher_guard_min_outlier_fraction),
            0.0,
        )
        for row in frame.itertuples(index=False):
            family = str(getattr(row, "top_atom_family", "")).strip()
            if not family or (guard_families and family not in guard_families):
                continue
            action = str(getattr(row, "recommended_guard_action", "")).strip().lower()
            if action.startswith("no "):
                continue
            fraction = _safe_float(
                getattr(row, "quality_outlier_fraction", float("nan")),
                default=1.0,
            )
            repeated = _truthy_value(getattr(row, "repeated_quality_outlier", False))
            if math.isfinite(fraction) and fraction < min_fraction and not repeated:
                continue
            entities = str(getattr(row, "outlier_entities", "")).replace(";", ",")
            for entity_uid in entities.split(","):
                entity_uid = entity_uid.strip()
                if entity_uid:
                    guarded.setdefault(entity_uid, set()).add(family)

    detached_path_value = str(
        getattr(config, "bioemu_detached_support_guard_path", "") or ""
    ).strip()
    if detached_path_value:
        detached_path = _resolve_guard_table_path(
            detached_path_value,
            data_root=data_root,
        )
        detached = _read_guard_table(detached_path)
        required = {"entity_uid", "top_atom_family"}
        missing = required - set(detached.columns)
        if missing:
            raise ValueError(
                "BioEmu detached support guard table requires columns "
                f"{sorted(required)}; missing {sorted(missing)}."
            )
        allowed_levels = {
            str(level).strip()
            for level in config.bioemu_detached_support_guard_levels
            if str(level).strip()
        }
        min_priority = max(
            float(config.bioemu_detached_support_guard_min_priority),
            0.0,
        )
        guard_families = {
            str(name)
            for name in config.bioemu_ucbshift_cnnls_teacher_guard_families
            if str(name)
        }
        for row in detached.itertuples(index=False):
            entity_uid = str(getattr(row, "entity_uid", "")).strip()
            family = str(getattr(row, "top_atom_family", "")).strip()
            if not entity_uid or not family:
                continue
            if guard_families and family not in guard_families:
                continue
            level = str(getattr(row, "support_guard_level", "")).strip()
            if allowed_levels and level not in allowed_levels:
                continue
            priority = _safe_float(
                getattr(row, "combined_priority_score", float("nan")),
                default=0.0,
            )
            if priority < min_priority:
                continue
            guarded.setdefault(entity_uid, set()).add(family)
    return guarded


def _resolve_guard_table_path(path_value: str | Path, *, data_root: Path) -> Path:
    path = Path(str(path_value))
    if not path.is_absolute():
        path = data_root / path
    if not path.exists():
        raise FileNotFoundError(
            "BioEmu teacher/support guard path was set but not found: "
            f"{path}"
        )
    return path


def _read_guard_table(path: Path) -> pd.DataFrame:
    if path.suffix.lower() == ".parquet":
        return pd.read_parquet(path)
    if path.suffix.lower() in {".tsv", ".tab"}:
        return pd.read_csv(path, sep="\t")
    return pd.read_csv(path)


def _attach_bioemu_ucbshift_teacher_outputs(
    *,
    outputs: dict[str, torch.Tensor],
    cnnls_teacher_weights: dict[str, np.ndarray] | None,
    cnnls_teacher_predictions: dict[str, dict[str, dict[str, float]]] | None,
    cnnls_teacher_guard: dict[str, set[str]] | None,
    example: PreparedCandidateFreeExample,
    config: StudentTrainingConfig,
    device: torch.device,
) -> dict[str, float]:
    guard_families = _teacher_guard_families_for_example(
        cnnls_teacher_guard,
        entity_uid=example.entity_uid,
    )
    terms: dict[str, float] = {}
    if guard_families:
        terms["ucbshift_cnnls_teacher_guarded_examples"] = 1.0
        terms["ucbshift_cnnls_teacher_guarded_family_count"] = float(
            len(guard_families)
        )

    if not (guard_families and config.bioemu_ucbshift_cnnls_teacher_guard_exclude_kl):
        teacher_weights = _teacher_weight_tensor_for_example(
            cnnls_teacher_weights,
            entity_uid=example.entity_uid,
            sample_count=int(outputs["sample_weights"].numel()),
            min_weight_count=int(config.bioemu_ucbshift_cnnls_teacher_min_weight_count),
            device=device,
        )
        if teacher_weights is not None:
            outputs["teacher_sample_weights"] = teacher_weights
    elif guard_families:
        terms["ucbshift_cnnls_teacher_guarded_kl_examples"] = 1.0

    teacher_mu, teacher_mu_mask, teacher_row_weight = _teacher_prediction_tensors_for_example(
        cnnls_teacher_predictions,
        example=example,
        device=device,
    )
    if teacher_mu is None or teacher_mu_mask is None or teacher_row_weight is None:
        return terms
    if guard_families and config.bioemu_ucbshift_cnnls_teacher_guard_exclude_mean_loss:
        before = int(torch.count_nonzero(teacher_mu_mask).detach().cpu())
        teacher_mu_mask = _guard_teacher_prediction_mask(
            teacher_mu_mask,
            example=example,
            guard_families=guard_families,
        )
        after = int(torch.count_nonzero(teacher_mu_mask).detach().cpu())
        skipped = max(before - after, 0)
        if skipped:
            terms["ucbshift_cnnls_teacher_guarded_mean_rows"] = float(skipped)
    if torch.count_nonzero(teacher_mu_mask) > 0:
        outputs["ucbshift_cnnls_teacher_mu"] = teacher_mu
        outputs["ucbshift_cnnls_teacher_mu_mask"] = teacher_mu_mask
        outputs["ucbshift_cnnls_teacher_row_weight"] = teacher_row_weight
        if bool(config.bioemu_ucbshift_cnnls_teacher_reliability_weighting):
            active_weight = teacher_row_weight[teacher_mu_mask].float()
            terms["ucbshift_cnnls_teacher_reliability_mean"] = float(
                torch.mean(active_weight).detach().cpu()
            )
            terms["ucbshift_cnnls_teacher_reliability_min"] = float(
                torch.min(active_weight).detach().cpu()
            )
    return terms


def _teacher_guard_families_for_example(
    guard_by_entity: dict[str, set[str]] | None,
    *,
    entity_uid: str,
) -> set[str]:
    if not guard_by_entity:
        return set()
    return set(guard_by_entity.get(str(entity_uid), set()))


def _guard_teacher_prediction_mask(
    mask: torch.Tensor,
    *,
    example: PreparedCandidateFreeExample,
    guard_families: set[str],
) -> torch.Tensor:
    if not guard_families:
        return mask
    guarded_mask = mask.clone()
    for row_index, target_id in enumerate(example.target_ids):
        parsed = parse_chemical_shift_target_id(str(target_id))
        if str(parsed["atom_family"]) in guard_families:
            guarded_mask[row_index] = False
    return guarded_mask


def _truthy_value(value: Any) -> bool:
    if isinstance(value, bool):
        return value
    if value is None:
        return False
    text = str(value).strip().lower()
    return text in {"1", "true", "yes", "y", "on"}


def _safe_float(value: Any, *, default: float) -> float:
    try:
        result = float(value)
    except (TypeError, ValueError):
        return default
    return result if math.isfinite(result) else default


def _teacher_prediction_reliability(
    row_values: dict[str, Any],
    *,
    config: StudentTrainingConfig,
) -> float:
    if not bool(config.bioemu_ucbshift_cnnls_teacher_reliability_weighting):
        return 1.0
    min_weight = min(
        max(float(config.bioemu_ucbshift_cnnls_teacher_reliability_min_weight), 0.0),
        1.0,
    )
    weight = 1.0

    ess_floor = max(
        float(config.bioemu_ucbshift_cnnls_teacher_reliability_ess_floor),
        0.0,
    )
    if ess_floor > 0.0:
        ess = _safe_float(row_values.get("teacher_ess"), default=ess_floor)
        weight *= min(1.0, max(min_weight, ess / ess_floor))

    entropy_floor = max(
        float(config.bioemu_ucbshift_cnnls_teacher_reliability_entropy_floor),
        0.0,
    )
    if entropy_floor > 0.0:
        entropy = _safe_float(
            row_values.get("teacher_entropy"),
            default=entropy_floor,
        )
        weight *= min(1.0, max(min_weight, entropy / entropy_floor))

    top_source = str(row_values.get("top_source", "")).strip()
    top_mass = _safe_float(row_values.get("top_source_mass"), default=0.0)
    threshold = min(
        max(
            float(
                config.bioemu_ucbshift_cnnls_teacher_reliability_non_bioemu_source_threshold
            ),
            0.0,
        ),
        1.0,
    )
    if top_source and top_source != "BioEmu" and top_mass > threshold:
        excess = (top_mass - threshold) / max(1.0 - threshold, 1.0e-6)
        weight *= min(1.0, max(min_weight, 1.0 - excess))

    atom_family = str(row_values.get("atom_family", "")).strip()
    tolerance = TEACHER_RELIABILITY_FAMILY_TOLERANCES.get(atom_family)
    support_gap_floor = min(
        max(
            float(config.bioemu_ucbshift_cnnls_teacher_reliability_support_gap_floor),
            min_weight,
        ),
        1.0,
    )
    delta = _safe_float(row_values.get("bioemu_only_delta"), default=float("nan"))
    if tolerance is not None and math.isfinite(delta) and abs(delta) > tolerance:
        weight *= min(1.0, max(support_gap_floor, tolerance / max(abs(delta), 1.0e-8)))

    valid_fraction = _safe_float(
        row_values.get("valid_candidate_fraction"),
        default=1.0,
    )
    weight *= min(1.0, max(min_weight, valid_fraction))

    inlier_responsibility = _safe_float(
        row_values.get("teacher_inlier_responsibility_mean"),
        default=1.0,
    )
    weight *= min(1.0, max(min_weight, inlier_responsibility))

    adaptive_floor_met = _safe_float(
        row_values.get("adaptive_lambda_floor_met"),
        default=1.0,
    )
    if adaptive_floor_met < 0.5:
        weight *= min(
            1.0,
            max(
                min_weight,
                float(
                    config.bioemu_ucbshift_cnnls_teacher_reliability_adaptive_floor_unmet_weight
                ),
            ),
        )

    return min(1.0, max(min_weight, weight))


def _teacher_weight_tensor_for_example(
    teacher_weights_by_entity: dict[str, np.ndarray] | None,
    *,
    entity_uid: str,
    sample_count: int,
    min_weight_count: int,
    device: torch.device,
) -> torch.Tensor | None:
    if not teacher_weights_by_entity:
        return None
    weights = teacher_weights_by_entity.get(str(entity_uid))
    if weights is None:
        return None
    safe_count = int(sample_count)
    if safe_count <= 0 or len(weights) < max(int(min_weight_count), safe_count):
        return None
    trimmed = np.asarray(weights[:safe_count], dtype=np.float64)
    total = float(trimmed.sum())
    if total <= 0.0:
        return None
    trimmed = trimmed / total
    return torch.as_tensor(trimmed, dtype=torch.float32, device=device)


def _teacher_prediction_tensors_for_example(
    teacher_predictions_by_entity: dict[str, dict[str, dict[str, float]]] | None,
    *,
    example: PreparedCandidateFreeExample,
    device: torch.device,
) -> tuple[torch.Tensor | None, torch.Tensor | None, torch.Tensor | None]:
    if not teacher_predictions_by_entity:
        return None, None, None
    teacher_by_target = teacher_predictions_by_entity.get(str(example.entity_uid))
    if not teacher_by_target:
        return None, None, None
    values: list[float] = []
    mask: list[bool] = []
    reliability: list[float] = []
    for target_id in example.target_ids:
        record = teacher_by_target.get(str(target_id))
        if record is None:
            values.append(0.0)
            mask.append(False)
            reliability.append(0.0)
            continue
        if isinstance(record, dict):
            value = record.get("mean")
            row_weight = _safe_float(record.get("reliability"), default=1.0)
        else:
            value = record
            row_weight = 1.0
        if value is None or not math.isfinite(float(value)):
            values.append(0.0)
            mask.append(False)
            reliability.append(0.0)
        else:
            values.append(float(value))
            mask.append(True)
            reliability.append(min(max(float(row_weight), 0.0), 1.0))
    if not any(mask):
        return None, None, None
    return (
        torch.as_tensor(values, dtype=torch.float32, device=device),
        torch.as_tensor(mask, dtype=torch.bool, device=device),
        torch.as_tensor(reliability, dtype=torch.float32, device=device),
    )


def _bioemu_cs_reweighting_generated_prior_distribution_loss(
    *,
    outputs: dict[str, torch.Tensor],
    config: StudentTrainingConfig,
    target_values: torch.Tensor,
    family_indices: torch.Tensor | None = None,
    row_mask: torch.Tensor | None = None,
) -> tuple[torch.Tensor, dict[str, float]]:
    """Align BioEmu generated prior mass to the CS-reweighted posterior q."""

    prefix = "cs_reweighting_teacher_generated_prior"
    kl_weight = max(float(config.bioemu_cs_reweighting_teacher_generated_prior_kl_weight), 0.0)
    topk_weight = max(
        float(config.bioemu_cs_reweighting_teacher_generated_prior_topk_mass_loss_weight),
        0.0,
    )
    listwise_weight = max(
        float(config.bioemu_cs_reweighting_teacher_generated_prior_topk_listwise_weight),
        0.0,
    )
    top1_weight = max(
        float(config.bioemu_cs_reweighting_teacher_generated_prior_top1_nll_weight),
        0.0,
    )
    tail_mass_weight = max(
        float(
            config.bioemu_cs_reweighting_teacher_generated_prior_tail_mass_loss_weight
        ),
        0.0,
    )
    ess_weight = max(
        float(
            config.bioemu_cs_reweighting_teacher_generated_prior_student_ess_floor_loss_weight
        ),
        0.0,
    )
    top_mass_weight = max(
        float(
            config.bioemu_cs_reweighting_teacher_generated_prior_student_top_mass_cap_loss_weight
        ),
        0.0,
    )
    ccc_floor_weight = max(
        float(
            config.bioemu_cs_reweighting_teacher_generated_prior_ccc_floor_loss_weight
        ),
        0.0,
    )
    macro_ccc_floor_weight = max(
        float(
            config.bioemu_cs_reweighting_teacher_generated_prior_macro_ccc_floor_loss_weight
        ),
        0.0,
    )
    energy_std_weight = max(
        float(
            config.bioemu_cs_reweighting_teacher_generated_prior_energy_std_loss_weight
        ),
        0.0,
    )
    energy_shape_weight = max(
        float(
            config.bioemu_cs_reweighting_teacher_generated_prior_energy_shape_loss_weight
        ),
        0.0,
    )
    energy_rank_weight = max(
        float(
            config.bioemu_cs_reweighting_teacher_generated_prior_energy_rank_loss_weight
        ),
        0.0,
    )
    energy_corr_weight = max(
        float(
            config.bioemu_cs_reweighting_teacher_generated_prior_energy_corr_loss_weight
        ),
        0.0,
    )
    total_configured_weight = (
        kl_weight
        + topk_weight
        + listwise_weight
        + top1_weight
        + tail_mass_weight
        + ess_weight
        + top_mass_weight
        + ccc_floor_weight
        + macro_ccc_floor_weight
        + energy_std_weight
        + energy_shape_weight
        + energy_rank_weight
        + energy_corr_weight
    )
    zero = target_values.new_tensor(0.0)
    if total_configured_weight <= 0.0:
        return zero, {}

    sample_log_prob, log_prob_source = _bioemu_generated_prior_log_prob_tensor(
        outputs=outputs,
        config=config,
    )
    metrics: dict[str, float] = {
        f"{prefix}_configured_weight": float(total_configured_weight),
        f"{prefix}_log_prob_source_{log_prob_source}": 1.0,
    }
    teacher_sample_weights = outputs.get("teacher_sample_weights")
    teacher_source = "accepted_teacher_bundle"
    strict_qpaper_teacher_required = bool(
        getattr(
            config,
            "bioemu_cs_reweighting_teacher_generated_prior_tail_mass_contract_required",
            False,
        )
        and getattr(
            config,
            "bioemu_x0_external_global_family_teacher_require_paper_cs_reweighting_lineage",
            False,
        )
    )
    if strict_qpaper_teacher_required:
        metrics[f"{prefix}_strict_qpaper_teacher_required"] = 1.0
    if not torch.is_tensor(teacher_sample_weights) and bool(
        config.bioemu_cs_reweighting_teacher_generated_prior_online_proxy_teacher_enabled
    ):
        if strict_qpaper_teacher_required:
            metrics[
                f"{prefix}_online_proxy_teacher_blocked_by_strict_qpaper_contract"
            ] = 1.0
        else:
            teacher_sample_weights, proxy_metrics = (
                _bioemu_cs_reweighting_generated_prior_online_proxy_teacher(
                    outputs=outputs,
                    config=config,
                    target_values=target_values,
                    family_indices=family_indices,
                    row_mask=row_mask,
                    prefix=prefix,
                )
            )
            metrics.update(proxy_metrics)
            if torch.is_tensor(teacher_sample_weights):
                teacher_source = "online_proxy_cs_reweighted_generated_support"
    if not torch.is_tensor(teacher_sample_weights) or not torch.is_tensor(sample_log_prob):
        metrics[f"{prefix}_missing_teacher_or_log_prob"] = 1.0
        if torch.is_tensor(teacher_sample_weights):
            metrics[f"{prefix}_teacher_rows"] = float(
                teacher_sample_weights.reshape(-1).numel()
            )
        if torch.is_tensor(sample_log_prob):
            metrics[f"{prefix}_generated_rows"] = float(
                sample_log_prob.reshape(-1).numel()
            )
        return zero, metrics
    safe_teacher_source = re.sub(
        r"[^0-9A-Za-z_]+",
        "_",
        teacher_source,
    ).strip("_").lower()
    metrics[f"{prefix}_teacher_source_{safe_teacher_source}"] = 1.0

    teacher = teacher_sample_weights.reshape(-1).to(
        device=target_values.device,
        dtype=target_values.dtype,
    )
    generator_log_prob = sample_log_prob.reshape(-1).to(
        device=target_values.device,
        dtype=target_values.dtype,
    )
    if teacher.numel() != generator_log_prob.numel() or teacher.numel() < 2:
        metrics[f"{prefix}_shape_mismatch"] = 1.0
        metrics[f"{prefix}_teacher_rows"] = float(teacher.numel())
        metrics[f"{prefix}_generated_rows"] = float(generator_log_prob.numel())
        return zero, metrics
    if (
        bool(config.bioemu_cs_reweighting_teacher_require_generated_prior_grad)
        and not bool(generator_log_prob.requires_grad)
    ):
        metrics[f"{prefix}_missing_generated_prior_grad"] = 1.0
        metrics[f"{prefix}_generated_requires_grad"] = 0.0
        return zero, metrics

    teacher = torch.nan_to_num(teacher, nan=0.0, posinf=0.0, neginf=0.0).clamp_min(
        0.0
    )
    if float(torch.sum(teacher).detach().cpu()) <= 0.0:
        metrics[f"{prefix}_empty_teacher_mass"] = 1.0
        return zero, metrics
    teacher = teacher / teacher.sum().clamp_min(1.0e-12)
    cosat_blend = min(
        max(float(config.bioemu_cs_reweighting_teacher_generated_prior_cosat_blend), 0.0),
        1.0,
    )
    if (
        cosat_blend > 0.0
        and teacher_source != "online_proxy_cs_reweighted_generated_support"
    ):
        sample_mu = outputs.get("sample_mu")
        can_build_cosat = (
            torch.is_tensor(sample_mu)
            and sample_mu.ndim == 2
            and int(sample_mu.shape[0]) == int(teacher.numel())
            and int(sample_mu.shape[-1]) == int(target_values.numel())
            and torch.is_tensor(family_indices)
            and int(family_indices.reshape(-1).numel()) == int(target_values.numel())
        )
        if can_build_cosat:
            sample_mu = sample_mu.to(device=target_values.device, dtype=target_values.dtype)
            row_mask_tensor = (
                row_mask.to(device=target_values.device, dtype=torch.bool)
                if torch.is_tensor(row_mask)
                and int(row_mask.reshape(-1).numel()) == int(target_values.numel())
                else torch.ones_like(target_values, dtype=torch.bool)
            )
            row_family_indices = family_indices.to(
                device=target_values.device
            ).long().reshape(-1)
            selected = (
                row_mask_tensor
                & torch.isfinite(target_values)
                & torch.all(torch.isfinite(sample_mu), dim=0)
            )
            configured_focus = [
                _normalized_atom_family_key(name)
                for name in config.bioemu_cs_reweighting_teacher_generated_prior_cosat_focus_families
            ]
            focus_families = [
                family for family in configured_focus if family in CHEMICAL_SHIFT_FAMILIES
            ] or list(CHEMICAL_SHIFT_FAMILIES)
            required_families = [
                _normalized_atom_family_key(name)
                for name in config.bioemu_cs_reweighting_teacher_generated_prior_cosat_required_families
            ]
            required_families = [
                family for family in required_families if family in CHEMICAL_SHIFT_FAMILIES
            ]
            fallback_families = [
                _normalized_atom_family_key(name)
                for name in config.bioemu_cs_reweighting_teacher_generated_prior_cosat_fallback_required_families
            ]
            fallback_families = [
                family for family in fallback_families if family in CHEMICAL_SHIFT_FAMILIES
            ]

            def _family_row_count(family_name: str) -> int:
                index = CHEMICAL_SHIFT_FAMILIES.index(family_name)
                return int(
                    torch.count_nonzero(
                        selected & (row_family_indices == int(index))
                    ).detach().cpu()
                )

            required_ok = bool(required_families) and all(
                _family_row_count(family) > 0 for family in required_families
            )
            fallback_rows = sum(_family_row_count(family) for family in fallback_families)
            fallback_ok = (
                bool(fallback_families)
                and all(_family_row_count(family) > 0 for family in fallback_families)
                and fallback_rows
                >= max(
                    int(
                        config.bioemu_cs_reweighting_teacher_generated_prior_cosat_fallback_min_rows
                    ),
                    0,
                )
            )
            active_families = required_families if required_ok else (
                fallback_families if fallback_ok else focus_families
            )
            active_families = [
                family for family in active_families if _family_row_count(family) > 0
            ]
            min_family_count = max(
                int(config.bioemu_cs_reweighting_teacher_generated_prior_cosat_min_family_count),
                1,
            )
            if len(active_families) >= min_family_count:
                family_mask = torch.zeros_like(selected, dtype=torch.bool)
                for family in active_families:
                    family_index = CHEMICAL_SHIFT_FAMILIES.index(family)
                    family_mask = family_mask | (
                        selected & (row_family_indices == int(family_index))
                    )
                cosat_rows = int(torch.count_nonzero(family_mask).detach().cpu())
                if cosat_rows > 0:
                    cosat_phi = sample_mu[:, family_mask]
                    cosat_targets = target_values[family_mask].reshape(1, -1)
                    cosat_families = row_family_indices[family_mask].clamp(
                        min=0,
                        max=len(CHEMICAL_SHIFT_FAMILIES) - 1,
                    )
                    family_ppm_scales = target_values.new_tensor(
                        ATOM_FAMILY_PPM_SCALES
                    ).clamp_min(1.0e-3)
                    cosat_scales = family_ppm_scales[cosat_families].reshape(1, -1)
                    cosat_error = (cosat_phi.detach() - cosat_targets) / cosat_scales
                    configured_family_weights = {
                        _normalized_atom_family_key(name): max(float(value), 0.0)
                        for name, value in dict(
                            config.bioemu_cs_reweighting_teacher_generated_prior_cosat_family_weights
                        ).items()
                    }
                    row_weights = torch.ones(
                        cosat_rows,
                        device=target_values.device,
                        dtype=target_values.dtype,
                    )
                    if configured_family_weights:
                        row_weights = torch.zeros_like(row_weights)
                        for family, family_weight in configured_family_weights.items():
                            if family not in CHEMICAL_SHIFT_FAMILIES or family_weight <= 0.0:
                                continue
                            family_index = CHEMICAL_SHIFT_FAMILIES.index(family)
                            row_weights = torch.where(
                                cosat_families == int(family_index),
                                row_weights.new_full(row_weights.shape, family_weight),
                                row_weights,
                            )
                    active_row_weights = row_weights > 0.0
                    if bool(torch.any(active_row_weights)):
                        cosat_scale = max(
                            float(
                                config.bioemu_cs_reweighting_teacher_generated_prior_cosat_scale
                            ),
                            0.0,
                        )
                        cosat_energy = (
                            row_weights.reshape(1, -1)
                            * cosat_scale
                            * cosat_error.square()
                        ).sum(dim=1) / row_weights.sum().clamp_min(1.0e-12)
                        cosat_teacher = torch.softmax(-cosat_energy, dim=0)
                        cosat_power = max(
                            float(
                                config.bioemu_cs_reweighting_teacher_generated_prior_cosat_power
                            ),
                            1.0e-6,
                        )
                        if abs(cosat_power - 1.0) > 1.0e-6:
                            cosat_teacher = cosat_teacher.pow(cosat_power)
                            cosat_teacher = cosat_teacher / cosat_teacher.sum().clamp_min(
                                1.0e-12
                            )
                        teacher = (
                            (1.0 - cosat_blend) * teacher
                            + cosat_blend * cosat_teacher.detach()
                        )
                        teacher = teacher / teacher.sum().clamp_min(1.0e-12)
                        metrics[f"{prefix}_cosat_blend_applied"] = 1.0
                        metrics[f"{prefix}_cosat_blend"] = float(cosat_blend)
                        metrics[f"{prefix}_cosat_rows"] = float(cosat_rows)
                        metrics[f"{prefix}_cosat_family_count"] = float(
                            len(active_families)
                        )
                        metrics[f"{prefix}_cosat_used_required_families"] = (
                            1.0 if required_ok else 0.0
                        )
                        metrics[f"{prefix}_cosat_used_fallback_families"] = (
                            1.0 if (not required_ok and fallback_ok) else 0.0
                        )
                        metrics[f"{prefix}_cosat_teacher_ess"] = float(
                            (1.0 / cosat_teacher.square().sum().clamp_min(1.0e-12))
                            .detach()
                            .cpu()
                        )
                        metrics[f"{prefix}_cosat_teacher_top_mass"] = float(
                            torch.max(cosat_teacher).detach().cpu()
                        )
                    else:
                        metrics[f"{prefix}_cosat_inactive_zero_family_weights"] = 1.0
                else:
                    metrics[f"{prefix}_cosat_inactive_no_rows"] = 1.0
            else:
                metrics[f"{prefix}_cosat_inactive_family_count"] = float(
                    len(active_families)
                )
        else:
            metrics[f"{prefix}_cosat_missing_sample_mu_or_family_indices"] = 1.0
    generator_log_prob = torch.nan_to_num(
        generator_log_prob,
        nan=0.0,
        posinf=0.0,
        neginf=0.0,
    )
    temperature = max(
        float(config.bioemu_cs_reweighting_teacher_generated_prior_kl_temperature),
        1.0e-4,
    )
    generator_log_prior = torch.log_softmax(
        generator_log_prob / generator_log_prob.new_tensor(temperature),
        dim=0,
    )
    generator_prior = torch.exp(generator_log_prior)
    teacher_log = torch.log(teacher.clamp_min(1.0e-12))
    kl_loss = torch.sum(teacher * (teacher_log - generator_log_prior))
    total = kl_weight * kl_loss

    row_count = int(teacher.numel())
    topk_fraction = max(
        float(config.bioemu_cs_reweighting_teacher_generated_prior_topk_fraction),
        0.0,
    )
    topk_min_count = max(
        int(config.bioemu_cs_reweighting_teacher_generated_prior_topk_min_count),
        1,
    )
    topk_count = min(
        max(int(math.ceil(float(row_count) * topk_fraction)), topk_min_count),
        row_count,
    )
    teacher_top_indices = torch.topk(teacher.detach(), k=topk_count).indices
    teacher_top_mass = torch.sum(teacher.index_select(0, teacher_top_indices))
    generated_top_mass = torch.sum(
        generator_prior.index_select(0, teacher_top_indices)
    )
    target_top_mass = (
        teacher_top_mass
        * generator_prior.new_tensor(
            max(
                float(
                    config.bioemu_cs_reweighting_teacher_generated_prior_topk_target_mass_scale
                ),
                0.0,
            )
        )
    ).clamp(max=1.0)
    topk_deficit = torch.relu(target_top_mass.detach() - generated_top_mass)
    topk_loss = torch.square(topk_deficit)
    total = total + topk_weight * topk_loss

    listwise_loss = zero
    if topk_count >= 2:
        top_teacher = teacher.index_select(0, teacher_top_indices)
        top_teacher = top_teacher / top_teacher.sum().clamp_min(1.0e-12)
        top_student_log = torch.log_softmax(
            generator_log_prob.index_select(0, teacher_top_indices)
            / generator_log_prob.new_tensor(temperature),
            dim=0,
        )
        listwise_loss = torch.sum(
            top_teacher * (torch.log(top_teacher.clamp_min(1.0e-12)) - top_student_log)
        )
        total = total + listwise_weight * listwise_loss

    top1_index = int(torch.argmax(teacher.detach()).detach().cpu())
    top1_nll = -generator_log_prior[top1_index]
    total = total + top1_weight * top1_nll

    tail_fraction = max(
        float(config.bioemu_cs_reweighting_teacher_generated_prior_tail_fraction),
        0.0,
    )
    tail_min_count = max(
        int(config.bioemu_cs_reweighting_teacher_generated_prior_tail_min_count),
        1,
    )
    tail_count = min(
        max(int(math.ceil(float(row_count) * tail_fraction)), tail_min_count),
        row_count,
    )
    teacher_tail_indices = torch.topk(
        teacher.detach(),
        k=tail_count,
        largest=False,
    ).indices
    teacher_tail_mass = torch.sum(teacher.index_select(0, teacher_tail_indices))
    generated_tail_mass = torch.sum(
        generator_prior.index_select(0, teacher_tail_indices)
    )
    target_tail_mass = (
        teacher_tail_mass
        * generator_prior.new_tensor(
            max(
                float(
                    config.bioemu_cs_reweighting_teacher_generated_prior_tail_mass_cap_scale
                ),
                0.0,
            )
        )
    ).clamp(max=1.0)
    tail_mass_excess = torch.relu(generated_tail_mass - target_tail_mass.detach())
    tail_mass_loss = torch.square(tail_mass_excess)
    total = total + tail_mass_weight * tail_mass_loss

    generator_ess = 1.0 / torch.sum(torch.square(generator_prior)).clamp_min(1.0e-12)
    generator_top_mass = torch.max(generator_prior)
    teacher_ess = 1.0 / torch.sum(torch.square(teacher)).clamp_min(1.0e-12)
    teacher_top_mass_scalar = torch.max(teacher)
    ess_floor = max(
        float(config.bioemu_cs_reweighting_teacher_generated_prior_student_ess_floor),
        0.0,
    )
    ess_floor_loss = zero
    if ess_floor > 0.0:
        ess_floor_tensor = generator_prior.new_tensor(ess_floor)
        ess_floor_loss = torch.square(
            torch.relu(ess_floor_tensor - generator_ess)
            / ess_floor_tensor.clamp_min(1.0e-12)
        )
        total = total + ess_weight * ess_floor_loss
    top_mass_cap = max(
        float(config.bioemu_cs_reweighting_teacher_generated_prior_student_top_mass_cap),
        0.0,
    )
    top_mass_cap_loss = zero
    if top_mass_cap > 0.0:
        cap_tensor = generator_prior.new_tensor(top_mass_cap)
        top_mass_cap_loss = torch.square(
            torch.relu(generator_top_mass - cap_tensor)
            / cap_tensor.clamp_min(1.0e-12)
        )
        total = total + top_mass_weight * top_mass_cap_loss

    ccc_floor_loss = zero
    if ccc_floor_weight > 0.0 or macro_ccc_floor_weight > 0.0:
        sample_mu = outputs.get("sample_mu")
        can_apply_ccc_floor = (
            torch.is_tensor(sample_mu)
            and sample_mu.ndim == 2
            and int(sample_mu.shape[0]) == int(generator_prior.numel())
            and int(sample_mu.shape[-1]) == int(target_values.numel())
            and torch.is_tensor(family_indices)
            and int(family_indices.reshape(-1).numel()) == int(target_values.numel())
        )
        if can_apply_ccc_floor:
            row_mask_tensor = (
                row_mask.to(device=target_values.device, dtype=torch.bool)
                if torch.is_tensor(row_mask)
                and int(row_mask.reshape(-1).numel()) == int(target_values.numel())
                else torch.ones_like(target_values, dtype=torch.bool)
            )
            ccc_floor_loss, ccc_floor_terms = _bioemu_shared_q_witness_ccc_floor_loss(
                sample_mu=sample_mu.detach(),
                target_values=target_values,
                family_indices=family_indices,
                row_mask=row_mask_tensor,
                sample_weights=generator_prior,
                loss_weight=ccc_floor_weight,
                ccc_floors=config.bioemu_cs_reweighting_teacher_generated_prior_ccc_floors,
                family_weights=(
                    config.bioemu_cs_reweighting_teacher_generated_prior_ccc_family_weights
                    or config.bioemu_cs_reweighting_teacher_generated_prior_cosat_family_weights
                ),
                macro_ccc_floor=(
                    config.bioemu_cs_reweighting_teacher_generated_prior_macro_ccc_floor
                ),
                macro_ccc_floor_loss_weight=macro_ccc_floor_weight,
                use_gradient_projection=False,
                metric_prefix=f"{prefix}_ccc_floor",
            )
            total = total + ccc_floor_loss
            ccc_floor_terms[f"{prefix}_ccc_floor_uses_generated_prior_q"] = 1.0
            ccc_floor_terms[f"{prefix}_ccc_floor_sample_mu_detached"] = 1.0
            metrics.update(ccc_floor_terms)
        else:
            metrics[f"{prefix}_ccc_floor_missing_sample_mu_or_family_indices"] = 1.0

    eps = generator_prior.new_tensor(1.0e-6)
    teacher_energy = -teacher_log.detach()
    generated_energy = -generator_log_prior
    teacher_energy = teacher_energy - teacher_energy.mean()
    generated_energy = generated_energy - generated_energy.mean()
    teacher_energy_std = teacher_energy.std(unbiased=False)
    generated_energy_std = generated_energy.std(unbiased=False)
    energy_std_loss = zero
    if energy_std_weight > 0.0:
        energy_std_loss = F.smooth_l1_loss(
            torch.log(generated_energy_std.clamp_min(eps)),
            torch.log(teacher_energy_std.clamp_min(eps)),
            beta=max(
                float(
                    config.bioemu_cs_reweighting_teacher_generated_prior_energy_std_huber_beta
                ),
                1.0e-6,
            ),
            reduction="mean",
        )
        total = total + energy_std_weight * energy_std_loss
    generated_energy_z = generated_energy / generated_energy_std.clamp_min(eps)
    teacher_energy_z = teacher_energy / teacher_energy_std.clamp_min(eps)
    energy_shape_loss = zero
    if energy_shape_weight > 0.0:
        energy_shape_loss = F.smooth_l1_loss(
            generated_energy_z,
            teacher_energy_z.detach(),
            beta=max(
                float(
                    config.bioemu_cs_reweighting_teacher_generated_prior_energy_huber_beta
                ),
                1.0e-6,
            ),
            reduction="mean",
        )
        total = total + energy_shape_weight * energy_shape_loss
    energy_corr = torch.mean(generated_energy_z * teacher_energy_z.detach())
    energy_corr_loss = zero
    if energy_corr_weight > 0.0:
        energy_corr_loss = torch.relu(1.0 - energy_corr)
        total = total + energy_corr_weight * energy_corr_loss
    energy_rank_loss = zero
    energy_rank_gap = zero
    energy_rank_top_count = 0
    if energy_rank_weight > 0.0 and row_count >= 2:
        rank_fraction = max(
            float(
                config.bioemu_cs_reweighting_teacher_generated_prior_energy_rank_top_fraction
            ),
            0.0,
        )
        energy_rank_top_count = min(
            max(int(math.ceil(float(row_count) * rank_fraction)), 1),
            max(row_count // 2, 1),
        )
        if energy_rank_top_count > 0:
            high_q_indices = torch.topk(teacher.detach(), k=energy_rank_top_count).indices
            low_q_indices = torch.topk(
                teacher_energy.detach(),
                k=energy_rank_top_count,
            ).indices
            high_q_energy = generated_energy.index_select(0, high_q_indices)
            low_q_energy = generated_energy.index_select(0, low_q_indices)
            pair_gap = low_q_energy[:, None] - high_q_energy[None, :]
            energy_rank_gap = pair_gap.detach().mean()
            energy_rank_loss = torch.relu(
                generated_energy.new_tensor(
                    max(
                        float(
                            config.bioemu_cs_reweighting_teacher_generated_prior_energy_rank_margin
                        ),
                        0.0,
                    )
                )
                - pair_gap
            ).mean()
            total = total + energy_rank_weight * energy_rank_loss

    metrics.update(
        {
            f"{prefix}_loss": float(total.detach().cpu()),
            f"{prefix}_kl": float(kl_loss.detach().cpu()),
            f"{prefix}_kl_weight": float(kl_weight),
            f"{prefix}_topk_mass_loss": float(topk_loss.detach().cpu()),
            f"{prefix}_topk_mass_loss_weight": float(topk_weight),
            f"{prefix}_topk_count": float(topk_count),
            f"{prefix}_teacher_topk_mass": float(teacher_top_mass.detach().cpu()),
            f"{prefix}_generated_topk_mass": float(generated_top_mass.detach().cpu()),
            f"{prefix}_target_topk_mass": float(target_top_mass.detach().cpu()),
            f"{prefix}_topk_mass_deficit": float(topk_deficit.detach().cpu()),
            f"{prefix}_topk_listwise": float(listwise_loss.detach().cpu()),
            f"{prefix}_topk_listwise_weight": float(listwise_weight),
            f"{prefix}_top1_nll": float(top1_nll.detach().cpu()),
            f"{prefix}_top1_nll_weight": float(top1_weight),
            f"{prefix}_tail_mass_loss": float(tail_mass_loss.detach().cpu()),
            f"{prefix}_tail_mass_loss_weight": float(tail_mass_weight),
            f"{prefix}_tail_count": float(tail_count),
            f"{prefix}_teacher_tail_mass": float(teacher_tail_mass.detach().cpu()),
            f"{prefix}_generated_tail_mass": float(generated_tail_mass.detach().cpu()),
            f"{prefix}_target_tail_mass": float(target_tail_mass.detach().cpu()),
            f"{prefix}_tail_mass_excess": float(tail_mass_excess.detach().cpu()),
            f"{prefix}_teacher_ess": float(teacher_ess.detach().cpu()),
            f"{prefix}_generated_ess": float(generator_ess.detach().cpu()),
            f"{prefix}_student_ess_floor": float(ess_floor),
            f"{prefix}_student_ess_floor_loss": float(ess_floor_loss.detach().cpu()),
            f"{prefix}_student_ess_floor_loss_weight": float(ess_weight),
            f"{prefix}_teacher_top_mass": float(teacher_top_mass_scalar.detach().cpu()),
            f"{prefix}_generated_top_mass": float(generator_top_mass.detach().cpu()),
            f"{prefix}_student_top_mass_cap": float(top_mass_cap),
            f"{prefix}_student_top_mass_cap_loss": float(
                top_mass_cap_loss.detach().cpu()
            ),
            f"{prefix}_student_top_mass_cap_loss_weight": float(top_mass_weight),
            f"{prefix}_ccc_floor_loss": float(ccc_floor_loss.detach().cpu()),
            f"{prefix}_ccc_floor_loss_weight": float(ccc_floor_weight),
            f"{prefix}_macro_ccc_floor": float(
                config.bioemu_cs_reweighting_teacher_generated_prior_macro_ccc_floor
            ),
            f"{prefix}_macro_ccc_floor_loss_weight": float(macro_ccc_floor_weight),
            f"{prefix}_energy_std_loss": float(energy_std_loss.detach().cpu()),
            f"{prefix}_energy_std_loss_weight": float(energy_std_weight),
            f"{prefix}_energy_shape_loss": float(energy_shape_loss.detach().cpu()),
            f"{prefix}_energy_shape_loss_weight": float(energy_shape_weight),
            f"{prefix}_energy_rank_loss": float(energy_rank_loss.detach().cpu()),
            f"{prefix}_energy_rank_loss_weight": float(energy_rank_weight),
            f"{prefix}_energy_corr_loss": float(energy_corr_loss.detach().cpu()),
            f"{prefix}_energy_corr_loss_weight": float(energy_corr_weight),
            f"{prefix}_energy_corr": float(energy_corr.detach().cpu()),
            f"{prefix}_energy_rank_gap": float(energy_rank_gap.detach().cpu()),
            f"{prefix}_energy_rank_top_count": float(energy_rank_top_count),
            f"{prefix}_teacher_energy_std": float(teacher_energy_std.detach().cpu()),
            f"{prefix}_generated_energy_std": float(
                generated_energy_std.detach().cpu()
            ),
            f"{prefix}_rows": float(row_count),
            f"{prefix}_temperature": float(temperature),
            f"{prefix}_generated_requires_grad": (
                1.0 if bool(generator_log_prob.requires_grad) else 0.0
            ),
            f"{prefix}_posterior_population_is_one_shared_q": 1.0,
        }
    )
    return total, metrics


def _bioemu_cs_reweighting_generated_prior_online_proxy_teacher(
    *,
    outputs: dict[str, torch.Tensor],
    config: StudentTrainingConfig,
    target_values: torch.Tensor,
    family_indices: torch.Tensor | None,
    row_mask: torch.Tensor | None,
    prefix: str,
) -> tuple[torch.Tensor | None, dict[str, float]]:
    """Build an explicit non-final online CS proxy q over generated support."""

    metrics: dict[str, float] = {
        f"{prefix}_online_proxy_teacher_enabled": 1.0,
        f"{prefix}_online_proxy_teacher_not_final_acceptance": 1.0,
        f"{prefix}_online_proxy_teacher_ucbshift_invoked": 0.0,
    }
    sample_mu = outputs.get("sample_mu")
    can_build = (
        torch.is_tensor(sample_mu)
        and sample_mu.ndim == 2
        and int(sample_mu.shape[-1]) == int(target_values.numel())
        and torch.is_tensor(family_indices)
        and int(family_indices.reshape(-1).numel()) == int(target_values.numel())
    )
    if not can_build:
        metrics[f"{prefix}_online_proxy_teacher_missing_sample_mu_or_family_indices"] = (
            1.0
        )
        return None, metrics

    sample_mu = sample_mu.to(device=target_values.device, dtype=target_values.dtype)
    row_mask_tensor = (
        row_mask.to(device=target_values.device, dtype=torch.bool)
        if torch.is_tensor(row_mask)
        and int(row_mask.reshape(-1).numel()) == int(target_values.numel())
        else torch.ones_like(target_values, dtype=torch.bool)
    )
    row_family_indices = family_indices.to(device=target_values.device).long().reshape(-1)
    selected = (
        row_mask_tensor
        & torch.isfinite(target_values)
        & torch.all(torch.isfinite(sample_mu), dim=0)
    )
    configured_focus = [
        _normalized_atom_family_key(name)
        for name in config.bioemu_cs_reweighting_teacher_generated_prior_cosat_focus_families
    ]
    focus_families = [
        family for family in configured_focus if family in CHEMICAL_SHIFT_FAMILIES
    ] or list(CHEMICAL_SHIFT_FAMILIES)
    required_families = [
        _normalized_atom_family_key(name)
        for name in config.bioemu_cs_reweighting_teacher_generated_prior_cosat_required_families
    ]
    required_families = [
        family for family in required_families if family in CHEMICAL_SHIFT_FAMILIES
    ]
    fallback_families = [
        _normalized_atom_family_key(name)
        for name in (
            config.bioemu_cs_reweighting_teacher_generated_prior_cosat_fallback_required_families
        )
    ]
    fallback_families = [
        family for family in fallback_families if family in CHEMICAL_SHIFT_FAMILIES
    ]

    def _family_row_count(family_name: str) -> int:
        index = CHEMICAL_SHIFT_FAMILIES.index(family_name)
        return int(
            torch.count_nonzero(selected & (row_family_indices == int(index)))
            .detach()
            .cpu()
        )

    required_ok = bool(required_families) and all(
        _family_row_count(family) > 0 for family in required_families
    )
    fallback_rows = sum(_family_row_count(family) for family in fallback_families)
    fallback_ok = (
        bool(fallback_families)
        and all(_family_row_count(family) > 0 for family in fallback_families)
        and fallback_rows
        >= max(
            int(
                config.bioemu_cs_reweighting_teacher_generated_prior_cosat_fallback_min_rows
            ),
            0,
        )
    )
    active_families = required_families if required_ok else (
        fallback_families if fallback_ok else focus_families
    )
    active_families = [
        family for family in active_families if _family_row_count(family) > 0
    ]
    min_family_count = max(
        int(config.bioemu_cs_reweighting_teacher_generated_prior_cosat_min_family_count),
        1,
    )
    if len(active_families) < min_family_count:
        metrics[f"{prefix}_online_proxy_teacher_inactive_family_count"] = float(
            len(active_families)
        )
        return None, metrics

    family_mask = torch.zeros_like(selected, dtype=torch.bool)
    for family in active_families:
        family_index = CHEMICAL_SHIFT_FAMILIES.index(family)
        family_mask = family_mask | (selected & (row_family_indices == int(family_index)))
    proxy_rows = int(torch.count_nonzero(family_mask).detach().cpu())
    if proxy_rows <= 0:
        metrics[f"{prefix}_online_proxy_teacher_inactive_no_rows"] = 1.0
        return None, metrics

    proxy_mu = sample_mu[:, family_mask]
    proxy_targets = target_values[family_mask].reshape(1, -1)
    proxy_families = row_family_indices[family_mask].clamp(
        min=0,
        max=len(CHEMICAL_SHIFT_FAMILIES) - 1,
    )
    family_ppm_scales = target_values.new_tensor(ATOM_FAMILY_PPM_SCALES).clamp_min(
        1.0e-3
    )
    proxy_scales = family_ppm_scales[proxy_families].reshape(1, -1)
    proxy_error = (proxy_mu.detach() - proxy_targets) / proxy_scales
    configured_family_weights = {
        _normalized_atom_family_key(name): max(float(value), 0.0)
        for name, value in dict(
            config.bioemu_cs_reweighting_teacher_generated_prior_cosat_family_weights
        ).items()
    }
    row_weights = torch.ones(
        proxy_rows,
        device=target_values.device,
        dtype=target_values.dtype,
    )
    if configured_family_weights:
        row_weights = torch.zeros_like(row_weights)
        for family, family_weight in configured_family_weights.items():
            if family not in CHEMICAL_SHIFT_FAMILIES or family_weight <= 0.0:
                continue
            family_index = CHEMICAL_SHIFT_FAMILIES.index(family)
            row_weights = torch.where(
                proxy_families == int(family_index),
                row_weights.new_full(row_weights.shape, family_weight),
                row_weights,
            )
    if not bool(torch.any(row_weights > 0.0)):
        metrics[f"{prefix}_online_proxy_teacher_inactive_zero_family_weights"] = 1.0
        return None, metrics

    proxy_scale = max(
        float(config.bioemu_cs_reweighting_teacher_generated_prior_cosat_scale),
        0.0,
    )
    proxy_energy = (
        row_weights.reshape(1, -1) * proxy_scale * proxy_error.square()
    ).sum(dim=1) / row_weights.sum().clamp_min(1.0e-12)
    teacher = torch.softmax(-proxy_energy, dim=0)
    proxy_power = max(
        float(config.bioemu_cs_reweighting_teacher_generated_prior_cosat_power),
        1.0e-6,
    )
    if abs(proxy_power - 1.0) > 1.0e-6:
        teacher = teacher.pow(proxy_power)
        teacher = teacher / teacher.sum().clamp_min(1.0e-12)
    metrics.update(
        {
            f"{prefix}_online_proxy_teacher_used": 1.0,
            f"{prefix}_online_proxy_teacher_rows": float(proxy_rows),
            f"{prefix}_online_proxy_teacher_family_count": float(len(active_families)),
            f"{prefix}_online_proxy_teacher_used_required_families": (
                1.0 if required_ok else 0.0
            ),
            f"{prefix}_online_proxy_teacher_used_fallback_families": (
                1.0 if (not required_ok and fallback_ok) else 0.0
            ),
            f"{prefix}_online_proxy_teacher_ess": float(
                (1.0 / teacher.square().sum().clamp_min(1.0e-12)).detach().cpu()
            ),
            f"{prefix}_online_proxy_teacher_top_mass": float(
                torch.max(teacher).detach().cpu()
            ),
            f"{prefix}_online_proxy_teacher_sample_count": float(teacher.numel()),
            f"{prefix}_online_proxy_teacher_scale": float(proxy_scale),
        }
    )
    return teacher.detach(), metrics


def _bioemu_generated_prior_log_prob_tensor(
    *,
    outputs: dict[str, torch.Tensor],
    config: StudentTrainingConfig,
) -> tuple[torch.Tensor | None, str]:
    source = str(
        config.bioemu_cs_reweighting_teacher_generated_prior_log_prob_source or "raw"
    ).strip()
    source_key = source.lower()
    aliases_by_source = {
        "raw": ("sample_log_prob",),
        "sample_log_prob": ("sample_log_prob",),
        "prior_logit_adapter": (
            "prior_logit_adapter_sample_log_prob",
            "prior_logit_adapter_log_prob",
            "generated_prior_log_prob",
            "sample_log_prob",
        ),
        "adapter": (
            "prior_logit_adapter_sample_log_prob",
            "prior_logit_adapter_log_prob",
            "generated_prior_log_prob",
            "sample_log_prob",
        ),
        "generated_prior": ("generated_prior_log_prob", "sample_log_prob"),
    }
    aliases = aliases_by_source.get(source_key, (source, "sample_log_prob"))
    for key in aliases:
        value = outputs.get(key)
        if torch.is_tensor(value):
            safe_key = re.sub(r"[^0-9A-Za-z_]+", "_", str(key)).strip("_").lower()
            return value, safe_key or "unknown"
    safe_source = re.sub(r"[^0-9A-Za-z_]+", "_", source).strip("_").lower()
    return None, safe_source or "missing"


def _cs_reweighting_teacher_mean_loss_weight(config: StudentTrainingConfig) -> float:
    """Return generic CS-reweighting teacher mean weight with legacy fallback."""

    generic_weight = float(config.bioemu_cs_reweighting_teacher_mean_loss_weight)
    if generic_weight > 0.0:
        return generic_weight
    return float(config.bioemu_ucbshift_cnnls_teacher_mean_loss_weight)


def _cs_reweighting_teacher_prior_kl_weight(config: StudentTrainingConfig) -> float:
    """Return generated-prior KL weight with legacy UCBShift/CNNLS fallback."""

    generic_weight = float(config.bioemu_cs_reweighting_teacher_prior_kl_weight)
    if generic_weight > 0.0:
        return generic_weight
    return float(config.bioemu_ucbshift_cnnls_teacher_prior_kl_weight)


def _cs_reweighting_teacher_prior_kl_temperature(
    config: StudentTrainingConfig,
) -> float:
    """Return temperature used to compare BioEmu generated prior to teacher q."""

    return max(float(config.bioemu_cs_reweighting_teacher_prior_kl_temperature), 1.0e-4)


def _posterior_temperature(config: StudentTrainingConfig, epoch: int) -> float:
    target = max(float(config.bioemu_nmr_posterior_weight_temperature), 1e-4)
    warmup = max(int(config.bioemu_nmr_weight_temperature_warmup_epochs), 0)
    if warmup <= 0:
        return target
    start = max(target * 2.0, 1.0)
    blend = min(max(float(epoch - 1) / float(warmup), 0.0), 1.0)
    return (1.0 - blend) * start + blend * target


def _learning_rate_for_epoch(config: StudentTrainingConfig, epoch: int) -> float:
    base = float(config.learning_rate)
    minimum = min(max(float(config.min_learning_rate), 0.0), base)
    if config.warmup_epochs > 0 and epoch <= config.warmup_epochs:
        return base * float(epoch) / float(max(config.warmup_epochs, 1))
    if config.learning_rate_schedule == "cosine" and config.epochs > config.warmup_epochs:
        progress = (epoch - config.warmup_epochs) / max(
            config.epochs - config.warmup_epochs,
            1,
        )
        cosine = 0.5 * (1.0 + math.cos(math.pi * min(max(progress, 0.0), 1.0)))
        return minimum + (base - minimum) * cosine
    return base


def _empty_bioemu_epoch(split_name: str) -> dict[str, Any]:
    return {
        "loss_summary": {},
        "loss_rows": [],
        "metric_rows": [],
        "metric_summary": {},
        "eligible_counts": {},
        "split": split_name,
    }


def _bioemu_latent_support_sample_epoch(
    config: StudentTrainingConfig,
    *,
    epoch: int,
    training: bool,
) -> int:
    """Return the epoch component used for deterministic latent support draws."""

    if training and bool(getattr(config, "bioemu_x0_freeze_train_support_seed", False)):
        return int(getattr(config, "bioemu_x0_train_support_seed_epoch", epoch)) + int(
            getattr(config, "bioemu_x0_train_support_seed_offset", 0) or 0
        )
    if (not training) and bool(
        getattr(config, "bioemu_x0_freeze_eval_support_seed", False)
    ):
        return int(getattr(config, "bioemu_x0_eval_support_seed_epoch", epoch))
    return int(epoch)


def _checkpoint_score(summary: dict[str, Any], config: StudentTrainingConfig) -> float:
    metric_name = str(config.checkpoint_metric)
    if metric_name in summary and math.isfinite(float(summary[metric_name])):
        value = float(summary[metric_name])
        return -value if "loss" in metric_name or "nll" in metric_name else value
    for fallback in (
        "val_masked_HN_Cprime_ccc_macro",
        "val_masked_HN_ccc_macro",
        "val_masked_family_ccc_macro",
    ):
        if fallback in summary and math.isfinite(float(summary[fallback])):
            return float(summary[fallback])
    if "val_loss" in summary and math.isfinite(float(summary["val_loss"])):
        return -float(summary["val_loss"])
    return -float("inf")


def _atlas_names(config: StudentTrainingConfig) -> tuple[str, ...]:
    names = tuple(config.bioemu_latent_atlas_coordinate_names)
    atlas_dim = max(int(config.bioemu_latent_atlas_dim), 1)
    if len(names) >= atlas_dim:
        return names[:atlas_dim]
    return names + tuple(f"atlas_{index}" for index in range(len(names), atlas_dim))


def _resolve_device(device_name: str) -> torch.device:
    if str(device_name) == "auto":
        return torch.device("cuda" if torch.cuda.is_available() else "cpu")
    return torch.device(device_name)


def _maybe_load_initial_checkpoint(
    model: BioEmuLatentNmrAtlasModel,
    config: StudentTrainingConfig,
    provider: BioEmuLatentProvider | None = None,
) -> None:
    if not config.initial_checkpoint_path:
        return
    checkpoint_path = Path(config.initial_checkpoint_path)
    if not checkpoint_path.exists():
        raise FileNotFoundError(f"initial_checkpoint_path not found: {checkpoint_path}")
    payload = torch.load(checkpoint_path, map_location="cpu")
    state_dict = payload.get("model_state_dict", payload) if isinstance(payload, dict) else payload
    if not isinstance(state_dict, dict):
        raise ValueError(f"Unsupported checkpoint payload at {checkpoint_path}")
    if config.initial_checkpoint_exclude_prefixes:
        prefixes = tuple(config.initial_checkpoint_exclude_prefixes)
        state_dict = {
            key: value for key, value in state_dict.items() if not key.startswith(prefixes)
        }
    if not bool(config.initial_checkpoint_strict):
        checkpoint_config = payload.get("config", {}) if isinstance(payload, dict) else {}
        state_dict = _adapt_initial_checkpoint_state_dict(
            model,
            state_dict,
            checkpoint_config if isinstance(checkpoint_config, dict) else {},
        )
    model.load_state_dict(state_dict, strict=bool(config.initial_checkpoint_strict))
    if provider is not None and isinstance(payload, dict):
        _load_bioemu_provider_trainable_state_dict(
            provider,
            payload.get("provider_trainable_state_dict", {}),
        )


def _factor_bin_coordinate_names_from_config(
    payload: dict[str, Any],
) -> tuple[str, ...]:
    source = str(
        payload.get("bioemu_factor_bin_rare_adapter_coordinate_source", "physics")
    ).strip().lower()
    physics_names = tuple(
        str(name)
        for name in payload.get(
            "bioemu_physics_atlas_coordinate_names",
            DEFAULT_PHYSICS_ATLAS_COORDINATES,
        )
    )
    atlas_names = tuple(
        str(name)
        for name in payload.get("bioemu_latent_atlas_coordinate_names", DEFAULT_ATLAS_NAMES)
    )
    if source in {"latent", "atlas", "state", "hn_state"}:
        return atlas_names
    if source in {"hybrid", "both", "physics_latent", "latent_physics"}:
        return (*physics_names, *atlas_names)
    return physics_names


def _mechanism_signed_router_coordinate_names_from_config(
    payload: dict[str, Any],
) -> tuple[str, ...]:
    source = str(
        payload.get("bioemu_mechanism_signed_router_coordinate_source", "physics")
    ).strip().lower()
    physics_names = tuple(
        str(name)
        for name in payload.get(
            "bioemu_physics_atlas_coordinate_names",
            DEFAULT_PHYSICS_ATLAS_COORDINATES,
        )
    )
    atlas_names = tuple(
        str(name)
        for name in payload.get("bioemu_latent_atlas_coordinate_names", DEFAULT_ATLAS_NAMES)
    )
    if source in {"latent", "atlas", "state", "hn_state"}:
        return atlas_names
    if source in {"hybrid", "both", "physics_latent", "latent_physics"}:
        return (*physics_names, *atlas_names)
    return physics_names


def _adapt_initial_checkpoint_state_dict(
    model: BioEmuLatentNmrAtlasModel,
    state_dict: dict[str, Any],
    checkpoint_config: dict[str, Any],
) -> dict[str, Any]:
    """Drop mismatched tensors and preserve sparse-adapter rows by canonical key."""

    current_state = model.state_dict()
    adapted = dict(state_dict)
    old_specs = _physics_factor_bin_specs(
        tuple(str(key) for key in checkpoint_config.get("bioemu_factor_bin_rare_adapter_keys", [])),
        _factor_bin_coordinate_names_from_config(checkpoint_config),
    )
    old_index_by_key = {spec.canonical_key: index for index, spec in enumerate(old_specs)}
    new_specs = tuple(model.factor_bin_rare_adapter.key_specs)
    new_index_by_key = {spec.canonical_key: index for index, spec in enumerate(new_specs)}
    factor_row_parameters = {
        "factor_bin_rare_adapter.key_embedding.weight",
        "factor_bin_rare_adapter.key_delta_bias.weight",
        "factor_bin_rare_adapter.key_gate_bias.weight",
    }
    old_mechanism_specs = _physics_factor_bin_specs(
        tuple(
            str(key)
            for key in checkpoint_config.get(
                "bioemu_mechanism_signed_router_keys",
                [],
            )
        ),
        _mechanism_signed_router_coordinate_names_from_config(checkpoint_config),
    )
    old_mechanism_index_by_key = {
        spec.canonical_key: index for index, spec in enumerate(old_mechanism_specs)
    }
    new_mechanism_specs = tuple(model.mechanism_signed_router.key_specs)
    new_mechanism_index_by_key = {
        spec.canonical_key: index for index, spec in enumerate(new_mechanism_specs)
    }
    mechanism_row_parameters = {
        "mechanism_signed_router.key_embedding.weight",
        "mechanism_signed_router.key_magnitude_bias.weight",
        "mechanism_signed_router.key_gate_bias.weight",
    }
    old_mechanism_override_specs = _physics_factor_bin_specs(
        tuple(
            str(key)
            for key in checkpoint_config.get(
                "bioemu_mechanism_signed_override_keys",
                checkpoint_config.get("bioemu_mechanism_signed_router_keys", []),
            )
        ),
        _mechanism_signed_router_coordinate_names_from_config(checkpoint_config),
    )
    old_mechanism_override_index_by_key = {
        spec.canonical_key: index
        for index, spec in enumerate(old_mechanism_override_specs)
    }
    new_mechanism_override_specs = tuple(
        model.mechanism_signed_override_adapter.key_specs
    )
    new_mechanism_override_index_by_key = {
        spec.canonical_key: index
        for index, spec in enumerate(new_mechanism_override_specs)
    }
    mechanism_override_row_parameters = {
        "mechanism_signed_override_adapter.key_embedding.weight",
        "mechanism_signed_override_adapter.key_magnitude_bias.weight",
        "mechanism_signed_override_adapter.key_gate_bias.weight",
    }
    old_residue_pairs = _residue_family_pair_indices(
        tuple(
            str(key)
            for key in checkpoint_config.get(
                "bioemu_residue_family_rare_adapter_keys",
                [],
            )
        )
    )
    old_residue_index_by_pair = {
        pair: index for index, pair in enumerate(old_residue_pairs)
    }
    new_residue_pairs = tuple(model.residue_family_rare_adapter.enabled_pairs)
    new_residue_index_by_pair = {
        pair: index for index, pair in enumerate(new_residue_pairs)
    }
    residue_row_parameters = {
        "residue_family_rare_adapter.pair_embedding.weight",
        "residue_family_rare_adapter.pair_delta_bias.weight",
        "residue_family_rare_adapter.pair_gate_bias.weight",
    }
    config_driven_readout_buffers = {
        "residue_family_chart_bin_readout_adapter.key_centers",
        "residue_family_chart_bin_readout_adapter.key_widths",
        "residue_family_chart_bin_readout_adapter.key_deltas",
        "residue_family_chart_bin_readout_adapter.key_max_abs",
        "residue_family_chart_bin_readout_adapter.key_gate_scales",
        "residue_family_directional_readout_adapter.pair_deltas",
        "residue_family_directional_readout_adapter.pair_max_abs",
        "residue_family_directional_readout_adapter.pair_centers",
        "residue_family_directional_readout_adapter.pair_margins",
        "residue_family_directional_readout_adapter.pair_gate_scales",
        "residue_family_anchor_readout_adapter.pair_centers",
        "residue_family_anchor_readout_adapter.pair_max_abs",
        "residue_family_anchor_readout_adapter.pair_margins",
        "residue_family_anchor_readout_adapter.pair_gate_scales",
    }
    restored_factor_rows = 0
    restored_mechanism_rows = 0
    restored_mechanism_override_rows = 0
    restored_residue_rows = 0
    dropped_config_driven_readout_buffers = 0
    for name, tensor in list(adapted.items()):
        current = current_state.get(name)
        if current is None or not isinstance(tensor, torch.Tensor):
            continue
        if name in config_driven_readout_buffers:
            # These readouts are fixed config-driven probes, not learned
            # parameters. Keep the current config values when warm-starting so
            # zero-LR probe runs can safely retune local physics charts.
            adapted.pop(name)
            dropped_config_driven_readout_buffers += 1
            continue
        if name in factor_row_parameters and old_index_by_key and new_index_by_key:
            if (
                tuple(tensor.shape) == tuple(current.shape)
                and old_index_by_key == new_index_by_key
            ):
                continue
            expanded = current.detach().clone()
            for key, old_index in old_index_by_key.items():
                new_index = new_index_by_key.get(key)
                if new_index is None:
                    continue
                if old_index >= tensor.shape[0] or new_index >= expanded.shape[0]:
                    continue
                expanded[new_index].copy_(tensor[old_index].to(dtype=expanded.dtype))
                restored_factor_rows += 1
            adapted[name] = expanded
            continue
        if (
            name in mechanism_row_parameters
            and old_mechanism_index_by_key
            and new_mechanism_index_by_key
        ):
            if (
                tuple(tensor.shape) == tuple(current.shape)
                and old_mechanism_index_by_key == new_mechanism_index_by_key
            ):
                continue
            expanded = current.detach().clone()
            for key, old_index in old_mechanism_index_by_key.items():
                new_index = new_mechanism_index_by_key.get(key)
                if new_index is None:
                    continue
                if old_index >= tensor.shape[0] or new_index >= expanded.shape[0]:
                    continue
                expanded[new_index].copy_(tensor[old_index].to(dtype=expanded.dtype))
                restored_mechanism_rows += 1
            adapted[name] = expanded
            continue
        if (
            name in mechanism_override_row_parameters
            and old_mechanism_override_index_by_key
            and new_mechanism_override_index_by_key
        ):
            if (
                tuple(tensor.shape) == tuple(current.shape)
                and old_mechanism_override_index_by_key
                == new_mechanism_override_index_by_key
            ):
                continue
            expanded = current.detach().clone()
            for key, old_index in old_mechanism_override_index_by_key.items():
                new_index = new_mechanism_override_index_by_key.get(key)
                if new_index is None:
                    continue
                if old_index >= tensor.shape[0] or new_index >= expanded.shape[0]:
                    continue
                expanded[new_index].copy_(tensor[old_index].to(dtype=expanded.dtype))
                restored_mechanism_override_rows += 1
            adapted[name] = expanded
            continue
        if (
            name in residue_row_parameters
            and old_residue_index_by_pair
            and new_residue_index_by_pair
        ):
            if (
                tuple(tensor.shape) == tuple(current.shape)
                and old_residue_index_by_pair == new_residue_index_by_pair
            ):
                continue
            expanded = current.detach().clone()
            for pair, old_index in old_residue_index_by_pair.items():
                new_index = new_residue_index_by_pair.get(pair)
                if new_index is None:
                    continue
                if old_index >= tensor.shape[0] or new_index >= expanded.shape[0]:
                    continue
                expanded[new_index].copy_(tensor[old_index].to(dtype=expanded.dtype))
                restored_residue_rows += 1
            adapted[name] = expanded
            continue
        if tuple(tensor.shape) == tuple(current.shape):
            continue
        adapted.pop(name)
    if restored_factor_rows:
        print(
            "[bioemu-latent-nmr] adapted initial factor-bin checkpoint rows "
            f"restored={restored_factor_rows}",
            flush=True,
        )
    if restored_mechanism_rows:
        print(
            "[bioemu-latent-nmr] adapted initial mechanism-signed router rows "
            f"restored={restored_mechanism_rows}",
            flush=True,
        )
    if restored_mechanism_override_rows:
        print(
            "[bioemu-latent-nmr] adapted initial mechanism-signed override rows "
            f"restored={restored_mechanism_override_rows}",
            flush=True,
        )
    if restored_residue_rows:
        print(
            "[bioemu-latent-nmr] adapted initial residue-family checkpoint rows "
            f"restored={restored_residue_rows}",
            flush=True,
        )
    if dropped_config_driven_readout_buffers:
        print(
            "[bioemu-latent-nmr] kept current config-driven readout buffers "
            f"dropped_from_checkpoint={dropped_config_driven_readout_buffers}",
            flush=True,
        )
    return adapted


def _maybe_open_neighborhood_adapter_parameters(
    model: BioEmuLatentNmrAtlasModel,
    config: StudentTrainingConfig,
) -> None:
    """Keep compact neighborhood message passing trainable in adapter-only runs."""

    if not (
        bool(config.enable_bioemu_neighborhood_aware_nmr)
        and bool(config.bioemu_neighborhood_train_with_local_adapters)
    ):
        return
    for parameter in model.neighborhood_encoder.parameters():
        parameter.requires_grad_(True)
    if float(config.bioemu_x2d_pair_latent_weight) > 0.0:
        for parameter in model.pair_residue_projection.parameters():
            parameter.requires_grad_(True)


def _maybe_open_bridge_cs_energy_parameters(
    model: BioEmuLatentNmrAtlasModel,
    config: StudentTrainingConfig,
) -> bool:
    """Open trainable CS-energy posterior parameters in adapter-only runs."""

    if not bool(config.bioemu_bridge_audit_signal_cs_energy_enabled):
        return False
    opened = False
    if bool(config.bioemu_bridge_audit_signal_cs_energy_learned_scale_enabled):
        model.bridge_cs_energy_learned_raw_scale.requires_grad_(True)
        opened = True
    if bool(config.bioemu_bridge_audit_signal_cs_energy_sample_head_enabled):
        for parameter in model.bridge_cs_energy_sample_head.parameters():
            parameter.requires_grad_(True)
        for parameter in model.bridge_cs_energy_sample_matrix_head.parameters():
            parameter.requires_grad_(True)
        opened = True
    return opened


def _maybe_open_bridge_cs_measure_distill_parameters(
    model: BioEmuLatentNmrAtlasModel,
    config: StudentTrainingConfig,
) -> bool:
    """Open the minimal readout path needed for q-weighted CS measure distill."""

    if float(config.bioemu_bridge_audit_signal_cs_measure_distill_loss_weight) <= 0.0:
        return False
    if not bool(config.bioemu_bridge_audit_signal_cs_measure_distill_trainable):
        return False
    for parameter in model.moment_head.parameters():
        parameter.requires_grad_(True)
    for parameter in model.moment_corrector.parameters():
        parameter.requires_grad_(True)
    return True


def _maybe_open_hierarchical_bayes_readout_parameters(
    model: BioEmuLatentNmrAtlasModel,
    config: StudentTrainingConfig,
) -> bool:
    """Open local residue-family shrinkage when physics-atlas readout is active."""

    if not (
        bool(config.enable_bioemu_physics_atlas_v36)
        and bool(config.bayesian_shrinkage_enabled)
    ):
        return False
    for parameter in model.hierarchical_bayes_readout.parameters():
        parameter.requires_grad_(True)
    return True


def _maybe_freeze_residue_family_rare_adapter_only(
    model: BioEmuLatentNmrAtlasModel,
    config: StudentTrainingConfig,
) -> None:
    if not bool(config.bioemu_train_only_residue_family_rare_adapter):
        return
    for parameter in model.parameters():
        parameter.requires_grad_(False)
    train_keys = tuple(str(key) for key in config.bioemu_residue_family_rare_adapter_train_keys)
    trainable_pair_indices = model.residue_family_rare_adapter.trainable_pair_indices(train_keys)
    if train_keys:
        for module in (
            model.residue_family_rare_adapter.pair_embedding,
            model.residue_family_rare_adapter.pair_delta_bias,
            model.residue_family_rare_adapter.pair_gate_bias,
        ):
            for parameter in module.parameters():
                parameter.requires_grad_(True)
        if bool(config.bioemu_residue_family_rare_adapter_train_shared_heads):
            for parameter in model.residue_family_rare_adapter.delta_head.parameters():
                parameter.requires_grad_(True)
            for parameter in model.residue_family_rare_adapter.gate_head.parameters():
                parameter.requires_grad_(True)
        model.residue_family_rare_adapter.apply_pair_gradient_mask(trainable_pair_indices)
        model.residue_family_rare_adapter.lock_non_trainable_pair_rows(
            trainable_pair_indices
        )
    else:
        for parameter in model.residue_family_rare_adapter.parameters():
            parameter.requires_grad_(True)
    _maybe_open_neighborhood_adapter_parameters(model, config)
    bridge_cs_opened = _maybe_open_bridge_cs_energy_parameters(model, config)
    bridge_measure_opened = _maybe_open_bridge_cs_measure_distill_parameters(
        model,
        config,
    )
    hierarchical_bayes_opened = _maybe_open_hierarchical_bayes_readout_parameters(
        model,
        config,
    )
    trainable = sum(
        int(parameter.numel()) for parameter in model.parameters() if parameter.requires_grad
    )
    total = sum(int(parameter.numel()) for parameter in model.parameters())
    print(
        "[bioemu-latent-nmr] train_only_residue_family_rare_adapter "
        f"trainable_parameters={trainable}/{total} "
        f"train_keys={len(train_keys)} trainable_pairs={len(trainable_pair_indices)} "
        f"train_shared_heads={bool(config.bioemu_residue_family_rare_adapter_train_shared_heads)}",
        f"bridge_cs_energy_opened={bridge_cs_opened}",
        f"bridge_cs_measure_distill_opened={bridge_measure_opened}",
        f"hierarchical_bayes_opened={hierarchical_bayes_opened}",
        flush=True,
    )


