def _maybe_freeze_selected_bioemu_adapter_union(
    model: BioEmuLatentNmrAtlasModel,
    config: StudentTrainingConfig,
) -> None:
    """Allow multiple train-only adapter flags to form one trainable union.

    The single-adapter helpers above intentionally freeze all parameters before
    opening one adapter.  When we want to preserve a C' signed override while
    also testing residue-family outlier adapters for N/CA/CB, that sequential
    behavior would let the last helper win.  This union pass runs only when two
    or more train-only flags are active, then re-opens exactly the requested
    adapter rows/heads.
    """

    active = [
        bool(config.bioemu_train_only_residue_family_rare_adapter),
        bool(config.bioemu_train_only_factor_bin_rare_adapter),
        bool(config.bioemu_train_only_mechanism_signed_router),
        bool(config.bioemu_train_only_mechanism_signed_override_adapter),
        bool(config.bioemu_train_only_family_split_capacity_readout),
    ]
    if sum(1 for flag in active if flag) <= 1:
        return

    for parameter in model.parameters():
        parameter.requires_grad_(False)

    details: list[str] = []

    if bool(config.bioemu_train_only_residue_family_rare_adapter):
        train_keys = tuple(
            str(key) for key in config.bioemu_residue_family_rare_adapter_train_keys
        )
        trainable_pair_indices = (
            model.residue_family_rare_adapter.trainable_pair_indices(train_keys)
        )
        if train_keys:
            for module in (
                model.residue_family_rare_adapter.pair_embedding,
                model.residue_family_rare_adapter.pair_delta_bias,
                model.residue_family_rare_adapter.pair_gate_bias,
            ):
                for parameter in module.parameters():
                    parameter.requires_grad_(True)
            if bool(config.bioemu_residue_family_rare_adapter_train_shared_heads):
                for parameter in model.residue_family_rare_adapter.delta_head.parameters():
                    parameter.requires_grad_(True)
                for parameter in model.residue_family_rare_adapter.gate_head.parameters():
                    parameter.requires_grad_(True)
            model.residue_family_rare_adapter.apply_pair_gradient_mask(
                trainable_pair_indices
            )
            model.residue_family_rare_adapter.lock_non_trainable_pair_rows(
                trainable_pair_indices
            )
        else:
            for parameter in model.residue_family_rare_adapter.parameters():
                parameter.requires_grad_(True)
        details.append(
            f"residue_family_rare={len(train_keys)}/"
            f"{len(trainable_pair_indices)}"
        )

    if bool(config.bioemu_train_only_factor_bin_rare_adapter):
        train_keys = tuple(str(key) for key in config.bioemu_factor_bin_rare_adapter_train_keys)
        trainable_key_indices = (
            model.factor_bin_rare_adapter.trainable_key_indices(train_keys)
        )
        if train_keys:
            for module in (
                model.factor_bin_rare_adapter.key_embedding,
                model.factor_bin_rare_adapter.key_delta_bias,
                model.factor_bin_rare_adapter.key_gate_bias,
            ):
                for parameter in module.parameters():
                    parameter.requires_grad_(True)
            if bool(config.bioemu_factor_bin_rare_adapter_train_shared_heads):
                for parameter in model.factor_bin_rare_adapter.delta_head.parameters():
                    parameter.requires_grad_(True)
                for parameter in model.factor_bin_rare_adapter.gate_head.parameters():
                    parameter.requires_grad_(True)
            model.factor_bin_rare_adapter.apply_key_gradient_mask(
                trainable_key_indices
            )
            model.factor_bin_rare_adapter.lock_non_trainable_key_rows(
                trainable_key_indices
            )
        else:
            for parameter in model.factor_bin_rare_adapter.parameters():
                parameter.requires_grad_(True)
        details.append(
            f"factor_bin_rare={len(train_keys)}/{len(trainable_key_indices)}"
        )

    if bool(config.bioemu_train_only_mechanism_signed_router):
        train_keys = tuple(str(key) for key in config.bioemu_mechanism_signed_router_train_keys)
        trainable_key_indices = (
            model.mechanism_signed_router.trainable_key_indices(train_keys)
        )
        if train_keys:
            for module in (
                model.mechanism_signed_router.key_embedding,
                model.mechanism_signed_router.key_magnitude_bias,
                model.mechanism_signed_router.key_gate_bias,
            ):
                for parameter in module.parameters():
                    parameter.requires_grad_(True)
            if bool(config.bioemu_mechanism_signed_router_train_shared_heads):
                for parameter in model.mechanism_signed_router.magnitude_head.parameters():
                    parameter.requires_grad_(True)
                for parameter in model.mechanism_signed_router.gate_head.parameters():
                    parameter.requires_grad_(True)
            model.mechanism_signed_router.apply_key_gradient_mask(
                trainable_key_indices
            )
            model.mechanism_signed_router.lock_non_trainable_key_rows(
                trainable_key_indices,
                preserve_locked_key_outputs=bool(
                    config.bioemu_mechanism_signed_router_preserve_locked_key_outputs
                ),
            )
        else:
            for parameter in model.mechanism_signed_router.parameters():
                parameter.requires_grad_(True)
        details.append(
            f"mechanism_signed_router={len(train_keys)}/{len(trainable_key_indices)}"
        )

    if bool(config.bioemu_train_only_mechanism_signed_override_adapter):
        train_keys = tuple(
            str(key) for key in config.bioemu_mechanism_signed_override_train_keys
        )
        trainable_key_indices = (
            model.mechanism_signed_override_adapter.trainable_key_indices(train_keys)
        )
        if train_keys:
            for module in (
                model.mechanism_signed_override_adapter.key_embedding,
                model.mechanism_signed_override_adapter.key_magnitude_bias,
                model.mechanism_signed_override_adapter.key_gate_bias,
            ):
                for parameter in module.parameters():
                    parameter.requires_grad_(True)
            if bool(config.bioemu_mechanism_signed_override_train_shared_heads):
                for parameter in (
                    model.mechanism_signed_override_adapter.magnitude_head.parameters()
                ):
                    parameter.requires_grad_(True)
                for parameter in model.mechanism_signed_override_adapter.gate_head.parameters():
                    parameter.requires_grad_(True)
            model.mechanism_signed_override_adapter.apply_key_gradient_mask(
                trainable_key_indices
            )
            model.mechanism_signed_override_adapter.lock_non_trainable_key_rows(
                trainable_key_indices,
                preserve_locked_key_outputs=bool(
                    config.bioemu_mechanism_signed_override_preserve_locked_key_outputs
                ),
            )
        else:
            for parameter in model.mechanism_signed_override_adapter.parameters():
                parameter.requires_grad_(True)
        details.append(
            "mechanism_signed_override="
            f"{len(train_keys)}/{len(trainable_key_indices)}"
        )

    if bool(config.bioemu_train_only_family_split_capacity_readout):
        for parameter in model.family_split_capacity_readout.parameters():
            parameter.requires_grad_(True)
        details.append("family_split_capacity=enabled")

    _maybe_open_neighborhood_adapter_parameters(model, config)
    if (
        bool(config.enable_bioemu_neighborhood_aware_nmr)
        and bool(config.bioemu_neighborhood_train_with_local_adapters)
    ):
        details.append("neighborhood_message=enabled")
    if _maybe_open_bridge_cs_energy_parameters(model, config):
        details.append("bridge_cs_energy=enabled")
    if _maybe_open_bridge_cs_measure_distill_parameters(model, config):
        details.append("bridge_cs_measure_distill=enabled")
    if _maybe_open_hierarchical_bayes_readout_parameters(model, config):
        details.append("hierarchical_bayes=enabled")

    trainable = sum(
        int(parameter.numel()) for parameter in model.parameters() if parameter.requires_grad
    )
    total = sum(int(parameter.numel()) for parameter in model.parameters())
    print(
        "[bioemu-latent-nmr] train_only_adapter_union "
        f"trainable_parameters={trainable}/{total} "
        f"modules={';'.join(details)}",
        flush=True,
    )


def _maybe_freeze_family_split_capacity_readout_only(
    model: BioEmuLatentNmrAtlasModel,
    config: StudentTrainingConfig,
) -> None:
    """Diagnostic mode: train only the family-split high-capacity readout."""

    if not bool(config.bioemu_train_only_family_split_capacity_readout):
        return
    for parameter in model.parameters():
        parameter.requires_grad_(False)
    for parameter in model.family_split_capacity_readout.parameters():
        parameter.requires_grad_(True)
    _maybe_open_neighborhood_adapter_parameters(model, config)
    bridge_cs_opened = _maybe_open_bridge_cs_energy_parameters(model, config)
    bridge_measure_opened = _maybe_open_bridge_cs_measure_distill_parameters(
        model,
        config,
    )
    hierarchical_bayes_opened = _maybe_open_hierarchical_bayes_readout_parameters(
        model,
        config,
    )
    trainable = sum(
        int(parameter.numel()) for parameter in model.parameters() if parameter.requires_grad
    )
    total = sum(int(parameter.numel()) for parameter in model.parameters())
    print(
        "[bioemu-latent-nmr] train_only_family_split_capacity_readout "
        f"trainable_parameters={trainable}/{total} "
        "neighborhood_local_adapters_opened="
        f"{bool(config.enable_bioemu_neighborhood_aware_nmr and config.bioemu_neighborhood_train_with_local_adapters)} "
        f"bridge_cs_energy_opened={bridge_cs_opened} "
        f"bridge_cs_measure_distill_opened={bridge_measure_opened} "
        f"hierarchical_bayes_opened={hierarchical_bayes_opened}",
        flush=True,
    )


def _maybe_freeze_bridge_cs_energy_head_only(
    model: BioEmuLatentNmrAtlasModel,
    config: StudentTrainingConfig,
) -> None:
    """Diagnostic mode: train only the CS-energy posterior occupancy head."""

    if not bool(config.bioemu_train_only_bridge_cs_energy_head):
        return
    for parameter in model.parameters():
        parameter.requires_grad_(False)
    opened = _maybe_open_bridge_cs_energy_parameters(model, config)
    measure_opened = _maybe_open_bridge_cs_measure_distill_parameters(model, config)
    hierarchical_bayes_opened = _maybe_open_hierarchical_bayes_readout_parameters(
        model,
        config,
    )
    trainable = sum(
        int(parameter.numel()) for parameter in model.parameters() if parameter.requires_grad
    )
    total = sum(int(parameter.numel()) for parameter in model.parameters())
    print(
        "[bioemu-latent-nmr] train_only_bridge_cs_energy_head "
        f"trainable_parameters={trainable}/{total} opened={opened} "
        f"measure_distill_opened={measure_opened} "
        f"hierarchical_bayes_opened={hierarchical_bayes_opened}",
        flush=True,
    )


def _bioemu_latent_optimizer_param_groups(
    model: nn.Module,
    *,
    support_basis_lr_multiplier: float = 1.0,
    mechanism_decoder_lr_multiplier: float = 1.0,
    capacity_adapter_lr_multiplier: float = 1.0,
    capacity_adapter_extra_lr_multiplier: float = 1.0,
    family_affine_lr_multiplier: float = 1.0,
    posterior_energy_lr_multiplier: float = 1.0,
    posterior_mode_lr_multiplier: float = 1.0,
    evidence_head_lr_multiplier: float = 1.0,
    posterior_energy_extra_lr_multiplier: float = 1.0,
    sample_support_delta_lr_multiplier: float = -1.0,
) -> list[dict[str, Any]]:
    """Create LR-multiplied optimizer groups for BioEmu latent NMR training.

    The x0 configs already carry cautious LR multipliers for decoder, support,
    posterior-energy, mode, and evidence heads.  This runner used to flatten all
    trainable parameters into one AdamW group, so those knobs had no effect for
    BioEmu latent atlas runs.  Defaults remain exactly equivalent to the old
    behavior because every multiplier defaults to 1.0.
    """

    support_multiplier = max(float(support_basis_lr_multiplier), 0.0)
    mechanism_multiplier = max(float(mechanism_decoder_lr_multiplier), 0.0)
    adapter_multiplier = max(float(capacity_adapter_lr_multiplier), 0.0)
    extra_adapter_multiplier = max(float(capacity_adapter_extra_lr_multiplier), 0.0)
    family_affine_multiplier = max(float(family_affine_lr_multiplier), 0.0)
    energy_multiplier = max(float(posterior_energy_lr_multiplier), 0.0)
    posterior_mode_multiplier = max(float(posterior_mode_lr_multiplier), 0.0)
    evidence_head_multiplier = max(float(evidence_head_lr_multiplier), 0.0)
    energy_extra_multiplier = max(float(posterior_energy_extra_lr_multiplier), 0.0)
    sample_support_delta_multiplier = (
        support_multiplier
        if float(sample_support_delta_lr_multiplier) < 0.0
        else max(float(sample_support_delta_lr_multiplier), 0.0)
    )

    sample_support_delta_prefixes = ("sample_support_delta_head.",)
    support_prefixes = (
        "decoder.hn_cprime_support_basis_mean_delta.",
        "decoder.hn_cprime_support_basis_gate.",
        "decoder.hn_signed_support_basis_mean_delta.",
        "decoder.hn_signed_support_basis_gate.",
        "decoder.cprime_isolated_support_basis_mean_delta.",
        "decoder.cprime_isolated_support_basis_gate.",
        "residue_family_rare_adapter.",
        "factor_bin_rare_adapter.",
        "chart_bin_residual_readout_adapter.",
        "residue_family_chart_bin_readout_adapter.",
        "residue_family_directional_readout_adapter.",
        "residue_family_anchor_readout_adapter.",
    )
    mechanism_prefixes = (
        "decoder.mechanism_projection.",
        "decoder.family_mechanism_mean_delta.",
        "decoder.hn_cprime_specialized_mean_delta.",
        "decoder.hn_selected_edge_mean_delta.",
        "decoder.hn_support_deviation_mean_delta.",
        "decoder.cprime_selected_edge_mean_delta.",
        "decoder.cprime_support_deviation_mean_delta.",
        "decoder.cprime_plane_support_refinement_mean_delta.",
        "decoder.n_ca_cb_support_deviation_mean_delta.",
        "atlas_head.",
        "physics_atlas_head.",
        "tangent_adapter.",
        "cprime_chart_bias_adapter.",
        "family_tangent_adapter_bank.",
        "family_chart_bias_adapter.",
        "hierarchical_bayes_readout.",
        "mechanism_signed_router.",
        "mechanism_signed_override_adapter.",
        "pair_residue_projection.",
        "neighborhood_encoder.",
    )
    adapter_prefixes = (
        "decoder.capacity_adapter_mean_delta.",
        "family_split_capacity_readout.",
    )
    extra_adapter_prefixes = ("decoder.capacity_adapter_extra_mean_delta.",)
    energy_prefixes = (
        "energy_head.energy_head.",
        "sample_norm_head.",
        "sample_log_sigma_head.",
        "sample_weight_head.",
    )
    posterior_mode_prefixes = (
        "moment_corrector.",
        "moment_head.",
    )
    evidence_head_prefixes = ("evidence_context.",)
    energy_extra_prefixes = (
        "energy_head.energy_extra_head.",
        "energy_head.energy_support_attention_head.",
        "bridge_cs_energy_sample_head.",
        "bridge_cs_energy_sample_matrix_head.",
    )
    energy_extra_names = {"bridge_cs_energy_learned_raw_scale"}
    family_affine_names = {
        "decoder.family_affine_scale_delta",
        "decoder.family_affine_shift_delta",
    }

    support_params: list[nn.Parameter] = []
    mechanism_params: list[nn.Parameter] = []
    adapter_params: list[nn.Parameter] = []
    extra_adapter_params: list[nn.Parameter] = []
    family_affine_params: list[nn.Parameter] = []
    energy_params: list[nn.Parameter] = []
    posterior_mode_params: list[nn.Parameter] = []
    evidence_head_params: list[nn.Parameter] = []
    energy_extra_params: list[nn.Parameter] = []
    sample_support_delta_params: list[nn.Parameter] = []
    default_params: list[nn.Parameter] = []

    for name, parameter in model.named_parameters():
        if not parameter.requires_grad:
            continue
        if any(name.startswith(prefix) for prefix in energy_extra_prefixes) or (
            name in energy_extra_names
        ):
            energy_extra_params.append(parameter)
        elif any(name.startswith(prefix) for prefix in energy_prefixes):
            energy_params.append(parameter)
        elif any(name.startswith(prefix) for prefix in posterior_mode_prefixes):
            posterior_mode_params.append(parameter)
        elif any(name.startswith(prefix) for prefix in evidence_head_prefixes):
            evidence_head_params.append(parameter)
        elif any(name.startswith(prefix) for prefix in sample_support_delta_prefixes):
            sample_support_delta_params.append(parameter)
        elif any(name.startswith(prefix) for prefix in extra_adapter_prefixes):
            extra_adapter_params.append(parameter)
        elif any(name.startswith(prefix) for prefix in adapter_prefixes) or (
            name == "decoder.capacity_adapter_scale_delta"
        ):
            adapter_params.append(parameter)
        elif name in family_affine_names:
            family_affine_params.append(parameter)
        elif any(name.startswith(prefix) for prefix in support_prefixes):
            support_params.append(parameter)
        elif any(name.startswith(prefix) for prefix in mechanism_prefixes):
            mechanism_params.append(parameter)
        else:
            default_params.append(parameter)

    groups: list[dict[str, Any]] = []
    _append_optimizer_group(groups, default_params, 1.0, "default")
    _append_optimizer_group(
        groups,
        support_params,
        support_multiplier,
        "support_basis",
    )
    _append_optimizer_group(
        groups,
        mechanism_params,
        mechanism_multiplier,
        "mechanism_decoder",
    )
    _append_optimizer_group(groups, adapter_params, adapter_multiplier, "capacity_adapter")
    _append_optimizer_group(
        groups,
        extra_adapter_params,
        extra_adapter_multiplier,
        "capacity_adapter_extra",
    )
    _append_optimizer_group(
        groups,
        family_affine_params,
        family_affine_multiplier,
        "family_affine",
    )
    _append_optimizer_group(groups, energy_params, energy_multiplier, "posterior_energy")
    _append_optimizer_group(
        groups,
        posterior_mode_params,
        posterior_mode_multiplier,
        "posterior_mode",
    )
    _append_optimizer_group(
        groups,
        evidence_head_params,
        evidence_head_multiplier,
        "evidence_head",
    )
    _append_optimizer_group(
        groups,
        energy_extra_params,
        energy_extra_multiplier,
        "posterior_energy_extra",
    )
    _append_optimizer_group(
        groups,
        sample_support_delta_params,
        sample_support_delta_multiplier,
        "sample_support_delta",
    )
    return groups


def _append_optimizer_group(
    groups: list[dict[str, Any]],
    params: list[nn.Parameter],
    lr_multiplier: float,
    group_name: str,
) -> None:
    if params:
        groups.append(
            {
                "params": params,
                "lr_multiplier": max(float(lr_multiplier), 0.0),
                "group_name": str(group_name),
            }
        )


def _bioemu_provider_optimizer_param_groups(
    provider: BioEmuLatentProvider,
    *,
    lr_multiplier: float = 1.0,
) -> list[dict[str, Any]]:
    """Expose trainable BioEmu provider parameters to the online optimizer.

    Most current providers deliberately return detached latents or frozen
    official BioEmu features.  This helper is therefore a no-op for legacy
    runs, but it is the contract point that lets future runtime score adapters
    or unfreezed BioEmu modules participate in end-to-end generation training.
    """

    loaded_model = getattr(provider, "_model", None)
    if not isinstance(loaded_model, nn.Module):
        return []
    params = [
        parameter for parameter in loaded_model.parameters() if parameter.requires_grad
    ]
    groups: list[dict[str, Any]] = []
    _append_optimizer_group(groups, params, lr_multiplier, "bioemu_provider")
    return groups


def _optimizer_group_parameter_count(group: dict[str, Any]) -> int:
    params = group.get("params")
    if not isinstance(params, list):
        return 0
    return sum(int(parameter.numel()) for parameter in params)


def _bioemu_latent_optimizer_contract_summary(
    optimizer_groups: list[dict[str, Any]],
    *,
    config: StudentTrainingConfig,
) -> dict[str, Any]:
    group_summaries: list[dict[str, Any]] = []
    parameter_count_by_group: dict[str, int] = {}
    lr_multiplier_by_group: dict[str, float] = {}
    for index, group in enumerate(optimizer_groups):
        name = str(group.get("group_name") or f"group_{index}")
        parameter_count = _optimizer_group_parameter_count(group)
        lr_multiplier = float(group.get("lr_multiplier", 1.0))
        group_summaries.append(
            {
                "index": int(index),
                "group_name": name,
                "parameter_count": int(parameter_count),
                "lr_multiplier": lr_multiplier,
            }
        )
        parameter_count_by_group[name] = (
            parameter_count_by_group.get(name, 0) + int(parameter_count)
        )
        lr_multiplier_by_group[name] = lr_multiplier

    failures: list[str] = []
    geometry_contract = bool(
        getattr(config, "bioemu_x0_shared_q_geometry_architecture_contract", False)
    )
    latent_bridge_required = bool(
        getattr(config, "bioemu_official_x1d_adapter_latent_bridge_trainable", False)
    )
    x2d_adapter_train_through = bool(
        getattr(config, "bioemu_official_x2d_adapter_enabled", False)
        and getattr(config, "bioemu_official_x2d_adapter_train_through_structure", False)
    )
    x2d_pair_latent_weight = float(
        getattr(config, "bioemu_x2d_pair_latent_weight", 0.0) or 0.0
    )
    x2d_effective_pair_capture = bool(
        getattr(config, "bioemu_capture_x2d_pair_latent", False)
        or (x2d_adapter_train_through and x2d_pair_latent_weight > 0.0)
    )
    if geometry_contract:
        if parameter_count_by_group.get("support_basis", 0) <= 0:
            failures.append("qbridge_support_basis_optimizer_group_empty")
        if parameter_count_by_group.get("mechanism_decoder", 0) <= 0:
            failures.append("qbridge_mechanism_decoder_optimizer_group_empty")
        if lr_multiplier_by_group.get("support_basis", 0.0) <= 1.0:
            failures.append("qbridge_support_basis_lr_not_boosted")
        if lr_multiplier_by_group.get("mechanism_decoder", 0.0) <= 1.0:
            failures.append("qbridge_mechanism_decoder_lr_not_boosted")
    if x2d_adapter_train_through:
        if parameter_count_by_group.get("bioemu_provider", 0) <= 0:
            failures.append("x2d_adapter_provider_optimizer_group_empty")
        if float(getattr(config, "bioemu_official_x2d_adapter_scale", 0.0) or 0.0) <= 0.0:
            failures.append("x2d_adapter_scale_not_positive")
        if float(getattr(config, "bioemu_official_x2d_adapter_max_abs", 0.0) or 0.0) <= 0.0:
            failures.append("x2d_adapter_max_abs_not_positive")
        if x2d_pair_latent_weight <= 0.0:
            failures.append("x2d_adapter_pair_latent_weight_not_positive")
        if not x2d_effective_pair_capture:
            failures.append("x2d_adapter_pair_latent_capture_disabled")
    if latent_bridge_required and parameter_count_by_group.get("bioemu_provider", 0) <= 0:
        failures.append("latent_bridge_provider_optimizer_group_empty")

    trainable_parameters = sum(parameter_count_by_group.values())
    return {
        "summary_kind": "bioemu_latent_optimizer_contract_v1",
        "status": "fail" if failures else "pass",
        "failures": failures,
        "group_count": int(len(group_summaries)),
        "trainable_parameters": int(trainable_parameters),
        "support_basis_parameters": int(parameter_count_by_group.get("support_basis", 0)),
        "mechanism_decoder_parameters": int(
            parameter_count_by_group.get("mechanism_decoder", 0)
        ),
        "bioemu_provider_parameters": int(
            parameter_count_by_group.get("bioemu_provider", 0)
        ),
        "geometry_architecture_contract": geometry_contract,
        "latent_bridge_provider_required": latent_bridge_required,
        "x2d_adapter_train_through_structure": x2d_adapter_train_through,
        "x2d_effective_pair_capture": x2d_effective_pair_capture,
        "x2d_pair_latent_weight": x2d_pair_latent_weight,
        "parameter_count_by_group": parameter_count_by_group,
        "lr_multiplier_by_group": lr_multiplier_by_group,
        "groups": group_summaries,
    }


def _enforce_bioemu_latent_optimizer_contract(summary: dict[str, Any]) -> None:
    if summary.get("status") == "pass":
        return
    failures = summary.get("failures")
    if isinstance(failures, list) and failures:
        failure_text = ",".join(str(item) for item in failures)
    else:
        failure_text = "unknown_optimizer_contract_failure"
    raise RuntimeError(f"BioEmu optimizer contract failed: {failure_text}")


def _bioemu_provider_trainable_state_dict(
    provider: BioEmuLatentProvider | None,
) -> dict[str, torch.Tensor]:
    """Return only trainable provider parameters, never the frozen BioEmu base."""

    if provider is None:
        return {}
    loaded_model = getattr(provider, "_model", None)
    if not isinstance(loaded_model, nn.Module):
        return {}
    trainable_names = {
        str(name)
        for name, parameter in loaded_model.named_parameters()
        if parameter.requires_grad
    }
    if not trainable_names:
        return {}
    state = loaded_model.state_dict()
    return {
        str(name): tensor.detach().cpu().clone()
        for name, tensor in state.items()
        if str(name) in trainable_names and torch.is_tensor(tensor)
    }


def _load_matching_provider_trainable_state_into_module(
    module: nn.Module,
    state_dict: dict[str, torch.Tensor],
) -> dict[str, Any]:
    """Load provider tensors whose keys and shapes still match the module."""

    current_state = module.state_dict()
    compatible: dict[str, torch.Tensor] = {}
    skipped: dict[str, str] = {}
    for name, tensor in state_dict.items():
        current_tensor = current_state.get(name)
        if not torch.is_tensor(current_tensor):
            skipped[name] = "missing_key"
            continue
        if tuple(current_tensor.shape) != tuple(tensor.shape):
            skipped[name] = (
                f"shape_mismatch:{tuple(tensor.shape)}!={tuple(current_tensor.shape)}"
            )
            continue
        compatible[name] = tensor.to(
            device=current_tensor.device,
            dtype=current_tensor.dtype,
        )
    missing_keys = 0
    unexpected_keys = 0
    if compatible:
        incompatible = module.load_state_dict(compatible, strict=False)
        missing_keys = len(getattr(incompatible, "missing_keys", []) or [])
        unexpected_keys = len(getattr(incompatible, "unexpected_keys", []) or [])
    return {
        "loaded_tensors": int(len(compatible)),
        "skipped_tensors": int(len(skipped)),
        "skipped_state_keys": sorted(skipped),
        "skipped_state_reasons": skipped,
        "missing_keys": int(missing_keys),
        "unexpected_keys": int(unexpected_keys),
    }


def _load_bioemu_provider_trainable_state_dict(
    provider: BioEmuLatentProvider,
    state_dict: Any,
) -> None:
    """Load or defer provider trainable state from an AtypEmu checkpoint."""

    if not isinstance(state_dict, dict) or not state_dict:
        return
    normalized_state: dict[str, torch.Tensor] = {}
    for name, value in state_dict.items():
        if torch.is_tensor(value):
            normalized_state[str(name)] = value.detach().clone()
    if not normalized_state:
        return
    loaded_model = getattr(provider, "_model", None)
    if isinstance(loaded_model, nn.Module):
        load_summary = _load_matching_provider_trainable_state_into_module(
            loaded_model,
            normalized_state,
        )
        setattr(provider, "_last_provider_trainable_state_load_summary", load_summary)
        return
    setattr(provider, "_pending_trainable_state_dict", normalized_state)


def _prepare_bioemu_provider_for_optimizer(
    provider: BioEmuLatentProvider,
    device: torch.device,
) -> dict[str, Any]:
    """Materialize trainable provider modules before optimizer groups are built."""

    needs_prepare = bool(
        getattr(provider, "x1d_adapter_enabled", False)
        or getattr(provider, "x2d_adapter_enabled", False)
        or getattr(provider, "_pending_trainable_state_dict", None)
    )
    if not needs_prepare:
        summary = _bioemu_provider_trainability_summary(provider)
        summary["loaded_for_optimizer"] = False
        summary["prepare_reason"] = "provider_has_no_configured_trainable_runtime_module"
        return summary
    loader = getattr(provider, "_load_model", None)
    if not callable(loader):
        summary = _bioemu_provider_trainability_summary(provider)
        summary["loaded_for_optimizer"] = False
        summary["prepare_reason"] = "provider_has_no_load_model_hook"
        return summary
    loader(device)
    summary = _bioemu_provider_trainability_summary(provider)
    summary["loaded_for_optimizer"] = True
    summary["prepare_reason"] = "provider_runtime_module_loaded_before_optimizer"
    return summary


def _bioemu_provider_trainability_summary(
    provider: BioEmuLatentProvider,
    optimizer: torch.optim.Optimizer | None = None,
) -> dict[str, Any]:
    """Summarize whether the BioEmu generation provider is in the gradient path."""

    loaded_model = getattr(provider, "_model", None)
    total_parameters = 0
    trainable_parameters = 0
    trainable_parameter_tensors = 0
    optimizer_provider_parameters = 0
    if isinstance(loaded_model, nn.Module):
        provider_parameter_ids = set()
        for parameter in loaded_model.parameters():
            total_parameters += int(parameter.numel())
            provider_parameter_ids.add(id(parameter))
            if parameter.requires_grad:
                trainable_parameters += int(parameter.numel())
                trainable_parameter_tensors += 1
        if optimizer is not None and provider_parameter_ids:
            seen_optimizer_parameters: set[int] = set()
            for group in optimizer.param_groups:
                for parameter in group.get("params", []):
                    parameter_id = id(parameter)
                    if (
                        parameter_id in provider_parameter_ids
                        and parameter_id not in seen_optimizer_parameters
                    ):
                        optimizer_provider_parameters += int(parameter.numel())
                        seen_optimizer_parameters.add(parameter_id)
    provider_name = provider.__class__.__name__
    generation_trainable = bool(
        trainable_parameters > 0 and optimizer_provider_parameters > 0
    )
    trainable_state = _bioemu_provider_trainable_state_dict(provider)
    reason = "provider_parameters_are_not_trainable_or_not_in_optimizer"
    if not isinstance(loaded_model, nn.Module):
        reason = "provider_has_no_loaded_torch_module"
    elif trainable_parameters <= 0:
        reason = "provider_loaded_module_is_frozen"
    elif optimizer_provider_parameters <= 0:
        reason = "provider_trainable_parameters_are_not_in_optimizer"
    else:
        reason = "provider_trainable_parameters_are_in_optimizer"
    return {
        "provider_class": provider_name,
        "loaded_torch_module": bool(isinstance(loaded_model, nn.Module)),
        "provider_total_parameters": int(total_parameters),
        "provider_trainable_parameters": int(trainable_parameters),
        "provider_trainable_parameter_tensors": int(trainable_parameter_tensors),
        "provider_trainable_state_tensors": int(len(trainable_state)),
        "optimizer_provider_parameters": int(optimizer_provider_parameters),
        "provider_generation_trainable": generation_trainable,
        "end_to_end_generation_gradient_contract": (
            "active" if generation_trainable else "inactive"
        ),
        "trainability_reason": reason,
    }


def _gradient_stats_for_parameters(parameters: Iterable[nn.Parameter]) -> dict[str, Any]:
    gradient_parameter_tensors = 0
    gradient_parameters = 0
    gradient_square_sum = 0.0
    gradient_max_abs = 0.0
    for parameter in parameters:
        gradient = parameter.grad
        if gradient is None:
            continue
        gradient_tensor = gradient.detach()
        if gradient_tensor.numel() == 0:
            continue
        gradient_parameter_tensors += 1
        gradient_parameters += int(parameter.numel())
        gradient_float = gradient_tensor.float()
        gradient_square_sum += float(
            torch.sum(gradient_float * gradient_float).detach().cpu()
        )
        gradient_max_abs = max(
            gradient_max_abs,
            float(torch.max(torch.abs(gradient_float)).detach().cpu()),
        )
    return {
        "gradient_parameter_tensors": int(gradient_parameter_tensors),
        "gradient_parameters": int(gradient_parameters),
        "gradient_l2_norm": float(math.sqrt(max(gradient_square_sum, 0.0))),
        "gradient_max_abs": float(gradient_max_abs),
    }


def _bioemu_provider_gradient_summary(
    provider: BioEmuLatentProvider | None,
    optimizer: torch.optim.Optimizer | None = None,
) -> dict[str, Any]:
    """Summarize whether trainable BioEmu provider parameters received gradients."""

    loaded_model = getattr(provider, "_model", None) if provider is not None else None
    if not isinstance(loaded_model, nn.Module):
        return {
            "provider_gradient_contract": "inactive",
            "provider_gradient_reason": "provider_has_no_loaded_torch_module",
            "provider_gradient_parameter_tensors": 0,
            "provider_gradient_parameters": 0,
            "provider_gradient_l2_norm": 0.0,
            "provider_gradient_max_abs": 0.0,
            "optimizer_provider_gradient_parameter_tensors": 0,
            "optimizer_provider_gradient_parameters": 0,
            "optimizer_provider_gradient_l2_norm": 0.0,
            "optimizer_provider_gradient_max_abs": 0.0,
        }

    trainable_parameters = [
        parameter for parameter in loaded_model.parameters() if parameter.requires_grad
    ]
    provider_stats = _gradient_stats_for_parameters(trainable_parameters)

    optimizer_parameter_ids: set[int] = set()
    if optimizer is not None:
        for group in optimizer.param_groups:
            for parameter in group.get("params", []):
                optimizer_parameter_ids.add(id(parameter))
    optimizer_provider_parameters = [
        parameter
        for parameter in trainable_parameters
        if id(parameter) in optimizer_parameter_ids
    ]
    optimizer_stats = _gradient_stats_for_parameters(optimizer_provider_parameters)

    optimizer_gradient_norm = float(optimizer_stats["gradient_l2_norm"])
    if not trainable_parameters:
        contract = "inactive"
        reason = "provider_has_no_trainable_parameters"
    elif optimizer is None:
        contract = "inactive"
        reason = "optimizer_missing"
    elif not optimizer_provider_parameters:
        contract = "inactive"
        reason = "provider_trainable_parameters_are_not_in_optimizer"
    elif optimizer_gradient_norm <= 0.0:
        contract = "zero"
        reason = "optimizer_provider_gradients_are_zero_or_missing"
    else:
        contract = "active"
        reason = "optimizer_provider_gradients_are_nonzero"

    return {
        "provider_gradient_contract": contract,
        "provider_gradient_reason": reason,
        "provider_gradient_parameter_tensors": int(
            provider_stats["gradient_parameter_tensors"]
        ),
        "provider_gradient_parameters": int(provider_stats["gradient_parameters"]),
        "provider_gradient_l2_norm": float(provider_stats["gradient_l2_norm"]),
        "provider_gradient_max_abs": float(provider_stats["gradient_max_abs"]),
        "optimizer_provider_gradient_parameter_tensors": int(
            optimizer_stats["gradient_parameter_tensors"]
        ),
        "optimizer_provider_gradient_parameters": int(
            optimizer_stats["gradient_parameters"]
        ),
        "optimizer_provider_gradient_l2_norm": optimizer_gradient_norm,
        "optimizer_provider_gradient_max_abs": float(optimizer_stats["gradient_max_abs"]),
    }


def _save_json(path: str | Path, payload: Any) -> None:
    Path(path).write_text(json.dumps(payload, indent=2, sort_keys=True))


def _save_json_atomic(path: str | Path, payload: Any) -> None:
    output_path = Path(path)
    output_path.parent.mkdir(parents=True, exist_ok=True)
    tmp_path = output_path.with_name(f"{output_path.name}.tmp")
    tmp_path.write_text(json.dumps(payload, indent=2, sort_keys=True))
    tmp_path.replace(output_path)


def _runtime_stage_json_safe(value: Any) -> Any:
    if isinstance(value, Path):
        return str(value)
    if isinstance(value, Mapping):
        return {str(key): _runtime_stage_json_safe(item) for key, item in value.items()}
    if isinstance(value, (list, tuple)):
        return [_runtime_stage_json_safe(item) for item in value]
    if isinstance(value, (str, int, float, bool)) or value is None:
        return value
    return str(value)


def _write_bioemu_runtime_stage(
    *,
    output_dir: Path,
    arrays_dir: Path,
    stage: str,
    **details: Any,
) -> dict[str, Any]:
    """Best-effort live marker for long startup and initial multiseed phases."""

    payload: dict[str, Any] = {
        "summary_kind": "bioemu_latent_nmr_runtime_stage_v1",
        "stage": str(stage),
        "updated_at_unix": float(time.time()),
        "online_trainer_never_runs_ucbshift": True,
        "online_trainer_never_waits_for_offline_ucbshift": True,
    }
    payload.update(
        {str(key): _runtime_stage_json_safe(value) for key, value in details.items()}
    )
    try:
        _save_json_atomic(
            output_dir / "reports" / "runtime_contract" / "bioemu_runtime_stage.json",
            payload,
        )
        _save_json_atomic(arrays_dir / "bioemu_runtime_stage.json", payload)
    except Exception as exc:  # pragma: no cover - marker must not kill training.
        payload["write_status"] = "warning"
        payload["write_exception_type"] = type(exc).__name__
        payload["write_exception"] = str(exc)
    return payload


def _append_jsonl(path: str | Path, payload: dict[str, Any]) -> None:
    with Path(path).open("a", encoding="utf-8") as handle:
        handle.write(json.dumps(payload, sort_keys=True) + "\n")


def _canonical_ready_payload_sha256(payload: dict[str, Any]) -> str:
    canonical_payload = dict(payload)
    canonical_payload.pop("manifest_payload_sha256", None)
    return hashlib.sha256(
        json.dumps(
            canonical_payload,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()


def _file_sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with Path(path).open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def _save_checkpoint(
    *paths: str | Path,
    epoch: int,
    model: nn.Module,
    provider: BioEmuLatentProvider | None = None,
    optimizer: torch.optim.Optimizer,
    config: StudentTrainingConfig,
    metrics: dict[str, Any],
) -> None:
    provider_state = _bioemu_provider_trainable_state_dict(provider)
    payload = {
        "model_state_dict": model.state_dict(),
        "provider_trainable_state_dict": provider_state,
        "provider_trainable_state_keys": sorted(provider_state),
        "optimizer_state_dict": optimizer.state_dict(),
        "config": config.as_dict(),
        "epoch": int(epoch),
        "metrics": metrics,
        "task": "posterior_nmr_bioemu_latent_atlas_v1",
    }
    for path in paths:
        output_path = Path(path)
        output_path.parent.mkdir(parents=True, exist_ok=True)
        torch.save(payload, output_path)


def _save_immutable_checkpoint(
    path: Path,
    *,
    epoch: int,
    model: nn.Module,
    provider: BioEmuLatentProvider | None = None,
    optimizer: torch.optim.Optimizer,
    config: StudentTrainingConfig,
    metrics: dict[str, Any],
) -> dict[str, Any]:
    """Save an epoch checkpoint once for asynchronous offline consumers."""

    path.parent.mkdir(parents=True, exist_ok=True)
    if path.exists():
        return {
            "created": False,
            "path": str(path),
            "checkpoint_sha256": _file_sha256(path),
            "checkpoint_size_bytes": int(path.stat().st_size),
        }
    tmp_path = path.with_name(f"{path.name}.tmp")
    _save_checkpoint(
        tmp_path,
        epoch=epoch,
        model=model,
        provider=provider,
        optimizer=optimizer,
        config=config,
        metrics=metrics,
    )
    tmp_path.replace(path)
    return {
        "created": True,
        "path": str(path),
        "checkpoint_sha256": _file_sha256(path),
        "checkpoint_size_bytes": int(path.stat().st_size),
    }


