    payload["manifest_payload_sha256"] = _canonical_ready_payload_sha256(payload)
    _save_json_atomic(manifest_path, payload)
    ready_tmp = ready_path.with_name(f"{ready_path.name}.tmp")
    ready_tmp.parent.mkdir(parents=True, exist_ok=True)
    ready_tmp.write_text(str(manifest_path) + "\n")
    ready_tmp.replace(ready_path)
    return {"manifest_path": str(manifest_path), "ready_path": str(ready_path)}
